    extern "C" __global__ void gpuwm_compose_pbl_radiation_cumulus(const CArray<float, 1, 1, 1> _raw_a, const CArray<float, 1, 1, 1> _raw_b, const CArray<float, 1, 1, 1> _raw_c, CArray<float, 1, 1, 1> _raw_out, CIndexer<1, 1> _ind) {
      ;
      #pragma unroll 1
      CUPY_FOR(i, _ind.size()) {
        _ind.set(i);
        const float &a = _raw_a[_ind.get()];
const float &b = _raw_b[_ind.get()];
const float &c = _raw_c[_ind.get()];
float &out = _raw_out[_ind.get()];
out = __fadd_rn(__fadd_rn(a, b), c);;
      }
      ;
    }

