// facp/fact are fac00/fac10 (ind0 half) or fac01/fac11 (ind1 half).
// Fortran e.g. lines 6278-6307 (band 7) / 6674-6703 (band 9).
struct RlwSpecFac0609 {
    float f0p, f1p, f2p, f0t, f1t, f2t;
};

