    const int plane = nlev * ncells;
    if (i >= plane) return;
    const int qi = iqv * plane + i;
    // Handoff uses the transported vapor BEFORE the all-species clamp.
    if (handoff) {
        const float dq = monotonic ? mpas_div(mpas_sub(after[qi], before[qi]), dt) : 0.0f;
