// gfortran lowers REAL MIN/MAX to minss/maxss, which return the SECOND
// operand whenever the first does not compare strictly less/greater.  The
// operands are only ever equal when they are the same value (or +-0.0, whose
// sign is erased by the subtraction that consumes the result), so this is a
// faithful mirror of gpuwm/core/noahmp_bareflux.py's _fmin/_fmax rather than
// a load-bearing difference.
__device__ __forceinline__ float f_min(float a, float b) { return (a < b) ? a : b; }
__device__ __forceinline__ float f_max(float a, float b) { return (a > b) ? a : b; }

// Round a double to binary32, INCLUDING into the subnormal range.
//
// `__double2float_rn` flushes a subnormal result to zero on this toolchain --
// measured on sm_120 with CUDA 13.0, and asking for `--ftz=false` does not
// change it, because CuPy appends `-ftz=true` after the caller's options and
// the compiler honours the last occurrence.  The flush is the flag, not the
// SM: the conversion instruction has no flush of its own, so under `-ftz=true`
// the compiler emits an extra multiply after it to produce one, and built
// without the append the same conversion keeps the subnormal.  glibc's
// expf and powf do produce subnormals, gfortran at -O0 leaves MXCSR's FTZ/DAZ
// clear, and `gpuwm.core.noahmp_libm` -- verified against the live glibc 2.39
// over 1,106,247,680 inputs -- produces them too.  So the conversion as
// compiled here is a divergence from the authority in a narrow but reachable
// band:
// expf(x) for x in [-103.616, -87.337), and powf wherever y*log2(x) lands in
// the same place.  ENERGY's RHSUR (:2203) evaluates exp(PSI*GRAV/(RW*TG)) on
// very dry soil and can reach it.
//
// The correctly rounded subnormal is recovered exactly rather than
// approximated: a binary32 subnormal with mantissa bits `m` is exactly
// m * 2^-149, `y * 2^149` is an exact scaling in binary64 for any y in this
// band, and `rint` rounds to nearest with ties to even -- which is the same
// rounding the conversion owes.  m == 2^23 is the carry into the smallest
// normal and its bit pattern 0x00800000 is already that number, so the carry
// needs no special case.
__device__ float nmp_d2f_rn(double y)
{
    double a = fabs(y);
    if (a > 0.0 && a < 1.1754943508222875e-38) {   /* 0x1p-126 */
        double scaled = rint(a * 7.1362384635297994e+44);   /* 2^149 */
        unsigned int m = (unsigned int)scaled;
        unsigned int s = (__double_as_longlong(y) < 0LL) ? 0x80000000u : 0u;
        return __uint_as_float(s | m);
    }
    return __double2float_rn(y);
}

// --------------------------------------------------------------------------
// glibc 2.39 logf  --  sysdeps/ieee754/flt-32/e_logf.c, FMA variant.
// Operation order read off the disassembly of __logf_fma, including the
// single FMA that computes logc + k*Ln2.
// --------------------------------------------------------------------------
__device__ float glibc_logf(float x)
{
    unsigned int ix = __float_as_uint(x);
    if (ix == 0x3F800000u) return 0.0f;           // log(1) == +0

    if ((ix - 0x00800000u) >= (0x7F800000u - 0x00800000u)) {
        if ((ix * 2u) == 0u) return __uint_as_float(0xFF800000u);   // log(0)
        if (ix == 0x7F800000u) return __uint_as_float(0x7F800000u); // log(inf)
        if ((ix & 0x80000000u) || (ix * 2u) >= 0xFF000000u)
            return __uint_as_float(0x7FC00000u);  // negative or NaN -> NaN
        ix = __float_as_uint(FMUL(x, K_P2P23));   // subnormal: * 0x1p23
        ix -= (23u << 23);
    }

    unsigned int tmp = ix - 0x3F330000u;
    unsigned int i = (tmp >> 19) & 15u;
    int k = ((int) tmp) >> 23;                    // arithmetic shift
    unsigned int iz = ix - (tmp & 0xFF800000u);
    double invc = __longlong_as_double(C_LOGF_TAB[2 * i]);
    double logc = __longlong_as_double(C_LOGF_TAB[2 * i + 1]);
    double z = (double) __uint_as_float(iz);

    double ln2 = __longlong_as_double(C_LOGF_MISC[0]);
    double a0 = __longlong_as_double(C_LOGF_MISC[1]);
    double a1 = __longlong_as_double(C_LOGF_MISC[2]);
    double a2 = __longlong_as_double(C_LOGF_MISC[3]);

    double r = DFMA(z, invc, -1.0);
    double y0 = DFMA((double) k, ln2, logc);
    double r2 = DMUL(r, r);
    double y = DFMA(a1, r, a2);
    y = DFMA(r2, a0, y);
    y = DFMA(r2, y, DADD(y0, r));
    return __double2float_rn(y);
}

// --------------------------------------------------------------------------
// glibc 2.39 powf  --  sysdeps/ieee754/flt-32/e_powf.c, FMA variant.
// Only the domain the radiation leaves reach is transcribed: a strictly
// positive normal base and a finite exponent (GROUNDALB's
// MAX(0.01, COSZ) ** 1.7).  Anything else returns NaN rather than a value
// this kernel cannot vouch for.
// --------------------------------------------------------------------------
__device__ double powf_log2_inline(unsigned int ix)
{
    unsigned int tmp = ix - 0x3F330000u;
    unsigned int i = (tmp >> 19) & 15u;
    unsigned int top = tmp & 0xFF800000u;
    unsigned int iz = ix - top;
    int k = ((int) top) >> 23;
    double invc = __longlong_as_double(C_POWF_LOG2_TAB[2 * i]);
    double logc = __longlong_as_double(C_POWF_LOG2_TAB[2 * i + 1]);
    double z = (double) __uint_as_float(iz);

    double r = DFMA(z, invc, -1.0);
    double y0 = DADD(logc, (double) k);

    double a0 = __longlong_as_double(C_POWF_LOG2_POLY[0]);
    double a1 = __longlong_as_double(C_POWF_LOG2_POLY[1]);
    double a2 = __longlong_as_double(C_POWF_LOG2_POLY[2]);
    double a3 = __longlong_as_double(C_POWF_LOG2_POLY[3]);
    double a4 = __longlong_as_double(C_POWF_LOG2_POLY[4]);

    double r2 = DMUL(r, r);
    double y = DFMA(a0, r, a1);
    double p = DFMA(a2, r, a3);
    double r4 = DMUL(r2, r2);
    double q = DFMA(a4, r, y0);
    q = DFMA(p, r2, q);
    y = DFMA(y, r4, q);
    return y;
}

__device__ float powf_exp2_inline(double xd, unsigned long long sign_bias)
{
    double shift = __longlong_as_double(C_EXP2F_MISC[0]);
    double kd = DADD(xd, shift);
    unsigned long long ki = (unsigned long long) __double_as_longlong(kd);
    kd = DSUB(kd, shift);
    double r = DSUB(xd, kd);

    unsigned long long t = C_EXP2F_TAB[ki & 31ULL];
    unsigned long long ski = ki + sign_bias;
    t += (ski << (52 - 5));
    double s = __longlong_as_double((long long) t);
    double c0 = __longlong_as_double(C_EXP2F_POLY[0]);
    double c1 = __longlong_as_double(C_EXP2F_POLY[1]);
    double c2 = __longlong_as_double(C_EXP2F_POLY[2]);
    double z = DFMA(c0, r, c1);
    double r2 = DMUL(r, r);
    double y = DFMA(c2, r, 1.0);
    y = DFMA(z, r2, y);
    y = DMUL(y, s);
    return nmp_d2f_rn(y);
}

__device__ float glibc_powf(float x, float y)
{
    unsigned int ix = __float_as_uint(x);
    unsigned int iy = __float_as_uint(y);
    if ((ix - 0x00800000u) >= 0x7F000000u || (((2u * iy) - 1u) >= 0xFEFFFFFFu))
        return __uint_as_float(0x7FC00000u);   // outside the ported domain

    double logx = powf_log2_inline(ix);
    double ylogx = DMUL((double) y, logx);
    unsigned long long ab = (unsigned long long) __double_as_longlong(ylogx);
    unsigned long long lim = ((unsigned long long) __double_as_longlong(126.0)) >> 47;
    if (((ab >> 47) & 0xFFFFULL) >= lim) {
        if (ylogx > __longlong_as_double(C_LIMITS[2]))
            return __uint_as_float(0x7F800000u);
        if (ylogx <= -150.0) return 0.0f;
    }
    return powf_exp2_inline(ylogx, 0ULL);
}

// --------------------------------------------------------------------------
// glibc 2.39 atanf  --  sysdeps/ieee754/flt-32/s_atanf.c (fdlibm kernel).
// Unlike logf/powf, atanf is NOT an ifunc in libm.so.6, so there is no -mfma
// rebuild of it: every operation is a plain float32 multiply or add and none
// of them may be contracted.  Hence FMUL/FADD/FSUB throughout, never FMA.
// --------------------------------------------------------------------------
__device__ float glibc_atanf(float x)
{
    unsigned int hx = __float_as_uint(x);
    unsigned int ix = hx & 0x7FFFFFFFu;
    int signed_hx = (int) hx;
    int id;

    if (ix >= 0x4C000000u) {                 // |x| >= 2^25
        if (ix > 0x7F800000u) return FADD(x, x);              // NaN
        if (signed_hx > 0)
            return FADD(__uint_as_float(C_ATAN[3]), __uint_as_float(C_ATAN[7]));
        return FSUB(FSUB(K_ZERO, __uint_as_float(C_ATAN[3])),
                    __uint_as_float(C_ATAN[7]));
    }

    if (ix < 0x3EE00000u) {                  // |x| < 0.4375
        if (ix < 0x31000000u) return x;      // |x| < 2^-29: atan(x) == x
        id = -1;
    } else {
        x = __uint_as_float(ix);             // fabsf(x)
        if (ix < 0x3F980000u) {              // |x| < 1.1875
            if (ix < 0x3F300000u) {          // 7/16 <= |x| < 11/16
                id = 0;
                x = FDIV(FSUB(FMUL(K_TWO, x), K_ONE), FADD(K_TWO, x));
            } else {                         // 11/16 <= |x| < 19/16
                id = 1;
                x = FDIV(FSUB(x, K_ONE), FADD(x, K_ONE));
            }
        } else {
            if (ix < 0x401C0000u) {          // |x| < 2.4375
                id = 2;
                x = FDIV(FSUB(x, K_1P5), FADD(K_ONE, FMUL(K_1P5, x)));
            } else {                         // 2.4375 <= |x| < 2^25
                id = 3;
                x = FDIV(K_N1, x);
            }
        }
    }

    float z = FMUL(x, x);
    float w = FMUL(z, z);
#define AT(i) __uint_as_float(C_ATAN[8 + (i)])
    float s1 = FMUL(w, AT(10));
    s1 = FMUL(w, FADD(AT(8), s1));
    s1 = FMUL(w, FADD(AT(6), s1));
    s1 = FMUL(w, FADD(AT(4), s1));
    s1 = FMUL(w, FADD(AT(2), s1));
    s1 = FMUL(z, FADD(AT(0), s1));
    float s2 = FMUL(w, AT(9));
    s2 = FMUL(w, FADD(AT(7), s2));
    s2 = FMUL(w, FADD(AT(5), s2));
    s2 = FMUL(w, FADD(AT(3), s2));
    s2 = FMUL(w, FADD(AT(1), s2));
#undef AT
    float s = FADD(s1, s2);
    if (id < 0) return FSUB(x, FMUL(x, s));
    float r = FSUB(__uint_as_float(C_ATAN[id]),
                   FSUB(FSUB(FMUL(x, s), __uint_as_float(C_ATAN[4 + id])), x));
    return (signed_hx < 0) ? FSUB(K_ZERO, r) : r;
}

// --------------------------------------------------------------------------
// gfortran expands REAL**3 and REAL**4 (integer constant exponents) into
// __builtin_powi, which multiplies rather than calling powf.
// --------------------------------------------------------------------------
__device__ __forceinline__ float powi3(float x)
{
    float x2 = FMUL(x, x);
    return FMUL(x2, x);
}

__device__ __forceinline__ float powi4(float x)
{
    float x2 = FMUL(x, x);
    return FMUL(x2, x2);
}

// --------------------------------------------------------------------------
// ESAT -- module_sf_noahmplsm.F:4952-5001
// base 0 -> ESW (water), 7 -> ESI (ice), 14 -> DESW, 21 -> DESI
// --------------------------------------------------------------------------
__device__ __forceinline__ float esat_poly(int base, float t)
{
#define C(i) __uint_as_float(C_ESAT[base + (i)])
    float y = FADD(C(5), FMUL(t, C(6)));
    y = FADD(C(4), FMUL(t, y));
    y = FADD(C(3), FMUL(t, y));
    y = FADD(C(2), FMUL(t, y));
    y = FADD(C(1), FMUL(t, y));
    y = FADD(C(0), FMUL(t, y));
#undef C
    return FMUL(K_HUND, y);
}

// --------------------------------------------------------------------------
// SFCDIF1 -- module_sf_noahmplsm.F:4583-4743, OPT_SFC == 1.
// The struct is the INOUT block BARE_FLUX threads through its five
// stability iterations.
// --------------------------------------------------------------------------
struct Sfcdif1State {
    float moz, fm, fh, fm2, fh2, fv, cm, ch, ch2;
    int mozsgn;
};

__device__ void d_sfcdif1(Sfcdif1State *s, int it, float sfctmp, float rhoair,
                          float h, float qair, float zlvl, float zpd,
                          float z0m, float z0h, float ur, float mpe)
{
    float mozold = s->moz;

    float tmpcm = glibc_logf(FDIV(FSUB(zlvl, zpd), z0m));
    float tmpch = glibc_logf(FDIV(FSUB(zlvl, zpd), z0h));
    float tmpcm2 = glibc_logf(FDIV(FADD(K_TWO, z0m), z0m));
    float tmpch2 = glibc_logf(FDIV(FADD(K_TWO, z0h), z0h));

    float mol, moz2;
    if (it == 1) {
        s->fv = K_ZERO;
        s->moz = K_ZERO;
        mol = K_ZERO;
        moz2 = K_ZERO;
    } else {
        float tvir = FMUL(FADD(K_ONE, FMUL(K_P61, qair)), sfctmp);
        float tmp1 = FDIV(FMUL(FMUL(K_VKC, FDIV(K_GRAV, tvir)), h),
                          FMUL(rhoair, K_CPAIR));
        if (fabsf(tmp1) <= mpe) tmp1 = mpe;
        mol = FDIV(FMUL(K_N1, powi3(s->fv)), tmp1);
        s->moz = f_min(FDIV(FSUB(zlvl, zpd), mol), K_ONE);
        moz2 = f_min(FDIV(FADD(K_TWO, z0h), mol), K_ONE);
    }

    if (FMUL(mozold, s->moz) < K_ZERO) s->mozsgn += 1;
    if (s->mozsgn >= 2) {
        s->moz = K_ZERO;
        s->fm = K_ZERO;
        s->fh = K_ZERO;
        moz2 = K_ZERO;
        s->fm2 = K_ZERO;
        s->fh2 = K_ZERO;
    }

    float fmnew, fhnew, fm2new, fh2new;
    if (s->moz < K_ZERO) {
        float tmp1 = glibc_powf(FSUB(K_ONE, FMUL(K_SIXTEEN, s->moz)), K_QUARTER);
        float tmp2 = glibc_logf(FDIV(FADD(K_ONE, FMUL(tmp1, tmp1)), K_TWO));
        float tmp3 = glibc_logf(FDIV(FADD(K_ONE, tmp1), K_TWO));
        fmnew = FADD(FSUB(FADD(FMUL(K_TWO, tmp3), tmp2),
                          FMUL(K_TWO, glibc_atanf(tmp1))), K_PIO2);
        fhnew = FMUL(K_TWO, tmp2);

        float tmp12 = glibc_powf(FSUB(K_ONE, FMUL(K_SIXTEEN, moz2)), K_QUARTER);
        float tmp22 = glibc_logf(FDIV(FADD(K_ONE, FMUL(tmp12, tmp12)), K_TWO));
        float tmp32 = glibc_logf(FDIV(FADD(K_ONE, tmp12), K_TWO));
        fm2new = FADD(FSUB(FADD(FMUL(K_TWO, tmp32), tmp22),
                           FMUL(K_TWO, glibc_atanf(tmp12))), K_PIO2);
        fh2new = FMUL(K_TWO, tmp22);
    } else {
        fmnew = FMUL(K_N5, s->moz);
        fhnew = fmnew;
        fm2new = FMUL(K_N5, moz2);
        fh2new = fm2new;
    }

    if (it == 1) {
        s->fm = fmnew;
        s->fh = fhnew;
        s->fm2 = fm2new;
        s->fh2 = fh2new;
    } else {
        s->fm = FMUL(K_HALF, FADD(s->fm, fmnew));
        s->fh = FMUL(K_HALF, FADD(s->fh, fhnew));
        s->fm2 = FMUL(K_HALF, FADD(s->fm2, fm2new));
        s->fh2 = FMUL(K_HALF, FADD(s->fh2, fh2new));
    }

    s->fh = f_min(s->fh, FMUL(K_P9, tmpch));
    s->fm = f_min(s->fm, FMUL(K_P9, tmpcm));
    s->fh2 = f_min(s->fh2, FMUL(K_P9, tmpch2));
    s->fm2 = f_min(s->fm2, FMUL(K_P9, tmpcm2));

    float cmfm = FSUB(tmpcm, s->fm);
    float chfh = FSUB(tmpch, s->fh);
    float cm2fm2 = FSUB(tmpcm2, s->fm2);
    float ch2fh2 = FSUB(tmpch2, s->fh2);
    if (fabsf(cmfm) <= mpe) cmfm = mpe;
    if (fabsf(chfh) <= mpe) chfh = mpe;
    if (fabsf(cm2fm2) <= mpe) cm2fm2 = mpe;
    if (fabsf(ch2fh2) <= mpe) ch2fh2 = mpe;

    s->cm = FDIV(FMUL(K_VKC, K_VKC), FMUL(cmfm, cmfm));
    // WRF divides CH by CMFM*CHFH, not CHFH*CHFH.  Not a typo to tidy up.
    s->ch = FDIV(FMUL(K_VKC, K_VKC), FMUL(cmfm, chfh));

    s->fv = FMUL(ur, FSQRT(s->cm));
    s->ch2 = FDIV(FMUL(K_VKC, s->fv), ch2fh2);
    (void) mol;
    (void) cm2fm2;
}

// --------------------------------------------------------------------------
// BARE_FLUX -- module_sf_noahmplsm.F:4174-4479
//
// in[53] per column, in the order
//   dt sag lwdn ur uu vv sfctmp thair qair eair rhoair snowh zlvl zpd z0m
//   fsno emg rsurf lathea gamma rhsur q2 pahb dx dz8w qc psfc sfcprs
//   tgb cm ch qsfc  dzsnso(-2..4) stc(-2..4) df(-2..4)
// ii[5] per column: isnow ivgtyp iloc jloc iurban
// out[13] per column:
//   tgb cm ch qsfc tauxb tauyb irb shb evb ghb t2mb q2b ehb2
//
// dt, thair, q2, dx, dz8w, qc, sfcprs, fsno, the incoming cm/ch/qsfc,
// ivgtyp, iloc and jloc are accepted and never read: under opt_sfc=1 and
// opt_stc=1 no live statement references them.
// --------------------------------------------------------------------------
#define NITERB 5
#define NSNOW 3

__device__ void d_bare_flux(const float *p, const int *q, float *o)
{
    const float sag = p[1], lwdn = p[2], ur = p[3], uu = p[4], vv = p[5];
    const float sfctmp = p[6], qair = p[8], eair = p[9], rhoair = p[10];
    const float snowh = p[11], zlvl = p[12], zpd = p[13], z0m = p[14];
    const float emg = p[16], rsurf = p[17], lathea = p[18], gamma = p[19];
    const float rhsur = p[20], pahb = p[22], psfc = p[26];
    const float *dzsnso = p + 32, *stc = p + 39, *df = p + 46;
    const int isnow = q[0];
    const int urban_flag = q[4];

    // Fortran declares these arrays (-NSNOW+1:NSOIL), so element k lives at
    // index k + NSNOW - 1 of the packed row.
    const int kk = isnow + 1 + NSNOW - 1;

    float tgb = p[28];
    float h = K_ZERO;

    Sfcdif1State s;
    s.moz = K_ZERO;
    s.mozsgn = 0;
    s.fm = K_ZERO;
    s.fh = K_ZERO;
    s.fm2 = K_ZERO;
    s.fh2 = K_ZERO;
    s.fv = K_P1;
    s.cm = K_ZERO;
    s.ch = K_ZERO;
    s.ch2 = K_ZERO;

    const float cir = FMUL(emg, K_SB);
    const float cgh = FDIV(FMUL(K_TWO, df[kk]), dzsnso[kk]);

    float csh = K_ZERO, cev = K_ZERO, estg = K_ZERO, ehb = K_ZERO;
    float irb = K_ZERO, shb = K_ZERO, evb = K_ZERO, ghb = K_ZERO;
    float qsfc = p[31];
    float z0h = z0m;

    for (int it = 1; it <= NITERB; ++it) {
        z0h = z0m;                       // both arms of the ITER==1 test

        d_sfcdif1(&s, it, sfctmp, rhoair, h, qair, zlvl, zpd, z0m, z0h,
                  ur, K_MPE);

        float rahb = f_max(K_ONE, FDIV(K_ONE, FMUL(s.ch, ur)));
        float rawb = rahb;
        ehb = FDIV(K_ONE, rahb);

        float t = f_min(K_P50, f_max(K_N50, FSUB(tgb, K_TFRZ)));
        float destg;
        if (t > K_ZERO) {
            estg = esat_poly(0, t);
            destg = esat_poly(14, t);
        } else {
            estg = esat_poly(7, t);
            destg = esat_poly(21, t);
        }

        csh = FDIV(FMUL(rhoair, K_CPAIR), rahb);
        cev = FDIV(FDIV(FMUL(rhoair, K_CPAIR), gamma), FADD(rsurf, rawb));

        irb = FSUB(FMUL(cir, powi4(tgb)), FMUL(emg, lwdn));
        shb = FMUL(csh, FSUB(tgb, sfctmp));
        evb = FMUL(cev, FSUB(FMUL(estg, rhsur), eair));
        ghb = FMUL(cgh, FSUB(tgb, stc[kk]));

        float b = FADD(FSUB(FSUB(FSUB(FSUB(sag, irb), shb), evb), ghb), pahb);
        float cir4t3 = FMUL(FMUL(K_FOUR, cir), powi3(tgb));
        float a = FADD(FADD(FADD(cir4t3, csh), FMUL(cev, destg)), cgh);
        float dtg = FDIV(b, a);

        irb = FADD(irb, FMUL(cir4t3, dtg));
        shb = FADD(shb, FMUL(csh, dtg));
        evb = FADD(evb, FMUL(FMUL(cev, destg), dtg));
        ghb = FADD(ghb, FMUL(cgh, dtg));

        tgb = FADD(tgb, dtg);
        h = FMUL(csh, FSUB(tgb, sfctmp));

        t = f_min(K_P50, f_max(K_N50, FSUB(tgb, K_TFRZ)));
        estg = (t > K_ZERO) ? esat_poly(0, t) : esat_poly(7, t);
        float er = FMUL(estg, rhsur);
        qsfc = FDIV(FMUL(K_P622, er), FSUB(psfc, FMUL(K_P378, er)));
        // QFX is computed here in WRF and never used again; omitted.
    }

    // opt_stc == 1 snow reset.  The opt_stc == 3 blend is dead and absent.
    if (snowh > K_P05 && tgb > K_TFRZ) {
        tgb = K_TFRZ;
        irb = FSUB(FMUL(cir, powi4(tgb)), FMUL(emg, lwdn));
        shb = FMUL(csh, FSUB(tgb, sfctmp));
        evb = FMUL(cev, FSUB(FMUL(estg, rhsur), eair));
        ghb = FSUB(FADD(sag, pahb), FADD(FADD(irb, shb), evb));
    }

    float tauxb = FSUB(K_ZERO, FMUL(FMUL(FMUL(rhoair, s.cm), ur), uu));
    float tauyb = FSUB(K_ZERO, FMUL(FMUL(FMUL(rhoair, s.cm), ur), vv));

    // opt_sfc == 1 2 m diagnostics.  WRF assigns EHB2 twice; the first
    // assignment is dead and is not reproduced.
    float ehb2 = FDIV(FMUL(s.fv, K_VKC),
                      FSUB(glibc_logf(FDIV(FADD(K_TWO, z0h), z0h)), s.fh2));
    float cq2b = ehb2;
    float t2mb, q2b;
    if (ehb2 < K_E5) {
        t2mb = tgb;
        q2b = qsfc;
    } else {
        t2mb = FSUB(tgb, FDIV(FMUL(FDIV(shb, FMUL(rhoair, K_CPAIR)), K_ONE),
                              ehb2));
        q2b = FSUB(qsfc, FMUL(FDIV(evb, FMUL(lathea, rhoair)),
                              FADD(FDIV(K_ONE, cq2b), rsurf)));
    }
    if (urban_flag) q2b = qsfc;

    o[0] = tgb;
    o[1] = s.cm;
    o[2] = ehb;          // "update CH": BARE_FLUX overwrites CH with EHB
    o[3] = qsfc;
    o[4] = tauxb;
    o[5] = tauyb;
    o[6] = irb;
    o[7] = shb;
    o[8] = evb;
    o[9] = ghb;
    o[10] = t2mb;
    o[11] = q2b;
    o[12] = ehb2;
}

extern "C" __global__ void noahmp_bare_flux(const float *in, const int *ii,
                                            float *out, int n)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) d_bare_flux(in + 53 * i, ii + 5 * i, out + 13 * i);
}

// Probe kernels.  They exist so the device acceptance test can show that the
// __constant__ tables survived ptxas and that the glibc kernels themselves --
// not merely the leaf built on top of them -- are bitwise right on the
// device.  Without them a table mis-fold could hide inside a leaf that
// happens not to reach the affected table entry.
extern "C" __global__ void noahmp_bareflux_libm_probe(const float *x,
                                                      float *out, int n)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        out[3 * i + 0] = glibc_logf(x[i]);
        out[3 * i + 1] = glibc_atanf(x[i]);
        out[3 * i + 2] = glibc_powf(x[i], K_QUARTER);
    }
}

extern "C" __global__ void noahmp_bareflux_esat_probe(const float *t,
                                                      float *out, int n)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        out[4 * i + 0] = esat_poly(0, t[i]);
        out[4 * i + 1] = esat_poly(7, t[i]);
        out[4 * i + 2] = esat_poly(14, t[i]);
        out[4 * i + 3] = esat_poly(21, t[i]);
    }
}

#ifndef MPAS_FTZ_FALLBACK_ENABLED
#define MPAS_FTZ_FALLBACK_ENABLED 1
#endif

__device__ __forceinline__ unsigned int mpas_f32_magnitude_bits(
    const float value)
{
    return __float_as_uint(value) & 0x7fffffffu;
}

__device__ __forceinline__ bool mpas_is_subnormal_f32(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int magnitude = mpas_f32_magnitude_bits(value);
    return magnitude != 0u && (magnitude & 0x7f800000u) == 0u;
#else
    return false;
#endif
}

// A plain float/double cast is one of the measured DAZ mechanisms, so decode
// a subnormal float from its integer mantissa instead.
__device__ __forceinline__ double mpas_f32_to_f64_ieee(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int bits = __float_as_uint(value);
    const unsigned int magnitude = bits & 0x7fffffffu;
    if (magnitude != 0u && (magnitude & 0x7f800000u) == 0u) {
        const double decoded = ldexp(
            (double)(magnitude & 0x007fffffu), -149);
        return (bits & 0x80000000u) != 0u ? -decoded : decoded;
    }
#endif
    return (double)value;
}

// __double2float_rn flushes an FP32-subnormal result on the certified route,
// so pack that narrow result from the rounded integer mantissa.
__device__ __forceinline__ float mpas_f64_to_f32_ieee(const double value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const double magnitude = fabs(value);
    if (magnitude > 0.0 && magnitude < 1.1754943508222875e-38) {
        const double scaled = rint(
            magnitude * 7.1362384635297994e+44);  // 2^149
        const unsigned int mantissa = (unsigned int)scaled;
        const unsigned int sign =
            (__double_as_longlong(value) < 0LL) ? 0x80000000u : 0u;
        return __uint_as_float(sign | mantissa);
    }
#endif
    return __double2float_rn(value);
}

__device__ __forceinline__ float mpas_add(
    const float left, const float right)
{
    const float ordinary = left + right;
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int result_magnitude = mpas_f32_magnitude_bits(ordinary);
    const unsigned int result_exponent = result_magnitude >> 23;
    // A result at exponent field >=25 cannot have been rounded differently
    // by an FP32 subnormal operand, which is then below half an ulp.
    if (result_exponent > 24u) return ordinary;
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) + mpas_f32_to_f64_ieee(right));
    }
#endif
#if MPAS_FTZ_FALLBACK_ENABLED
    // Two normal binary32 values can cancel into the subnormal range only
    // while both exponent fields are <= 23; above that, one ulp is already
    // at least the smallest normal value.
    if (left_exponent <= 23u && right_exponent <= 23u
            && result_exponent == 0u
            && left_magnitude != right_magnitude
            && left_magnitude != 0u && right_magnitude != 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) + mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_sub(
    const float left, const float right)
{
    const float ordinary = left - right;
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int result_magnitude = mpas_f32_magnitude_bits(ordinary);
    const unsigned int result_exponent = result_magnitude >> 23;
    if (result_exponent > 24u) return ordinary;
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) - mpas_f32_to_f64_ieee(right));
    }
#endif
#if MPAS_FTZ_FALLBACK_ENABLED
    if (left_exponent <= 23u && right_exponent <= 23u
            && result_exponent == 0u
            && left_magnitude != right_magnitude
            && left_magnitude != 0u && right_magnitude != 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) - mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_mul(
    const float left, const float right)
{
    const float ordinary = left * right;
#if MPAS_FTZ_FALLBACK_ENABLED
    // A normal finite/overflow result proves neither operand was lost to DAZ
    // and no FTZ result occurred.  Inspect operands only on the rare zero or
    // subnormal-result envelope.
    if ((mpas_f32_magnitude_bits(ordinary) & 0x7f800000u) == 0u) {
        const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
        const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
        if (left_magnitude != 0u && right_magnitude != 0u) {
            return mpas_f64_to_f32_ieee(
                mpas_f32_to_f64_ieee(left) * mpas_f32_to_f64_ieee(right));
        }
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_div(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) / mpas_f32_to_f64_ieee(right));
    }
#endif
    const float ordinary = left / right;
#if MPAS_FTZ_FALLBACK_ENABLED
    if (left_magnitude != 0u && right_magnitude != 0u
            && left_exponent + 126u <= right_exponent
            && (mpas_f32_magnitude_bits(ordinary) & 0x7f800000u) == 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) / mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_sqrt(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(value)) {
        return mpas_f64_to_f32_ieee(sqrt(mpas_f32_to_f64_ieee(value)));
    }
#endif
    return sqrtf(value);
}

__device__ __forceinline__ float mpas_abs(const float value)
{
    return __uint_as_float(__float_as_uint(value) & 0x7fffffffu);
}

__device__ __forceinline__ float mpas_copysign(
    const float magnitude, const float sign)
{
    return __uint_as_float(
        (__float_as_uint(magnitude) & 0x7fffffffu)
        | (__float_as_uint(sign) & 0x80000000u));
}

__device__ __forceinline__ float mpas_min(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(left) || mpas_is_subnormal_f32(right)) {
        return mpas_f32_to_f64_ieee(right) < mpas_f32_to_f64_ieee(left)
            ? right : left;
    }
#endif
    return fminf(left, right);
}

__device__ __forceinline__ float mpas_max(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(left) || mpas_is_subnormal_f32(right)) {
        return mpas_f32_to_f64_ieee(right) > mpas_f32_to_f64_ieee(left)
            ? right : left;
    }
#endif
    return fmaxf(left, right);
}


/* Level-independent kernels walk a flat (level, owner) element index, owner
   fastest, in a grid-stride loop; each element runs the former per-owner
   loop body for its level unchanged, so the launch geometry is not in the
   arithmetic.  The forecast launches one thread per element. */
#define HORIZONTAL_ELEMENT_LOOP(total) \
    for (int element = blockDim.x * blockIdx.x + threadIdx.x; \
         element < (total); element += gridDim.x * blockDim.x)
__device__ __forceinline__ int lidx(const int k, const int i, const int n) {
    return k * n + i;
}

__device__ __forceinline__ float cell_sign(
    const int cell, const int edge, const int* cells_on_edge
) {
    return cells_on_edge[2 * edge] == cell ? 1.0f : -1.0f;
}

__device__ __forceinline__ float vertex_sign(
    const int vertex, const int edge, const int* vertices_on_edge
) {
    return vertices_on_edge[2 * edge + 1] == vertex ? 1.0f : -1.0f;
}

__device__ __forceinline__ int kite_slot(
    const int vertex,
    const int cell,
    const int* cells_on_vertex,
    const int vertex_degree
) {
    for (int slot = 0; slot < vertex_degree; ++slot) {
        if (cells_on_vertex[vertex * vertex_degree + slot] == cell) return slot;
    }
    return -1;
}

extern "C" __global__ void recover_edge_f32(
    const float* rho,
    const float* rho_u,
    const float* dc_edge,
    const float* dv_edge,
    const int* cells_on_edge,
    const int nlev,
    const int ncells,
    const int nedges,
    float* normal_velocity,
    float* rho_edge,
    float* ke_edge
) {
    const int edge = blockDim.x * blockIdx.x + threadIdx.x;
    if (edge >= nedges) return;
    const int cell0 = cells_on_edge[2 * edge];
    const int cell1 = cells_on_edge[2 * edge + 1];
    for (int k = 0; k < nlev; ++k) {
        const int tid = lidx(k, edge, nedges);
        const float edge_rho = mpas_mul(0.5f, mpas_add(
            rho[lidx(k, cell0, ncells)], rho[lidx(k, cell1, ncells)]
        ));
        const float u = mpas_div(rho_u[tid], edge_rho);
        rho_edge[tid] = edge_rho;
        normal_velocity[tid] = u;
        // Native MPAS: efac*u**2. Round the square before the area product.
        ke_edge[tid] = mpas_mul(mpas_mul(
            dc_edge[edge], dv_edge[edge]), mpas_mul(u, u));
    }
}

extern "C" __global__ void edge_fields_from_saved_u_f32(
    const float* rho,
    const float* normal_velocity,
    const float* dc_edge,
    const float* dv_edge,
    const int* cells_on_edge,
    const int nlev,
    const int ncells,
    const int nedges,
    float* rho_edge,
    float* ke_edge
) {
    const int edge = blockDim.x * blockIdx.x + threadIdx.x;
    if (edge >= nedges) return;
    const int cell0 = cells_on_edge[2 * edge];
    const int cell1 = cells_on_edge[2 * edge + 1];
    for (int k = 0; k < nlev; ++k) {
        const int tid = lidx(k, edge, nedges);
        const float edge_rho = mpas_mul(0.5f, mpas_add(
            rho[lidx(k, cell0, ncells)], rho[lidx(k, cell1, ncells)]
        ));
        const float u = normal_velocity[tid];
        rho_edge[tid] = edge_rho;
        // Native MPAS: efac*u**2. Round the square before the area product.
        ke_edge[tid] = mpas_mul(mpas_mul(
            dc_edge[edge], dv_edge[edge]), mpas_mul(u, u));
    }
}

extern "C" __global__ void tangential_velocity_f32(
    const float* normal_velocity,
    const int* edges_on_edge,
    const int* n_edges_on_edge,
    const float* weights_on_edge,
    const int nlev,
    const int nedges,
    const int max_edges2,
    float* tangential_velocity
) {
    HORIZONTAL_ELEMENT_LOOP(nlev * nedges) {
        const int edge = element % nedges;
        const int k = element / nedges;
        const int count = n_edges_on_edge[edge];
        float value = 0.0f;
        for (int slot = 0; slot < count; ++slot) {
            const int offset = edge * max_edges2 + slot;
            const int neighbor = edges_on_edge[offset];
            value = mpas_add(value, mpas_mul(weights_on_edge[offset],
                normal_velocity[lidx(k, neighbor, nedges)]));
        }
        tangential_velocity[lidx(k, edge, nedges)] = value;
    }
}

extern "C" __global__ void vertex_diagnostics_f32(
    const float* normal_velocity,
    const float* ke_edge,
    const int* edges_on_vertex,
    const int* vertices_on_edge,
    const float* dc_edge,
    const float* area_triangle,
    const float* f_vertex,
    const int nlev,
    const int nedges,
    const int nvertices,
    const int vertex_degree,
    float* vorticity,
    float* ke_vertex,
    float* pv_vertex
) {
    const int vertex = blockDim.x * blockIdx.x + threadIdx.x;
    if (vertex >= nvertices) return;
    for (int k = 0; k < nlev; ++k) {
        float vort = 0.0f;
        float ke = 0.0f;
        for (int slot = 0; slot < vertex_degree; ++slot) {
            const int edge = edges_on_vertex[vertex * vertex_degree + slot];
            if (edge < 0) continue;
            vort = mpas_add(vort, mpas_mul(mpas_mul(
                vertex_sign(vertex, edge, vertices_on_edge), dc_edge[edge]),
                normal_velocity[lidx(k, edge, nedges)]));
            ke = mpas_add(ke, mpas_mul(
                0.25f, ke_edge[lidx(k, edge, nedges)]));
        }
        vort = mpas_div(vort, area_triangle[vertex]);
        ke = mpas_div(ke, area_triangle[vertex]);
        const int tid = lidx(k, vertex, nvertices);
        vorticity[tid] = vort;
        ke_vertex[tid] = ke;
        pv_vertex[tid] = mpas_add(f_vertex[vertex], vort);
    }
}

extern "C" __global__ void cell_diagnostics_f32(
    const float* normal_velocity,
    const float* ke_edge,
    const float* ke_vertex,
    const int* edges_on_cell,
    const int* n_edges_on_cell,
    const int* cells_on_edge,
    const int* vertices_on_cell,
    const int* cells_on_vertex,
    const float* dv_edge,
    const float* area_cell,
    const float* kite_areas,
    const int nlev,
    const int ncells,
    const int nedges,
    const int nvertices,
    const int max_edges,
    const int vertex_degree,
    float* divergence,
    float* kinetic_energy
) {
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    const int count = n_edges_on_cell[cell];
    const float inv_area = 1.0f / area_cell[cell];
    for (int k = 0; k < nlev; ++k) {
        float div = 0.0f;
        float ke = 0.0f;
        for (int slot = 0; slot < count; ++slot) {
            const int edge = edges_on_cell[cell * max_edges + slot];
            div = mpas_add(div, mpas_mul(mpas_mul(
                cell_sign(cell, edge, cells_on_edge), dv_edge[edge]),
                normal_velocity[lidx(k, edge, nedges)]));
            ke = mpas_add(ke, mpas_mul(
                0.25f, ke_edge[lidx(k, edge, nedges)]));
        }
        div = mpas_mul(div, inv_area);
        ke = mpas_mul(ke, inv_area);
        ke = mpas_mul(ke, 0.625f);
        for (int slot = 0; slot < count; ++slot) {
            const int vertex = vertices_on_cell[cell * max_edges + slot];
            const int kite = kite_slot(
                vertex, cell, cells_on_vertex, vertex_degree
            );
            if (kite >= 0) {
                ke = mpas_add(ke, mpas_mul(mpas_mul(mpas_mul(
                    0.375f, kite_areas[vertex * vertex_degree + kite]),
                    ke_vertex[lidx(k, vertex, nvertices)]), inv_area));
            }
        }
        const int tid = lidx(k, cell, ncells);
        divergence[tid] = div;
        kinetic_energy[tid] = ke;
    }
}

extern "C" __global__ void pv_edge_base_f32(
    const float* pv_vertex,
    const int* vertices_on_edge,
    const int nlev,
    const int nedges,
    const int nvertices,
    float* pv_edge
) {
    const int edge = blockDim.x * blockIdx.x + threadIdx.x;
    if (edge >= nedges) return;
    const int vertex0 = vertices_on_edge[2 * edge];
    const int vertex1 = vertices_on_edge[2 * edge + 1];
    for (int k = 0; k < nlev; ++k) {
        pv_edge[lidx(k, edge, nedges)] = mpas_mul(0.5f, mpas_add(
            pv_vertex[lidx(k, vertex0, nvertices)],
            pv_vertex[lidx(k, vertex1, nvertices)]));
    }
}

extern "C" __global__ void pv_cell_f32(
    const float* pv_vertex,
    const int* vertices_on_cell,
    const int* n_edges_on_cell,
    const int* cells_on_vertex,
    const float* kite_areas,
    const float* area_cell,
    const int nlev,
    const int ncells,
    const int nvertices,
    const int max_edges,
    const int vertex_degree,
    float* pv_cell
) {
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    const int count = n_edges_on_cell[cell];
    for (int k = 0; k < nlev; ++k) {
        float value = 0.0f;
        for (int slot = 0; slot < count; ++slot) {
            const int vertex = vertices_on_cell[cell * max_edges + slot];
            const int kite = kite_slot(
                vertex, cell, cells_on_vertex, vertex_degree
            );
            if (kite >= 0) {
                value = mpas_add(value, mpas_div(mpas_mul(
                    kite_areas[vertex * vertex_degree + kite],
                    pv_vertex[lidx(k, vertex, nvertices)]), area_cell[cell]));
            }
        }
        pv_cell[lidx(k, cell, ncells)] = value;
    }
}

extern "C" __global__ void pv_apvm_f32(
    const float* normal_velocity,
    const float* tangential_velocity,
    const float* pv_vertex,
    const float* pv_cell,
    const int* vertices_on_edge,
    const int* cells_on_edge,
    const float* dc_edge,
    const float* dv_edge,
    const float scale,
    const int nlev,
    const int ncells,
    const int nedges,
    const int nvertices,
    float* pv_edge,
    float* grad_pv_normal,
    float* grad_pv_tangential
) {
    const int edge = blockDim.x * blockIdx.x + threadIdx.x;
    if (edge >= nedges) return;
    const int vertex0 = vertices_on_edge[2 * edge];
    const int vertex1 = vertices_on_edge[2 * edge + 1];
    const int cell0 = cells_on_edge[2 * edge];
    const int cell1 = cells_on_edge[2 * edge + 1];
    for (int k = 0; k < nlev; ++k) {
        const int tid = lidx(k, edge, nedges);
        const float grad_t = mpas_div(mpas_sub(
            pv_vertex[lidx(k, vertex1, nvertices)],
            pv_vertex[lidx(k, vertex0, nvertices)]), dv_edge[edge]);
        const float grad_n = mpas_div(mpas_sub(
            pv_cell[lidx(k, cell1, ncells)],
            pv_cell[lidx(k, cell0, ncells)]), dc_edge[edge]);
        grad_pv_tangential[tid] = grad_t;
        grad_pv_normal[tid] = grad_n;
        pv_edge[tid] = mpas_sub(pv_edge[tid], mpas_mul(scale, mpas_add(
            mpas_mul(tangential_velocity[tid], grad_t),
            mpas_mul(normal_velocity[tid], grad_n))));
    }
}

extern "C" __global__ void mass_flux_divergence_f32(
    const float* rho_u,
    const int* edges_on_cell,
    const int* n_edges_on_cell,
    const int* cells_on_edge,
    const float* dv_edge,
    const float* area_cell,
    const int nlev,
    const int ncells,
    const int nedges,
    const int max_edges,
    float* mass_divergence
) {
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    const int count = n_edges_on_cell[cell];
    for (int k = 0; k < nlev; ++k) {
        float value = 0.0f;
        for (int slot = 0; slot < count; ++slot) {
            const int edge = edges_on_cell[cell * max_edges + slot];
            value = mpas_add(value, mpas_mul(mpas_mul(
                cell_sign(cell, edge, cells_on_edge), dv_edge[edge]),
                rho_u[lidx(k, edge, nedges)]));
        }
        mass_divergence[lidx(k, cell, ncells)] = mpas_div(
            value, area_cell[cell]);
    }
}

extern "C" __global__ void density_tendency_f32(
    const float* mass_divergence,
    const float* rho_w,
    const float* rdzw,
    const float* physics_tendency,
    const int has_physics,
    const int nlev,
    const int ncells,
    float* tendency
) {
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    for (int k = 0; k < nlev; ++k) {
        const int tid = lidx(k, cell, ncells);
        float value = mpas_sub(mpas_sub(0.0f, mass_divergence[tid]),
            mpas_mul(rdzw[k], mpas_sub(
                rho_w[lidx(k + 1, cell, ncells)],
                rho_w[lidx(k, cell, ncells)])));
        if (has_physics) value = mpas_add(value, physics_tendency[tid]);
        tendency[tid] = value;
    }
}

extern "C" __global__ void pressure_gradient_f32(
    const float* pressure_p,
    const float* dpdz,
    const float* cqu,
    const float* zz,
    const float* zxu,
    const int* cells_on_edge,
    const float* dc_edge,
    const int nlev,
    const int ncells,
    const int nedges,
    float* tendency
) {
    const int edge = blockDim.x * blockIdx.x + threadIdx.x;
    if (edge >= nedges) return;
    const int cell0 = cells_on_edge[2 * edge];
    const int cell1 = cells_on_edge[2 * edge + 1];
    for (int k = 0; k < nlev; ++k) {
        const int tid = lidx(k, edge, nedges);
        const float normal = mpas_div(mpas_div(mpas_sub(
            pressure_p[lidx(k, cell1, ncells)],
            pressure_p[lidx(k, cell0, ncells)]), dc_edge[edge]),
            mpas_mul(0.5f, mpas_add(
                zz[lidx(k, cell1, ncells)],
                zz[lidx(k, cell0, ncells)])));
        const float terrain = mpas_mul(mpas_mul(0.5f, zxu[tid]), mpas_add(
            dpdz[lidx(k, cell0, ncells)],
            dpdz[lidx(k, cell1, ncells)]));
        tendency[tid] = mpas_mul(mpas_sub(0.0f, cqu[tid]),
            mpas_sub(normal, terrain));
    }
}

extern "C" __global__ void mixing_scaling_f32(
    const int* cells_on_edge,
    const float* mesh_density,
    const int nedges,
    const int scale_with_mesh,
    float* del2,
    float* del4
) {
    const int edge = blockDim.x * blockIdx.x + threadIdx.x;
    if (edge >= nedges) return;
    if (!scale_with_mesh) {
        del2[edge] = 1.0f;
        del4[edge] = 1.0f;
        return;
    }
    const int cell0 = cells_on_edge[2 * edge];
    const int cell1 = cells_on_edge[2 * edge + 1];
    const float mean_density = 0.5f * (mesh_density[cell0] + mesh_density[cell1]);
    del2[edge] = 1.0f / powf(mean_density, 0.25f);
    del4[edge] = 1.0f / powf(mean_density, 0.75f);
}

extern "C" __global__ void smagorinsky_f32(
    const float* normal_velocity,
    const float* tangential_velocity,
    const int* edges_on_cell,
    const int* n_edges_on_cell,
    const float* defc_a,
    const float* defc_b,
    const float strain_scale,
    const float ceiling,
    const int nlev,
    const int ncells,
    const int nedges,
    const int max_edges,
    float* kdiff
) {
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    const int count = n_edges_on_cell[cell];
    for (int k = 0; k < nlev; ++k) {
        float diagonal = 0.0f;
        float off_diagonal = 0.0f;
        bool ftz_sensitive = false;
        for (int slot = 0; slot < count; ++slot) {
            const int offset = cell * max_edges + slot;
            const int edge = edges_on_cell[offset];
            const float u = normal_velocity[lidx(k, edge, nedges)];
            const float v = tangential_velocity[lidx(k, edge, nedges)];
            const float a = defc_a[offset];
            const float b = defc_b[offset];
            const unsigned int umag = mpas_f32_magnitude_bits(u);
            const unsigned int vmag = mpas_f32_magnitude_bits(v);
            const unsigned int amag = mpas_f32_magnitude_bits(a);
            const unsigned int bmag = mpas_f32_magnitude_bits(b);
            ftz_sensitive = ftz_sensitive
                || (umag != 0u && (umag >> 23) <= 63u)
                || (vmag != 0u && (vmag >> 23) <= 63u)
                || (amag != 0u && (amag >> 23) == 0u)
                || (bmag != 0u && (bmag >> 23) == 0u);
            diagonal += a * u - b * v;
            off_diagonal += b * u + a * v;
        }
        if (ftz_sensitive) {
            diagonal = 0.0f;
            off_diagonal = 0.0f;
            for (int slot = 0; slot < count; ++slot) {
                const int offset = cell * max_edges + slot;
                const int edge = edges_on_cell[offset];
                const float u = normal_velocity[lidx(k, edge, nedges)];
                const float v = tangential_velocity[lidx(k, edge, nedges)];
                const float a = defc_a[offset];
                const float b = defc_b[offset];
                diagonal = mpas_add(diagonal,
                    mpas_sub(mpas_mul(a, u), mpas_mul(b, v)));
                off_diagonal = mpas_add(off_diagonal,
                    mpas_add(mpas_mul(b, u), mpas_mul(a, v)));
            }
            const float strain = mpas_sqrt(mpas_add(
                mpas_mul(diagonal, diagonal),
                mpas_mul(off_diagonal, off_diagonal)));
            kdiff[lidx(k, cell, ncells)] = mpas_min(
                mpas_mul(strain_scale, strain), ceiling);
        } else {
            const float strain = sqrtf(
                diagonal * diagonal + off_diagonal * off_diagonal);
            kdiff[lidx(k, cell, ncells)] = fminf(
                strain_scale * strain, ceiling);
        }
    }
}

extern "C" __global__ void momentum_filter_lap2_f32(
    const float* rho_edge,
    const float* divergence,
    const float* vorticity,
    const float* kdiff,
    const float* del2,
    const int* cells_on_edge,
    const int* vertices_on_edge,
    const float* dc_edge,
    const float* dv_edge,
    const int nlev,
    const int ncells,
    const int nedges,
    const int nvertices,
    float* delsq_u,
    float* tendency
) {
    const int edge = blockDim.x * blockIdx.x + threadIdx.x;
    if (edge >= nedges) return;
    const int cell0 = cells_on_edge[2 * edge];
    const int cell1 = cells_on_edge[2 * edge + 1];
    const int vertex0 = vertices_on_edge[2 * edge];
    const int vertex1 = vertices_on_edge[2 * edge + 1];
    const float inv_dc = 1.0f / dc_edge[edge];
    const float inv_dv = fminf(1.0f / dv_edge[edge], 4.0f * inv_dc);
    for (int k = 0; k < nlev; ++k) {
        const int tid = lidx(k, edge, nedges);
        const float lap = mpas_sub(mpas_mul(mpas_sub(
            divergence[lidx(k, cell1, ncells)],
            divergence[lidx(k, cell0, ncells)]), inv_dc),
            mpas_mul(mpas_sub(vorticity[lidx(k, vertex1, nvertices)],
                vorticity[lidx(k, vertex0, nvertices)]), inv_dv));
        const float kedge = mpas_mul(0.5f, mpas_add(
            kdiff[lidx(k, cell0, ncells)],
            kdiff[lidx(k, cell1, ncells)]));
        delsq_u[tid] = lap;
        tendency[tid] = mpas_mul(mpas_mul(mpas_mul(
            rho_edge[tid], kedge), lap), del2[edge]);
    }
}

extern "C" __global__ void laplacian_divergence_f32(
    const float* delsq_u,
    const int* edges_on_cell,
    const int* n_edges_on_cell,
    const int* cells_on_edge,
    const float* dv_edge,
    const float* area_cell,
    const int nlev,
    const int ncells,
    const int nedges,
    const int max_edges,
    float* delsq_divergence
) {
    HORIZONTAL_ELEMENT_LOOP(nlev * ncells) {
        const int cell = element % ncells;
        const int k = element / ncells;
        const int count = n_edges_on_cell[cell];
        float value = 0.0f;
        for (int slot = 0; slot < count; ++slot) {
            const int edge = edges_on_cell[cell * max_edges + slot];
            value = mpas_add(value, mpas_mul(mpas_div(mpas_mul(
                cell_sign(cell, edge, cells_on_edge), dv_edge[edge]),
                area_cell[cell]), delsq_u[lidx(k, edge, nedges)]));
        }
        delsq_divergence[lidx(k, cell, ncells)] = value;
    }
}

extern "C" __global__ void laplacian_vorticity_f32(
    const float* delsq_u,
    const int* edges_on_vertex,
    const int* vertices_on_edge,
    const float* dc_edge,
    const float* area_triangle,
    const int nlev,
    const int nedges,
    const int nvertices,
    const int vertex_degree,
    float* delsq_vorticity
) {
    const int vertex = blockDim.x * blockIdx.x + threadIdx.x;
    if (vertex >= nvertices) return;
    for (int k = 0; k < nlev; ++k) {
        float value = 0.0f;
        for (int slot = 0; slot < vertex_degree; ++slot) {
            const int edge = edges_on_vertex[vertex * vertex_degree + slot];
            if (edge < 0) continue;
            value = mpas_add(value, mpas_mul(mpas_div(mpas_mul(
                vertex_sign(vertex, edge, vertices_on_edge), dc_edge[edge]),
                area_triangle[vertex]), delsq_u[lidx(k, edge, nedges)]));
        }
        delsq_vorticity[lidx(k, vertex, nvertices)] = value;
    }
}

extern "C" __global__ void momentum_filter_lap4_f32(
    const float* rho_edge,
    const float* delsq_divergence,
    const float* delsq_vorticity,
    const float* del4,
    const int* cells_on_edge,
    const int* vertices_on_edge,
    const float* dc_edge,
    const float* dv_edge,
    const float h4,
    const float div_factor,
    const int nlev,
    const int ncells,
    const int nedges,
    const int nvertices,
    float* tendency
) {
    const int edge = blockDim.x * blockIdx.x + threadIdx.x;
    if (edge >= nedges) return;
    const int cell0 = cells_on_edge[2 * edge];
    const int cell1 = cells_on_edge[2 * edge + 1];
    const int vertex0 = vertices_on_edge[2 * edge];
    const int vertex1 = vertices_on_edge[2 * edge + 1];
    const float inv_dc = 1.0f / dc_edge[edge];
    const float inv_dv = fminf(1.0f / dv_edge[edge], 4.0f * inv_dc);
    const float scale = mpas_mul(del4[edge], h4);
    for (int k = 0; k < nlev; ++k) {
        const int tid = lidx(k, edge, nedges);
        const float diffusion = mpas_mul(rho_edge[tid], mpas_sub(
            mpas_mul(mpas_mul(mpas_mul(mpas_sub(
                delsq_divergence[lidx(k, cell1, ncells)],
                delsq_divergence[lidx(k, cell0, ncells)]), scale),
                div_factor), inv_dc),
            mpas_mul(mpas_mul(mpas_sub(
                delsq_vorticity[lidx(k, vertex1, nvertices)],
                delsq_vorticity[lidx(k, vertex0, nvertices)]), scale),
                inv_dv)));
        tendency[tid] = mpas_sub(tendency[tid], diffusion);
    }
}

extern "C" __global__ void theta_filter_lap2_f32(
    const float* theta_m,
    const float* rho_edge,
    const float* kdiff,
    const float* del2,
    const int* edges_on_cell,
    const int* n_edges_on_cell,
    const int* cells_on_edge,
    const float* dc_edge,
    const float* dv_edge,
    const float* area_cell,
    const int nlev,
    const int ncells,
    const int nedges,
    const int max_edges,
    float* delsq_theta,
    float* tendency
) {
    HORIZONTAL_ELEMENT_LOOP(nlev * ncells) {
        const int cell = element % ncells;
        const int k = element / ncells;
        const int count = n_edges_on_cell[cell];
        float lap = 0.0f;
        float tend = 0.0f;
        for (int slot = 0; slot < count; ++slot) {
            const int edge = edges_on_cell[cell * max_edges + slot];
            const int cell0 = cells_on_edge[2 * edge];
            const int cell1 = cells_on_edge[2 * edge + 1];
            const float factor = mpas_div(mpas_mul(
                cell_sign(cell, edge, cells_on_edge), dv_edge[edge]),
                mpas_mul(area_cell[cell], dc_edge[edge]));
            const float flux = mpas_mul(mpas_mul(factor, mpas_sub(
                theta_m[lidx(k, cell1, ncells)],
                theta_m[lidx(k, cell0, ncells)])),
                rho_edge[lidx(k, edge, nedges)]);
            lap = mpas_add(lap, flux);
            tend = mpas_add(tend, mpas_mul(mpas_mul(mpas_mul(
                flux, 0.5f), mpas_add(
                    kdiff[lidx(k, cell0, ncells)],
                    kdiff[lidx(k, cell1, ncells)])), del2[edge]));
        }
        const int tid = lidx(k, cell, ncells);
        delsq_theta[tid] = lap;
        tendency[tid] = tend;
    }
}

extern "C" __global__ void theta_filter_lap4_f32(
    const float* delsq_theta,
    const float* del4,
    const int* edges_on_cell,
    const int* n_edges_on_cell,
    const int* cells_on_edge,
    const float* dc_edge,
    const float* dv_edge,
    const float* area_cell,
    const float h4,
    const int nlev,
    const int ncells,
    const int max_edges,
    float* tendency
) {
    HORIZONTAL_ELEMENT_LOOP(nlev * ncells) {
        const int cell = element % ncells;
        const int k = element / ncells;
        const int count = n_edges_on_cell[cell];
        const int tid = lidx(k, cell, ncells);
        float tend = tendency[tid];
        for (int slot = 0; slot < count; ++slot) {
            const int edge = edges_on_cell[cell * max_edges + slot];
            const int cell0 = cells_on_edge[2 * edge];
            const int cell1 = cells_on_edge[2 * edge + 1];
            const float factor = mpas_div(mpas_mul(mpas_mul(mpas_div(
                mpas_mul(del4[edge], h4), area_cell[cell]), dv_edge[edge]),
                cell_sign(cell, edge, cells_on_edge)), dc_edge[edge]);
            tend = mpas_sub(tend, mpas_mul(factor, mpas_sub(
                delsq_theta[lidx(k, cell1, ncells)],
                delsq_theta[lidx(k, cell0, ncells)])));
        }
        tendency[tid] = tend;
    }
}

extern "C" __global__ void w_filter_lap2_f32(
    const float* vertical_velocity,
    const float* rho_edge,
    const float* kdiff,
    const float* del2,
    const int* edges_on_cell,
    const int* n_edges_on_cell,
    const int* cells_on_edge,
    const float* dc_edge,
    const float* dv_edge,
    const float* area_cell,
    const int nlev,
    const int ncells,
    const int nedges,
    const int max_edges,
    float* delsq_w,
    float* tendency
) {
    HORIZONTAL_ELEMENT_LOOP(nlev * ncells) {
        const int cell = element % ncells;
        const int k = element / ncells;
        const int count = n_edges_on_cell[cell];
        const int tid = lidx(k, cell, ncells);
        if (k == 0) {
            delsq_w[tid] = 0.0f;
            tendency[tid] = 0.0f;
            continue;
        }
        float lap = 0.0f;
        float tend = 0.0f;
        for (int slot = 0; slot < count; ++slot) {
            const int edge = edges_on_cell[cell * max_edges + slot];
            const int cell0 = cells_on_edge[2 * edge];
            const int cell1 = cells_on_edge[2 * edge + 1];
            const float factor = mpas_div(mpas_mul(mpas_mul(
                mpas_div(0.5f, area_cell[cell]),
                cell_sign(cell, edge, cells_on_edge)), dv_edge[edge]),
                dc_edge[edge]);
            const float flux = mpas_mul(mpas_mul(factor, mpas_add(
                rho_edge[lidx(k, edge, nedges)],
                rho_edge[lidx(k - 1, edge, nedges)])), mpas_sub(
                    vertical_velocity[lidx(k, cell1, ncells)],
                    vertical_velocity[lidx(k, cell0, ncells)]));
            lap = mpas_add(lap, flux);
            const float kedge = mpas_mul(0.25f, mpas_add(mpas_add(
                kdiff[lidx(k, cell0, ncells)],
                kdiff[lidx(k, cell1, ncells)]), mpas_add(
                    kdiff[lidx(k - 1, cell0, ncells)],
                    kdiff[lidx(k - 1, cell1, ncells)])));
            tend = mpas_add(tend, mpas_mul(mpas_mul(
                flux, del2[edge]), kedge));
        }
        delsq_w[tid] = lap;
        tendency[tid] = tend;
    }
}

extern "C" __global__ void w_filter_lap4_f32(
    const float* delsq_w,
    const float* del4,
    const int* edges_on_cell,
    const int* n_edges_on_cell,
    const int* cells_on_edge,
    const float* dc_edge,
    const float* dv_edge,
    const float* area_cell,
    const float h4,
    const int nlev,
    const int ncells,
    const int max_edges,
    float* tendency
) {
    /* Rows 1..nlev-1 only, as the per-cell loop ran them. */
    HORIZONTAL_ELEMENT_LOOP((nlev - 1) * ncells) {
        const int cell = element % ncells;
        const int k = 1 + element / ncells;
        const int count = n_edges_on_cell[cell];
        const int tid = lidx(k, cell, ncells);
        float tend = tendency[tid];
        for (int slot = 0; slot < count; ++slot) {
            const int edge = edges_on_cell[cell * max_edges + slot];
            const int cell0 = cells_on_edge[2 * edge];
            const int cell1 = cells_on_edge[2 * edge + 1];
            const float factor = mpas_div(mpas_mul(mpas_mul(mpas_div(
                mpas_mul(del4[edge], h4), area_cell[cell]), dv_edge[edge]),
                cell_sign(cell, edge, cells_on_edge)), dc_edge[edge]);
            tend = mpas_sub(tend, mpas_mul(factor, mpas_sub(
                delsq_w[lidx(k, cell1, ncells)],
                delsq_w[lidx(k, cell0, ncells)])));
        }
        tendency[tid] = tend;
    }
}

extern "C" __global__ void divergence_damping_f32(
    const float* theta_m,
    const float* rtheta_pp,
    const float* rtheta_pp_old,
    const int* cells_on_edge,
    const float* spec_zone_mask_edge,
    const float coefficient,
    const int n_cells_solve,
    const int nlev,
    const int ncells,
    const int nedges,
    float* rho_u_perturbation
) {
    const int edge = blockDim.x * blockIdx.x + threadIdx.x;
    if (edge >= nedges) return;
    const int cell0 = cells_on_edge[2 * edge];
    const int cell1 = cells_on_edge[2 * edge + 1];
    if (cell0 >= n_cells_solve && cell1 >= n_cells_solve) return;
    for (int k = 0; k < nlev; ++k) {
        const int tid = lidx(k, edge, nedges);
        const float delta0 = mpas_sub(
            rtheta_pp[lidx(k, cell0, ncells)],
            rtheta_pp_old[lidx(k, cell0, ncells)]);
        const float delta1 = mpas_sub(
            rtheta_pp[lidx(k, cell1, ncells)],
            rtheta_pp_old[lidx(k, cell1, ncells)]);
        const float denominator = mpas_add(
            theta_m[lidx(k, cell0, ncells)],
            theta_m[lidx(k, cell1, ncells)]);
        rho_u_perturbation[tid] = mpas_add(rho_u_perturbation[tid],
            mpas_div(mpas_mul(mpas_mul(coefficient,
                mpas_sub(delta0, delta1)), mpas_sub(
                    1.0f, spec_zone_mask_edge[edge])), denominator));
    }
}

