    if (n_bins == 0) {
        out = (invert ? true : false);
        return;
    }

    const bool assume_increasing = true;
    const bool side_is_right = false;
    long long y;

    #ifdef __HIP_DEVICE_COMPILE__
    bool is_done = false;
    #endif

