    double rhog = fmin(fmax(x_g / vg, 10.0), 900.0);           // MPAS mp_radar.F90:242
    vg = x_g / rhog;                                           // MPAS mp_radar.F90:243
    double grenz = 1.0 - rhog / 1000.0;                        // MPAS mp_radar.F90:245
