                           FADD(K_ONE, glibc_powf(FMUL(W_500, sice), W_THREE)));
        w = FADD(FMUL(vkwgt, w),
                 FMUL(FMUL(FSUB(K_ONE, vkwgt), dwsat),
                      glibc_powf(factr1, expon)));
