        delta[k] = FMUL(FSUB(d[k], FMUL(a[k], delta[k - 1])), recip);
    }
    p[NSOIL - 1] = delta[NSOIL - 1];                                 // :5582
    for (int k = NSOIL - 2; k >= 0; --k) {                           // :5586
