              par[P_DWSAT], par[P_DKSAT], &wdf, &wcnd);              // :7703
    infmax = f_max(infmax, wcnd);                                    // :7704
    infmax = f_min(infmax, FDIV(px, dt));                            // :7705

    *runsrf = f_max(K_ZERO, FSUB(qinsur, infmax));                   // :7707
    *pddum = FSUB(qinsur, *runsrf);                                  // :7708
}

