    extern "C" __global__ void cupy_take(const CArray<float, 1, 1, 1> a, const CArray<int, 1, 1, 1> _raw_indices, const long long ldim_, const long long cdim_, const long long rdim_, const long long index_range_, CArray<float, 1, 1, 1> _raw_out, CIndexer<1, 1> _ind) {
      ;
