    }

    cmc = FADD(canliq, canice);                                      // :6388
    float ecan = FSUB(FSUB(FADD(qevac, qsubc), qdewc), qfroc);       // :6392

    o[0] = canliq; o[1] = canice; o[2] = tv;  o[3] = cmc;
    o[4] = ecan;   o[5] = etran;  o[6] = fwet;
