        for (int slot = 0; slot < n_edges_on_edge[edge]; ++slot) {
            const int offset = edge * max_edges2 + slot;
            const int neighbor = edges_on_edge[offset];
            q = mpas_sub(q, mpas_mul(mpas_mul(
                weights_on_edge[offset], reference_u[E2(k, neighbor, nedges)]),
                f_edge[edge]));
        }
        const float gradient = mpas_mul(mpas_sub(
            kinetic[C2(k, c1, ncells)], kinetic[C2(k, c0, ncells)]),
            inv_dc_edge[edge]);
        const float horizontal = mpas_mul(rho_edge[index], mpas_sub(q, gradient));
        result[index] = mpas_sub(has_initial ? mpas_add(initial_tendency[index], horizontal) : horizontal,
            mpas_mul(mpas_mul(u[index], 0.5f),
                mpas_add(mass_divergence[C2(k, c0, ncells)],
                    mass_divergence[C2(k, c1, ncells)])));
    }
}

#ifndef HEX_HOIST_EOE
#define HEX_HOIST_EOE 10
#endif
extern "C" __global__ void vector_momentum_hoist_v841_f32(
    const int nlev, const int ncells, const int nedges, const int max_edges2,
    const float *u, const float *rho_edge, const float *pv_edge,
    const float *kinetic, const float *mass_divergence,
    const int *cells_on_edge, const int *edges_on_edge,
    const int *n_edges_on_edge, const float *weights_on_edge,
    const float *inv_dc_edge, const float *reference_u, const float *f_edge,
    const float *initial_tendency, const int has_initial,
    float *result, const int lpt)
{
    /* One thread per edge walks every level.  The edge's stencil -- its
       neighbour edges, TRiSK weights, f, 1/dc and two cells -- is read once
       instead of once per level; every level runs the
       vector_momentum_v841_f32 element body unchanged (same operands, slot
       order and helper calls), so each output carries the same bits. */
    const int hex_rows = nlev;
    const int hex_chunks = (hex_rows + lpt - 1) / lpt;
    const int hex_element = blockDim.x * blockIdx.x + threadIdx.x;
    if (hex_element >= nedges * hex_chunks) return;
    const int edge = hex_element % nedges;
    const int hex_k0 = (hex_element / nedges) * lpt;
    const int hex_k1 = min(hex_rows, hex_k0 + lpt);
    const int count = n_edges_on_edge[edge];
    const int c0 = cells_on_edge[2 * edge];
    const int c1 = cells_on_edge[2 * edge + 1];
    if (count > HEX_HOIST_EOE) {
        for (int k = hex_k0; k < hex_k1; ++k) {
            const int index = E2(k, edge, nedges);
            float q = 0.0f;
            for (int slot = 0; slot < count; ++slot) {
                const int offset = edge * max_edges2 + slot;
                const int neighbor = edges_on_edge[offset];
                const float work_pv = mpas_mul(0.5f, mpas_add(
                    pv_edge[index], pv_edge[E2(k, neighbor, nedges)]));
                q = mpas_add(q, mpas_mul(mpas_mul(
                    weights_on_edge[offset], u[E2(k, neighbor, nedges)]), work_pv));
            }
            for (int slot = 0; slot < count; ++slot) {
                const int offset = edge * max_edges2 + slot;
                const int neighbor = edges_on_edge[offset];
                q = mpas_sub(q, mpas_mul(mpas_mul(
                    weights_on_edge[offset], reference_u[E2(k, neighbor, nedges)]),
                    f_edge[edge]));
            }
            const float gradient = mpas_mul(mpas_sub(
                kinetic[C2(k, c1, ncells)], kinetic[C2(k, c0, ncells)]),
                inv_dc_edge[edge]);
            const float horizontal = mpas_mul(rho_edge[index], mpas_sub(q, gradient));
            result[index] = mpas_sub(has_initial ? mpas_add(initial_tendency[index], horizontal) : horizontal,
                mpas_mul(mpas_mul(u[index], 0.5f),
                    mpas_add(mass_divergence[C2(k, c0, ncells)],
                        mass_divergence[C2(k, c1, ncells)])));
        }
        return;
    }
    int nb[HEX_HOIST_EOE];
    float wt[HEX_HOIST_EOE];
#pragma unroll
    for (int slot = 0; slot < HEX_HOIST_EOE; ++slot) {
        nb[slot] = slot < count ? edges_on_edge[edge * max_edges2 + slot] : edge;
        wt[slot] = slot < count ? weights_on_edge[edge * max_edges2 + slot] : 0.0f;
    }
    const float fe = f_edge[edge];
    const float inv_dc = inv_dc_edge[edge];
    for (int k = hex_k0; k < hex_k1; ++k) {
        const int index = E2(k, edge, nedges);
        const float pv_self = pv_edge[index];
        float q = 0.0f;
#pragma unroll
        for (int slot = 0; slot < HEX_HOIST_EOE; ++slot) {
            if (slot < count) {
                const float work_pv = mpas_mul(0.5f, mpas_add(
                    pv_self, pv_edge[E2(k, nb[slot], nedges)]));
                q = mpas_add(q, mpas_mul(mpas_mul(
                    wt[slot], u[E2(k, nb[slot], nedges)]), work_pv));
            }
        }
#pragma unroll
        for (int slot = 0; slot < HEX_HOIST_EOE; ++slot) {
            if (slot < count) {
                q = mpas_sub(q, mpas_mul(mpas_mul(
                    wt[slot], reference_u[E2(k, nb[slot], nedges)]), fe));
            }
        }
        const float gradient = mpas_mul(mpas_sub(
            kinetic[C2(k, c1, ncells)], kinetic[C2(k, c0, ncells)]), inv_dc);
        const float horizontal = mpas_mul(rho_edge[index], mpas_sub(q, gradient));
        result[index] = mpas_sub(has_initial ? mpas_add(initial_tendency[index], horizontal) : horizontal,
            mpas_mul(mpas_mul(u[index], 0.5f),
                mpas_add(mass_divergence[C2(k, c0, ncells)],
                    mass_divergence[C2(k, c1, ncells)])));
    }
}

extern "C" __global__ void theta_finish_v841_f32(
    const int nlev, const int ncells, const int nedges, const int max_edges,
    const int *n_edges_on_cell, const int *edges_on_cell,
    const float *acoustic_sign, const float *inv_area_cell, const float *rdzw,
    const float *edge_flux, const float *vertical_flux, float *result)
{
    DYNAMICS_ELEMENT_LOOP(nlev * ncells) {
        const int cell = element % ncells;
        const int k = element / ncells;
        const int index = C2(k, cell, ncells);
        float value = 0.0f;
        for (int slot = 0; slot < n_edges_on_cell[cell]; ++slot) {
            const int edge = edges_on_cell[CES(cell, slot, max_edges)];
            value = mpas_sub(value, mpas_mul(
                acoustic_sign[CES(cell, slot, max_edges)],
                edge_flux[E2(k, edge, nedges)]));
        }
        value = mpas_mul(value, inv_area_cell[cell]);
        value = mpas_sub(value, mpas_mul(rdzw[k], mpas_sub(
            vertical_flux[C2(k + 1, cell, ncells)], vertical_flux[index])));
        result[index] = value;
    }
}

// Native F:6814-6874 accumulates all advective fluxes, then all corrections.
// Combining the two per edge changes cancellation before the cell sum.
extern "C" __global__ void theta_finish_corrected_v841_f32(
    const int nlev, const int ncells, const int nedges, const int max_edges,
    const int *n_edges_on_cell, const int *edges_on_cell,
    const float *acoustic_sign, const float *inv_area_cell, const float *rdzw,
    const float *edge_flux, const float *vertical_flux,
    const float *ru, const float *ru_saved, const float *theta_saved,
    const float *dv_edge, const int *cells_on_edge, float *result)
{
    DYNAMICS_ELEMENT_LOOP(nlev * ncells) {
        const int cell = element % ncells;
        const int k = element / ncells;
        const int index = C2(k, cell, ncells);
        float value = 0.0f;
        for (int slot = 0; slot < n_edges_on_cell[cell]; ++slot) {
            const int edge = edges_on_cell[CES(cell, slot, max_edges)];
            value = mpas_sub(value, mpas_mul(
                acoustic_sign[CES(cell, slot, max_edges)],
                edge_flux[E2(k, edge, nedges)]));
        }
        for (int slot = 0; slot < n_edges_on_cell[cell]; ++slot) {
            const int edge = edges_on_cell[CES(cell, slot, max_edges)];
            const int c0 = cells_on_edge[2 * edge];
            const int c1 = cells_on_edge[2 * edge + 1];
            const int eindex = E2(k, edge, nedges);
            const float flux = mpas_mul(mpas_mul(mpas_mul(mpas_mul(
                acoustic_sign[CES(cell, slot, max_edges)], dv_edge[edge]),
                mpas_sub(ru_saved[eindex], ru[eindex])), 0.5f),
                mpas_add(theta_saved[C2(k, c1, ncells)],
                    theta_saved[C2(k, c0, ncells)]));
            value = mpas_sub(value, flux);
        }
        value = mpas_mul(value, inv_area_cell[cell]);
        result[index] = mpas_sub(value, mpas_mul(rdzw[k], mpas_sub(
            vertical_flux[C2(k + 1, cell, ncells)], vertical_flux[index])));
    }
}

extern "C" __global__ void w_finish_v841_f32(
    const int nlev, const int ncells, const int nedges, const int max_edges,
    const int *n_edges_on_cell, const int *edges_on_cell,
    const float *acoustic_sign, const float *inv_area_cell, const float *rdzu,
    const float *edge_flux, const float *vertical_flux, float *result)
{
    DYNAMICS_ELEMENT_LOOP((nlev + 1) * ncells) {
        const int cell = element % ncells;
        const int k = element / ncells;
        const int index = C2(k, cell, ncells);
        if (k == 0 || k == nlev) {
            result[index] = 0.0f;
        } else {
            float value = 0.0f;
            for (int slot = 0; slot < n_edges_on_cell[cell]; ++slot) {
                const int edge = edges_on_cell[CES(cell, slot, max_edges)];
                value = mpas_sub(value, mpas_mul(
                    acoustic_sign[CES(cell, slot, max_edges)],
                    edge_flux[E2(k, edge, nedges)]));
            }
            value = mpas_mul(value, inv_area_cell[cell]);
            value = mpas_sub(value, mpas_mul(rdzu[k], mpas_sub(
                vertical_flux[C2(k + 1, cell, ncells)], vertical_flux[index])));
            result[index] = value;
        }
    }
}

extern "C" __global__ void enforce_rw_endpoints_v841_f32(
    const int nlev, const int ncells, float *rw)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    rw[C2(0, cell, ncells)] = 0.0f;
    rw[C2(nlev, cell, ncells)] = 0.0f;
}

extern "C" __global__ void validate_positive_state_v841_f32(
    const int nvalues, const float *rho, const float *rho_theta, int *invalid)
{
    const int index = blockDim.x * blockIdx.x + threadIdx.x;
    if (index >= nvalues) return;
    const float density = rho[index];
    const float theta_mass = rho_theta[index];
    if (!(isfinite(density) && density > 0.0f
            && isfinite(theta_mass) && theta_mass > 0.0f)) {
        atomicExch(invalid, 1);
    }
}

extern "C" __global__ void validate_recovered_v841_f32(
    const int nlev, const int ncells, const int nedges,
    const float *rho, const float *rho_theta, const float *rho_u,
    const float *rho_w, const float *theta, const float *exner,
    const float *rho_p, const float *rtheta_p, const float *pressure_p,
    const float *normal_velocity, const float *vertical_velocity, int *invalid)
{
    const int owner = blockDim.x * blockIdx.x + threadIdx.x;
    if (owner < ncells) {
        for (int k = 0; k < nlev; ++k) {
            const int index = C2(k, owner, ncells);
            if (!(isfinite(rho[index]) && rho[index] > 0.0f
                    && isfinite(rho_theta[index]) && rho_theta[index] > 0.0f
                    && isfinite(theta[index]) && theta[index] > 0.0f
                    && isfinite(exner[index]) && exner[index] > 0.0f
                    && isfinite(rho_p[index]) && isfinite(rtheta_p[index])
                    && isfinite(pressure_p[index]))) {
                atomicExch(invalid, 1);
            }
        }
        for (int k = 0; k <= nlev; ++k) {
            const int index = C2(k, owner, ncells);
            if (!(isfinite(rho_w[index]) && isfinite(vertical_velocity[index])))
                atomicExch(invalid, 1);
        }
    }
    if (owner < nedges) {
        for (int k = 0; k < nlev; ++k) {
            const int index = E2(k, owner, nedges);
            if (!(isfinite(rho_u[index]) && isfinite(normal_velocity[index])))
                atomicExch(invalid, 1);
        }
    }
}

extern "C" __global__ void validate_finite_array_v841_f32(
    const int nvalues, const float *values, int *invalid)
{
    const int index = blockDim.x * blockIdx.x + threadIdx.x;
    if (index < nvalues && !isfinite(values[index])) atomicExch(invalid, 1);
}

extern "C" __global__ void split_flux_first_v841_f32(
    const int nlevels, const int nowners, const float *current, float *accumulator)
{
    DYNAMICS_ELEMENT_LOOP(nlevels * nowners) {
        accumulator[element] = current[element];
    }
}

extern "C" __global__ void split_flux_add_v841_f32(
    const int nlevels, const int nowners, const float *current, float *accumulator)
{
    DYNAMICS_ELEMENT_LOOP(nlevels * nowners) {
        accumulator[element] = mpas_add(current[element], accumulator[element]);
    }
}

extern "C" __global__ void split_flux_finish_v841_f32(
    const int nlevels, const int nowners, const float reciprocal,
    const float *accumulator, float *average)
{
    DYNAMICS_ELEMENT_LOOP(nlevels * nowners) {
        average[element] = mpas_mul(accumulator[element], reciprocal);
    }
}

#ifndef HEX_HOIST_CELL
#define HEX_HOIST_CELL 10
#endif
/* Chunked, stencil-hoisted forms of theta_finish_v841_f32 and
   w_finish_v841_f32: one thread per (level chunk, cell); rows 0 and nlev of
   w are the element kernel's zero rows. */
extern "C" __global__ void finish_chunk_v841_f32(
    const int nlev, const int ncells, const int nedges, const int max_edges,
    const int *n_edges_on_cell, const int *edges_on_cell,
    const float *acoustic_sign, const float *inv_area_cell, const float *rdz,
    const float *edge_flux, const float *vertical_flux, float *result,
    const int w_rows, const int lpt)
{
    const int hex_rows = w_rows ? nlev + 1 : nlev;
    const int hex_chunks = (hex_rows + lpt - 1) / lpt;
    const int hex_element = blockDim.x * blockIdx.x + threadIdx.x;
    if (hex_element >= ncells * hex_chunks) return;
    const int cell = hex_element % ncells;
    const int hex_k0 = (hex_element / ncells) * lpt;
    const int hex_k1 = min(hex_rows, hex_k0 + lpt);
    const int count = n_edges_on_cell[cell];
    const bool hoisted = count <= HEX_HOIST_CELL;
    int ed[HEX_HOIST_CELL];
    float sg[HEX_HOIST_CELL];
#pragma unroll
    for (int slot = 0; slot < HEX_HOIST_CELL; ++slot) {
        const bool live = hoisted && slot < count;
        ed[slot] = live ? edges_on_cell[CES(cell, slot, max_edges)] : 0;
        sg[slot] = live ? acoustic_sign[CES(cell, slot, max_edges)] : 0.0f;
    }
    const float inv_area = inv_area_cell[cell];
    for (int k = hex_k0; k < hex_k1; ++k) {
        const int index = C2(k, cell, ncells);
        if (w_rows && (k == 0 || k == nlev)) {
            result[index] = 0.0f;
            continue;
        }
        float value = 0.0f;
        if (hoisted) {
#pragma unroll
            for (int slot = 0; slot < HEX_HOIST_CELL; ++slot) {
                if (slot < count) {
                    value = mpas_sub(value, mpas_mul(sg[slot],
                        edge_flux[E2(k, ed[slot], nedges)]));
                }
            }
        } else {
            for (int slot = 0; slot < count; ++slot) {
                const int edge = edges_on_cell[CES(cell, slot, max_edges)];
                value = mpas_sub(value, mpas_mul(
                    acoustic_sign[CES(cell, slot, max_edges)],
                    edge_flux[E2(k, edge, nedges)]));
            }
        }
        value = mpas_mul(value, inv_area);
        value = mpas_sub(value, mpas_mul(rdz[k], mpas_sub(
            vertical_flux[C2(k + 1, cell, ncells)], vertical_flux[index])));
        result[index] = value;
    }
}

#ifndef MPAS_FTZ_FALLBACK_ENABLED
#define MPAS_FTZ_FALLBACK_ENABLED 1
#endif

__device__ __forceinline__ unsigned int mpas_f32_magnitude_bits(
    const float value)
{
    return __float_as_uint(value) & 0x7fffffffu;
}

__device__ __forceinline__ bool mpas_is_subnormal_f32(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int magnitude = mpas_f32_magnitude_bits(value);
    return magnitude != 0u && (magnitude & 0x7f800000u) == 0u;
#else
    return false;
#endif
}

// A plain float/double cast is one of the measured DAZ mechanisms, so decode
// a subnormal float from its integer mantissa instead.
__device__ __forceinline__ double mpas_f32_to_f64_ieee(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int bits = __float_as_uint(value);
    const unsigned int magnitude = bits & 0x7fffffffu;
    if (magnitude != 0u && (magnitude & 0x7f800000u) == 0u) {
        const double decoded = ldexp(
            (double)(magnitude & 0x007fffffu), -149);
        return (bits & 0x80000000u) != 0u ? -decoded : decoded;
    }
#endif
    return (double)value;
}

// __double2float_rn flushes an FP32-subnormal result on the certified route,
// so pack that narrow result from the rounded integer mantissa.
__device__ __forceinline__ float mpas_f64_to_f32_ieee(const double value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const double magnitude = fabs(value);
    if (magnitude > 0.0 && magnitude < 1.1754943508222875e-38) {
        const double scaled = rint(
            magnitude * 7.1362384635297994e+44);  // 2^149
        const unsigned int mantissa = (unsigned int)scaled;
        const unsigned int sign =
            (__double_as_longlong(value) < 0LL) ? 0x80000000u : 0u;
        return __uint_as_float(sign | mantissa);
    }
#endif
    return __double2float_rn(value);
}

__device__ __forceinline__ float mpas_add(
    const float left, const float right)
{
    const float ordinary = left + right;
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int result_magnitude = mpas_f32_magnitude_bits(ordinary);
    const unsigned int result_exponent = result_magnitude >> 23;
    // A result at exponent field >=25 cannot have been rounded differently
    // by an FP32 subnormal operand, which is then below half an ulp.
    if (result_exponent > 24u) return ordinary;
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) + mpas_f32_to_f64_ieee(right));
    }
#endif
#if MPAS_FTZ_FALLBACK_ENABLED
    // Two normal binary32 values can cancel into the subnormal range only
    // while both exponent fields are <= 23; above that, one ulp is already
    // at least the smallest normal value.
    if (left_exponent <= 23u && right_exponent <= 23u
            && result_exponent == 0u
            && left_magnitude != right_magnitude
            && left_magnitude != 0u && right_magnitude != 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) + mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_sub(
    const float left, const float right)
{
    const float ordinary = left - right;
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int result_magnitude = mpas_f32_magnitude_bits(ordinary);
    const unsigned int result_exponent = result_magnitude >> 23;
    if (result_exponent > 24u) return ordinary;
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) - mpas_f32_to_f64_ieee(right));
    }
#endif
#if MPAS_FTZ_FALLBACK_ENABLED
    if (left_exponent <= 23u && right_exponent <= 23u
            && result_exponent == 0u
            && left_magnitude != right_magnitude
            && left_magnitude != 0u && right_magnitude != 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) - mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_mul(
    const float left, const float right)
{
    const float ordinary = left * right;
#if MPAS_FTZ_FALLBACK_ENABLED
    // A normal finite/overflow result proves neither operand was lost to DAZ
    // and no FTZ result occurred.  Inspect operands only on the rare zero or
    // subnormal-result envelope.
    if ((mpas_f32_magnitude_bits(ordinary) & 0x7f800000u) == 0u) {
        const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
        const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
        if (left_magnitude != 0u && right_magnitude != 0u) {
            return mpas_f64_to_f32_ieee(
                mpas_f32_to_f64_ieee(left) * mpas_f32_to_f64_ieee(right));
        }
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_div(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) / mpas_f32_to_f64_ieee(right));
    }
#endif
    const float ordinary = left / right;
#if MPAS_FTZ_FALLBACK_ENABLED
    if (left_magnitude != 0u && right_magnitude != 0u
            && left_exponent + 126u <= right_exponent
            && (mpas_f32_magnitude_bits(ordinary) & 0x7f800000u) == 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) / mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_sqrt(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(value)) {
        return mpas_f64_to_f32_ieee(sqrt(mpas_f32_to_f64_ieee(value)));
    }
#endif
    return sqrtf(value);
}

__device__ __forceinline__ float mpas_abs(const float value)
{
    return __uint_as_float(__float_as_uint(value) & 0x7fffffffu);
}

__device__ __forceinline__ float mpas_copysign(
    const float magnitude, const float sign)
{
    return __uint_as_float(
        (__float_as_uint(magnitude) & 0x7fffffffu)
        | (__float_as_uint(sign) & 0x80000000u));
}

__device__ __forceinline__ float mpas_min(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(left) || mpas_is_subnormal_f32(right)) {
        return mpas_f32_to_f64_ieee(right) < mpas_f32_to_f64_ieee(left)
            ? right : left;
    }
#endif
    return fminf(left, right);
}

__device__ __forceinline__ float mpas_max(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(left) || mpas_is_subnormal_f32(right)) {
        return mpas_f32_to_f64_ieee(right) > mpas_f32_to_f64_ieee(left)
            ? right : left;
    }
#endif
    return fmaxf(left, right);
}

#define C2(k,c,nc) ((k)*(nc) + (c))
#define E2(k,e,ne) ((k)*(ne) + (e))
#define CES(c,s,me) ((c)*(me) + (s))

extern "C" __global__ void acoustic_cofrz_v841(
    const int nlev, const float *rdzw, float *cofrz)
{
    const int k = blockDim.x * blockIdx.x + threadIdx.x;
    if (k < nlev) cofrz[k] = rdzw[k];
}

extern "C" __global__ void acoustic_coefficients_v841(
    const int nlev, const int ncells, const float dts,
    const float gravity, const float rgas, const float cp,
    const float *zz, const float *cqw, const float *exner,
    const float *theta, const float *rho_base,
    const float *rtheta_base, const float *exner_base,
    const float *rtheta_p, const float *qtot,
    const float *rdzw, const float *fzm, const float *fzp,
    const float *rdzu, const float *etp, const float *ewp,
    float *cofwr, float *cofwz, float *coftz, float *cofwt,
    const float *cofrz, float *a_tri, float *b_tri, float *c_tri,
    float *alpha_tri, float *gamma_tri, int *singular)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    const float one = 1.0f;
    const float half = 0.5f;
    const float rcv = mpas_div(rgas, mpas_sub(cp, rgas));
    const float csquared = mpas_mul(cp, rcv);
    const float dts2 = mpas_mul(dts, dts);

    for (int k = 0; k < nlev; ++k) {
        const int i = C2(k, cell, ncells);
        cofwr[i] = 0.0f;
        cofwz[i] = 0.0f;
        coftz[i] = 0.0f;
        float value = mpas_mul(half, rcv);
        value = mpas_mul(value, zz[i]);
        value = mpas_mul(value, gravity);
        value = mpas_mul(value, rho_base[i]);
        value = mpas_div(value, mpas_add(one, qtot[i]));
        value = mpas_mul(value, exner[i]);
        value = mpas_div(value, mpas_mul(
            mpas_add(rtheta_base[i], rtheta_p[i]), exner_base[i]));
        cofwt[i] = value;
        a_tri[i] = 0.0f;
        b_tri[i] = 0.0f;
        c_tri[i] = 0.0f;
        alpha_tri[i] = 0.0f;
        gamma_tri[i] = 0.0f;
    }
    coftz[C2(nlev, cell, ncells)] = 0.0f;
    if (nlev > 0) b_tri[C2(0, cell, ncells)] = one;

    for (int k = 1; k < nlev; ++k) {
        const int i = C2(k, cell, ncells);
        const int im = C2(k - 1, cell, ncells);
        const float interp_zz = mpas_add(mpas_mul(fzm[k], zz[i]),
            mpas_mul(fzp[k], zz[im]));
        cofwr[i] = mpas_mul(mpas_mul(half, gravity), interp_zz);
        float zcoef = mpas_mul(csquared, interp_zz);
        zcoef = mpas_mul(zcoef, rdzu[k]);
        zcoef = mpas_mul(zcoef, cqw[i]);
        zcoef = mpas_mul(zcoef, mpas_add(mpas_mul(fzm[k], exner[i]),
            mpas_mul(fzp[k], exner[im])));
        cofwz[i] = zcoef;
        coftz[i] = mpas_add(mpas_mul(fzm[k], theta[i]),
            mpas_mul(fzp[k], theta[im]));
    }

    for (int k = 1; k < nlev; ++k) {
        const int i = C2(k, cell, ncells);
        const int im = C2(k - 1, cell, ncells);
        const int ip = C2(k + 1, cell, ncells);

        float avalue = mpas_sub(0.0f, mpas_mul(mpas_mul(mpas_mul(
            cofwz[i], coftz[im]), rdzw[k - 1]), zz[im]));
        avalue = mpas_add(avalue, mpas_mul(cofwr[i], cofrz[k - 1]));
        avalue = mpas_sub(avalue, mpas_mul(mpas_mul(
            cofwt[im], coftz[im]), rdzw[k - 1]));
        avalue = mpas_mul(avalue, etp[k - 1]);
        a_tri[i] = mpas_mul(avalue, ewp[k - 1]);

        const float upper_metric = mpas_mul(mpas_mul(
            etp[k], rdzw[k]), zz[i]);
        const float lower_metric = mpas_mul(mpas_mul(
            etp[k - 1], rdzw[k - 1]), zz[im]);
        float bvalue = mpas_mul(mpas_mul(cofwz[i], coftz[i]),
            mpas_add(upper_metric, lower_metric));
        const float upper_heat = mpas_mul(mpas_mul(
            etp[k], cofwt[i]), rdzw[k]);
        const float lower_heat = mpas_mul(mpas_mul(
            etp[k - 1], cofwt[im]), rdzw[k - 1]);
        bvalue = mpas_sub(bvalue, mpas_mul(coftz[i],
            mpas_sub(upper_heat, lower_heat)));
        const float upper_mass = mpas_mul(etp[k], cofrz[k]);
        const float lower_mass = mpas_mul(etp[k - 1], cofrz[k - 1]);
        bvalue = mpas_add(bvalue, mpas_mul(cofwr[i],
            mpas_sub(upper_mass, lower_mass)));
        b_tri[i] = mpas_mul(bvalue, ewp[k]);

        float cvalue = mpas_sub(0.0f, mpas_mul(mpas_mul(mpas_mul(
            cofwz[i], coftz[ip]), rdzw[k]), zz[i]));
        cvalue = mpas_sub(cvalue, mpas_mul(cofwr[i], cofrz[k]));
        cvalue = mpas_add(cvalue, mpas_mul(mpas_mul(
            cofwt[i], coftz[ip]), rdzw[k]));
        cvalue = mpas_mul(cvalue, etp[k]);
        c_tri[i] = mpas_mul(cvalue, ewp[k + 1]);
    }
    if (nlev > 0) c_tri[C2(nlev - 1, cell, ncells)] = 0.0f;

    for (int k = 1; k < nlev; ++k) {
        const int i = C2(k, cell, ncells);
        const int im = C2(k - 1, cell, ncells);
        const float denominator = mpas_add(one, mpas_mul(dts2,
            mpas_sub(b_tri[i], mpas_mul(a_tri[i], gamma_tri[im]))));
        if (!(isfinite(denominator) && denominator != 0.0f))
            atomicExch(singular, 1);
        alpha_tri[i] = mpas_div(one, denominator);
        gamma_tri[i] = mpas_mul(mpas_mul(dts2, c_tri[i]), alpha_tri[i]);
    }
}

extern "C" __global__ void acoustic_ru_v841(
    const int nlev, const int nedges, const int ncells,
    const int small_step, const float dts,
    const float gravity, const float rgas, const float cp,
    const int *cells_on_edge, const float *inv_dc_edge,
    const float *zz, const float *exner, const float *cqu,
    const float *zxu, const float *tend_ru,
    const float *rho_pp, const float *rtheta_pp,
    float *ru_p, float *ru_avg)
{
    const int edge = blockDim.x * blockIdx.x + threadIdx.x;
    if (edge >= nedges) return;
    const int c0 = cells_on_edge[2 * edge];
    const int c1 = cells_on_edge[2 * edge + 1];
    const float half = 0.5f;
    const float rcv = mpas_div(rgas, mpas_sub(cp, rgas));
    const float csquared = mpas_mul(cp, rcv);
    for (int k = 0; k < nlev; ++k) {
        const int index = E2(k, edge, nedges);
        if (small_step == 1) {
            const float value = mpas_mul(dts, tend_ru[index]);
            ru_p[index] = value;
            ru_avg[index] = value;
        } else {
            const float normal = mpas_mul(mpas_sub(
                rtheta_pp[C2(k, c1, ncells)],
                rtheta_pp[C2(k, c0, ncells)]), inv_dc_edge[edge]);
            const float normalized = mpas_div(normal, mpas_mul(half, mpas_add(
                zz[C2(k, c1, ncells)], zz[C2(k, c0, ncells)])));
            float pgrad = mpas_mul(cqu[index], half);
            pgrad = mpas_mul(pgrad, csquared);
            pgrad = mpas_mul(pgrad, mpas_add(exner[C2(k, c0, ncells)],
                exner[C2(k, c1, ncells)]));
            pgrad = mpas_mul(pgrad, normalized);
            const float terrain = mpas_mul(mpas_mul(mpas_mul(
                half, zxu[index]), gravity), mpas_add(
                    rho_pp[C2(k, c0, ncells)],
                    rho_pp[C2(k, c1, ncells)]));
            pgrad = mpas_add(pgrad, terrain);
            ru_p[index] = mpas_add(ru_p[index], mpas_mul(
                dts, mpas_sub(tend_ru[index], pgrad)));
            ru_avg[index] = mpas_add(ru_avg[index], ru_p[index]);
        }
    }
}

extern "C" __global__ void acoustic_prepare_v841(
    const int nlev, const int ncells, const int small_step,
    float *rw_p, float *rtheta_pp, float *rtheta_pp_old,
    float *rho_pp, float *ww_avg)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    for (int k = 0; k < nlev; ++k) {
        const int index = C2(k, cell, ncells);
        if (small_step == 1) {
            rtheta_pp_old[index] = 0.0f;
            rtheta_pp[index] = 0.0f;
            rho_pp[index] = 0.0f;
        } else {
            rtheta_pp_old[index] = rtheta_pp[index];
        }
    }
    if (small_step == 1) {
        for (int k = 0; k <= nlev; ++k) {
            const int index = C2(k, cell, ncells);
            rw_p[index] = 0.0f;
            ww_avg[index] = 0.0f;
        }
    }
}

extern "C" __global__ void acoustic_rs_ts_v841(
    const int nlev, const int ncells, const int nedges, const int max_edges,
    const float dts, const int *n_edges_on_cell, const int *edges_on_cell,
    const int *cells_on_edge, const float *edge_sign_on_cell,
    const float *dv_edge, const float *inv_area_cell,
    const float *theta_m, const float *rdzw,
    const float *cofrz, const float *coftz, const float *ewm,
    const float *ru_p, const float *rw_p,
    const float *rho_pp, const float *rtheta_pp,
    const float *tend_rho, const float *tend_rt,
    float *rs, float *ts)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    const int count = n_edges_on_cell[cell];
    for (int k = 0; k < nlev; ++k) {
        const int index = C2(k, cell, ncells);
        float r = 0.0f;
        float t = 0.0f;
        for (int slot = 0; slot < count; ++slot) {
            const int edge = edges_on_cell[CES(cell, slot, max_edges)];
            const int c0 = cells_on_edge[2 * edge];
            const int c1 = cells_on_edge[2 * edge + 1];
            float flux = mpas_mul(
                edge_sign_on_cell[CES(cell, slot, max_edges)], dts);
            flux = mpas_mul(flux, dv_edge[edge]);
            flux = mpas_mul(flux, ru_p[E2(k, edge, nedges)]);
            flux = mpas_mul(flux, inv_area_cell[cell]);
            r = mpas_sub(r, flux);
            t = mpas_sub(t, mpas_mul(mpas_mul(flux, 0.5f), mpas_add(
                theta_m[C2(k, c1, ncells)],
                theta_m[C2(k, c0, ncells)])));
        }
        r = mpas_add(mpas_add(rho_pp[index], mpas_mul(dts, tend_rho[index])),
            r);
        r = mpas_sub(r, mpas_mul(mpas_mul(dts, cofrz[k]), mpas_sub(
            mpas_mul(ewm[k + 1], rw_p[C2(k + 1, cell, ncells)]),
            mpas_mul(ewm[k], rw_p[index]))));
        t = mpas_add(mpas_add(rtheta_pp[index], mpas_mul(dts, tend_rt[index])),
            t);
        t = mpas_sub(t, mpas_mul(mpas_mul(dts, rdzw[k]), mpas_sub(
            mpas_mul(mpas_mul(ewm[k + 1], coftz[C2(k + 1, cell, ncells)]),
                rw_p[C2(k + 1, cell, ncells)]),
            mpas_mul(mpas_mul(ewm[k], coftz[index]), rw_p[index]))));
        rs[index] = r;
        ts[index] = t;
    }
}

extern "C" __global__ void acoustic_column_solve_v841(
    const int nlev, const int ncells, const float dts,
    const float *zz, const float *rho_zz,
    const float *fzm, const float *fzp, const float *rdzw,
    const float *dss, const float *w, const float *rw, const float *rw_save,
    const float *tend_rw, const float *rs, const float *ts,
    const float *cofwr, const float *cofwz, const float *coftz,
    const float *cofwt, const float *cofrz,
    const float *a_tri, const float *alpha_tri, const float *gamma_tri,
    const float *etp, const float *etm, const float *ewp, const float *ewm,
    float *rw_p, float *rho_pp, float *rtheta_pp, float *ww_avg)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    const float dts2 = mpas_mul(dts, dts);
    for (int k = 1; k < nlev; ++k) {
        const int i = C2(k, cell, ncells);
        const int im = C2(k - 1, cell, ncells);
        ww_avg[i] = mpas_add(ww_avg[i], mpas_mul(ewm[k], rw_p[i]));

        const float theta_implicit = mpas_sub(
            mpas_mul(mpas_mul(etp[k], zz[i]), ts[i]),
            mpas_mul(mpas_mul(etp[k - 1], zz[im]), ts[im]));
        const float theta_explicit = mpas_sub(
            mpas_mul(mpas_mul(etm[k], zz[i]), rtheta_pp[i]),
            mpas_mul(mpas_mul(etm[k - 1], zz[im]), rtheta_pp[im]));
        const float density_implicit = mpas_add(
            mpas_mul(etp[k], rs[i]), mpas_mul(etp[k - 1], rs[im]));
        const float density_explicit = mpas_add(
            mpas_mul(etm[k], rho_pp[i]),
            mpas_mul(etm[k - 1], rho_pp[im]));
        const float heat_upper = mpas_add(
            mpas_mul(etp[k], ts[i]), mpas_mul(etm[k], rtheta_pp[i]));
        const float heat_lower = mpas_add(
            mpas_mul(etp[k - 1], ts[im]),
            mpas_mul(etm[k - 1], rtheta_pp[im]));

        float inner = mpas_sub(tend_rw[i], mpas_mul(cofwz[i],
            mpas_add(theta_implicit, theta_explicit)));
        inner = mpas_sub(inner, mpas_mul(cofwr[i],
            mpas_add(density_implicit, density_explicit)));
        inner = mpas_add(inner, mpas_mul(cofwt[i], heat_upper));
        inner = mpas_add(inner, mpas_mul(cofwt[im], heat_lower));
        rw_p[i] = mpas_add(rw_p[i], mpas_mul(dts, inner));
    }

    for (int k = 1; k < nlev; ++k) {
        const int i = C2(k, cell, ncells);
        const int im = C2(k - 1, cell, ncells);
        rw_p[i] = mpas_mul(mpas_sub(rw_p[i], mpas_mul(mpas_mul(
            dts2, a_tri[i]), rw_p[im])), alpha_tri[i]);
    }
    for (int k = nlev - 1; k >= 0; --k) {
        const int i = C2(k, cell, ncells);
        rw_p[i] = mpas_sub(rw_p[i], mpas_mul(
            gamma_tri[i], rw_p[C2(k + 1, cell, ncells)]));
    }

    for (int k = 1; k < nlev; ++k) {
        const int i = C2(k, cell, ncells);
        const int im = C2(k - 1, cell, ncells);
        const float delta_saved = mpas_sub(rw_save[i], rw[i]);
        const float zz_interface = mpas_add(
            mpas_mul(fzm[k], zz[i]), mpas_mul(fzp[k], zz[im]));
        const float rho_interface = mpas_add(
            mpas_mul(fzm[k], rho_zz[i]), mpas_mul(fzp[k], rho_zz[im]));
        float value = mpas_add(rw_p[i], delta_saved);
        value = mpas_sub(value, mpas_mul(mpas_mul(mpas_mul(mpas_mul(
            dts, dss[i]), zz_interface), rho_interface), w[i]));
        value = mpas_div(value, mpas_add(1.0f, mpas_mul(dts, dss[i])));
        rw_p[i] = mpas_sub(value, delta_saved);
        ww_avg[i] = mpas_add(ww_avg[i], mpas_mul(ewp[k], rw_p[i]));
    }
    for (int k = 0; k < nlev; ++k) {
        const int i = C2(k, cell, ncells);
        rho_pp[i] = mpas_sub(rs[i], mpas_mul(mpas_mul(dts, cofrz[k]),
            mpas_sub(mpas_mul(ewp[k + 1], rw_p[C2(k + 1, cell, ncells)]),
                mpas_mul(ewp[k], rw_p[i]))));
        rtheta_pp[i] = mpas_sub(ts[i], mpas_mul(mpas_mul(dts, rdzw[k]),
            mpas_sub(mpas_mul(mpas_mul(ewp[k + 1],
                    coftz[C2(k + 1, cell, ncells)]),
                rw_p[C2(k + 1, cell, ncells)]),
                mpas_mul(mpas_mul(ewp[k], coftz[i]), rw_p[i]))));
    }
}

/* Element forms of acoustic_rs_ts_v841 and acoustic_column_solve_v841.
   rs/ts at (level, cell) read only that level's inputs, so one thread per
   (level, cell), cell fastest, runs the per-cell loop body for its level
   unchanged.  The column solve keeps its tridiagonal sweeps serial per
   column; its first and last loops, whose levels are independent, run one
   thread per (level, cell).  Every value is the same helper sequence on the
   same operands, so outputs carry the same bits. */
extern "C" __global__ void acoustic_rs_ts_elem_v841(
    const int nlev, const int ncells, const int nedges, const int max_edges,
    const float dts, const int *n_edges_on_cell, const int *edges_on_cell,
    const int *cells_on_edge, const float *edge_sign_on_cell,
    const float *dv_edge, const float *inv_area_cell,
    const float *theta_m, const float *rdzw,
    const float *cofrz, const float *coftz, const float *ewm,
    const float *ru_p, const float *rw_p,
    const float *rho_pp, const float *rtheta_pp,
    const float *tend_rho, const float *tend_rt,
    float *rs, float *ts)
{
    const int element = blockDim.x * blockIdx.x + threadIdx.x;
    if (element >= nlev * ncells) return;
    const int cell = element % ncells;
    const int k = element / ncells;
    const int count = n_edges_on_cell[cell];
    const int index = C2(k, cell, ncells);
    float r = 0.0f;
    float t = 0.0f;
    for (int slot = 0; slot < count; ++slot) {
        const int edge = edges_on_cell[CES(cell, slot, max_edges)];
        const int c0 = cells_on_edge[2 * edge];
        const int c1 = cells_on_edge[2 * edge + 1];
        float flux = mpas_mul(
            edge_sign_on_cell[CES(cell, slot, max_edges)], dts);
        flux = mpas_mul(flux, dv_edge[edge]);
        flux = mpas_mul(flux, ru_p[E2(k, edge, nedges)]);
        flux = mpas_mul(flux, inv_area_cell[cell]);
        r = mpas_sub(r, flux);
        t = mpas_sub(t, mpas_mul(mpas_mul(flux, 0.5f), mpas_add(
            theta_m[C2(k, c1, ncells)],
            theta_m[C2(k, c0, ncells)])));
    }
    r = mpas_add(mpas_add(rho_pp[index], mpas_mul(dts, tend_rho[index])),
        r);
    r = mpas_sub(r, mpas_mul(mpas_mul(dts, cofrz[k]), mpas_sub(
        mpas_mul(ewm[k + 1], rw_p[C2(k + 1, cell, ncells)]),
        mpas_mul(ewm[k], rw_p[index]))));
    t = mpas_add(mpas_add(rtheta_pp[index], mpas_mul(dts, tend_rt[index])),
        t);
    t = mpas_sub(t, mpas_mul(mpas_mul(dts, rdzw[k]), mpas_sub(
        mpas_mul(mpas_mul(ewm[k + 1], coftz[C2(k + 1, cell, ncells)]),
            rw_p[C2(k + 1, cell, ncells)]),
        mpas_mul(mpas_mul(ewm[k], coftz[index]), rw_p[index]))));
    rs[index] = r;
    ts[index] = t;
}

extern "C" __global__ void acoustic_column_pre_v841(
    const int nlev, const int ncells, const float dts,
    const float *zz, const float *tend_rw, const float *rs, const float *ts,
    const float *cofwr, const float *cofwz, const float *cofwt,
    const float *etp, const float *etm, const float *ewm,
    float *rw_p, const float *rho_pp, const float *rtheta_pp, float *ww_avg)
{
    const int element = blockDim.x * blockIdx.x + threadIdx.x;
    if (element >= (nlev - 1) * ncells) return;
    const int cell = element % ncells;
    const int k = 1 + element / ncells;
    const int i = C2(k, cell, ncells);
    const int im = C2(k - 1, cell, ncells);
    ww_avg[i] = mpas_add(ww_avg[i], mpas_mul(ewm[k], rw_p[i]));

    const float theta_implicit = mpas_sub(
        mpas_mul(mpas_mul(etp[k], zz[i]), ts[i]),
        mpas_mul(mpas_mul(etp[k - 1], zz[im]), ts[im]));
    const float theta_explicit = mpas_sub(
        mpas_mul(mpas_mul(etm[k], zz[i]), rtheta_pp[i]),
        mpas_mul(mpas_mul(etm[k - 1], zz[im]), rtheta_pp[im]));
    const float density_implicit = mpas_add(
        mpas_mul(etp[k], rs[i]), mpas_mul(etp[k - 1], rs[im]));
    const float density_explicit = mpas_add(
        mpas_mul(etm[k], rho_pp[i]),
        mpas_mul(etm[k - 1], rho_pp[im]));
    const float heat_upper = mpas_add(
        mpas_mul(etp[k], ts[i]), mpas_mul(etm[k], rtheta_pp[i]));
    const float heat_lower = mpas_add(
        mpas_mul(etp[k - 1], ts[im]),
        mpas_mul(etm[k - 1], rtheta_pp[im]));

    float inner = mpas_sub(tend_rw[i], mpas_mul(cofwz[i],
        mpas_add(theta_implicit, theta_explicit)));
    inner = mpas_sub(inner, mpas_mul(cofwr[i],
        mpas_add(density_implicit, density_explicit)));
    inner = mpas_add(inner, mpas_mul(cofwt[i], heat_upper));
    inner = mpas_add(inner, mpas_mul(cofwt[im], heat_lower));
    rw_p[i] = mpas_add(rw_p[i], mpas_mul(dts, inner));
}

extern "C" __global__ void acoustic_column_sweep_v841(
    const int nlev, const int ncells, const float dts,
    const float *a_tri, const float *alpha_tri, const float *gamma_tri,
    float *rw_p)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    const float dts2 = mpas_mul(dts, dts);
    for (int k = 1; k < nlev; ++k) {
        const int i = C2(k, cell, ncells);
        const int im = C2(k - 1, cell, ncells);
        rw_p[i] = mpas_mul(mpas_sub(rw_p[i], mpas_mul(mpas_mul(
            dts2, a_tri[i]), rw_p[im])), alpha_tri[i]);
    }
    for (int k = nlev - 1; k >= 0; --k) {
        const int i = C2(k, cell, ncells);
        rw_p[i] = mpas_sub(rw_p[i], mpas_mul(
            gamma_tri[i], rw_p[C2(k + 1, cell, ncells)]));
    }
}

extern "C" __global__ void acoustic_column_post_w_v841(
    const int nlev, const int ncells, const float dts,
    const float *zz, const float *rho_zz,
    const float *fzm, const float *fzp,
    const float *dss, const float *w, const float *rw, const float *rw_save,
    const float *ewp, float *rw_p, float *ww_avg)
{
    const int element = blockDim.x * blockIdx.x + threadIdx.x;
    if (element >= (nlev - 1) * ncells) return;
    const int cell = element % ncells;
    const int k = 1 + element / ncells;
    const int i = C2(k, cell, ncells);
    const int im = C2(k - 1, cell, ncells);
    const float delta_saved = mpas_sub(rw_save[i], rw[i]);
    const float zz_interface = mpas_add(
        mpas_mul(fzm[k], zz[i]), mpas_mul(fzp[k], zz[im]));
    const float rho_interface = mpas_add(
        mpas_mul(fzm[k], rho_zz[i]), mpas_mul(fzp[k], rho_zz[im]));
    float value = mpas_add(rw_p[i], delta_saved);
    value = mpas_sub(value, mpas_mul(mpas_mul(mpas_mul(mpas_mul(
        dts, dss[i]), zz_interface), rho_interface), w[i]));
    value = mpas_div(value, mpas_add(1.0f, mpas_mul(dts, dss[i])));
    rw_p[i] = mpas_sub(value, delta_saved);
    ww_avg[i] = mpas_add(ww_avg[i], mpas_mul(ewp[k], rw_p[i]));
}

extern "C" __global__ void acoustic_column_post_rt_v841(
    const int nlev, const int ncells, const float dts,
    const float *rdzw, const float *rs, const float *ts,
    const float *coftz, const float *cofrz, const float *ewp,
    const float *rw_p, float *rho_pp, float *rtheta_pp)
{
    const int element = blockDim.x * blockIdx.x + threadIdx.x;
    if (element >= nlev * ncells) return;
    const int cell = element % ncells;
    const int k = element / ncells;
    const int i = C2(k, cell, ncells);
    rho_pp[i] = mpas_sub(rs[i], mpas_mul(mpas_mul(dts, cofrz[k]),
        mpas_sub(mpas_mul(ewp[k + 1], rw_p[C2(k + 1, cell, ncells)]),
            mpas_mul(ewp[k], rw_p[i]))));
    rtheta_pp[i] = mpas_sub(ts[i], mpas_mul(mpas_mul(dts, rdzw[k]),
        mpas_sub(mpas_mul(mpas_mul(ewp[k + 1],
                coftz[C2(k + 1, cell, ncells)]),
            rw_p[C2(k + 1, cell, ncells)]),
            mpas_mul(mpas_mul(ewp[k], coftz[i]), rw_p[i]))));
}

#ifndef HEX_HOIST_CELL
#define HEX_HOIST_CELL 10
#endif
/* Chunked, stencil-hoisted acoustic rs/ts: one thread per (level chunk,
   cell); each cell's edges, endpoint cells and sign x dts x dvEdge (the same
   two helper calls on the same operands, level-independent) sit in
   registers, and each (level, cell) runs the element body unchanged. */
extern "C" __global__ void acoustic_rs_ts_chunk_v841(
    const int nlev, const int ncells, const int nedges, const int max_edges,
    const float dts, const int *n_edges_on_cell, const int *edges_on_cell,
    const int *cells_on_edge, const float *edge_sign_on_cell,
    const float *dv_edge, const float *inv_area_cell,
    const float *theta_m, const float *rdzw,
    const float *cofrz, const float *coftz, const float *ewm,
    const float *ru_p, const float *rw_p,
    const float *rho_pp, const float *rtheta_pp,
    const float *tend_rho, const float *tend_rt,
    float *rs, float *ts, const int lpt)
{
    const int hex_chunks = (nlev + lpt - 1) / lpt;
    const int hex_element = blockDim.x * blockIdx.x + threadIdx.x;
    if (hex_element >= ncells * hex_chunks) return;
    const int cell = hex_element % ncells;
    const int hex_k0 = (hex_element / ncells) * lpt;
    const int hex_k1 = min(nlev, hex_k0 + lpt);
    const int count = n_edges_on_cell[cell];
    const bool hoisted = count <= HEX_HOIST_CELL;
    int ed[HEX_HOIST_CELL];
    int ca[HEX_HOIST_CELL];
    int cb[HEX_HOIST_CELL];
    float sdd[HEX_HOIST_CELL];
#pragma unroll
    for (int slot = 0; slot < HEX_HOIST_CELL; ++slot) {
        const bool live = hoisted && slot < count;
        const int edge = live ? edges_on_cell[CES(cell, slot, max_edges)] : 0;
        ed[slot] = edge;
        ca[slot] = live ? cells_on_edge[2 * edge] : 0;
        cb[slot] = live ? cells_on_edge[2 * edge + 1] : 0;
        sdd[slot] = live ? mpas_mul(mpas_mul(
            edge_sign_on_cell[CES(cell, slot, max_edges)], dts), dv_edge[edge]) : 0.0f;
    }
    const float inv_area = inv_area_cell[cell];
    for (int k = hex_k0; k < hex_k1; ++k) {
        const int index = C2(k, cell, ncells);
        float r = 0.0f;
        float t = 0.0f;
        if (hoisted) {
#pragma unroll
            for (int slot = 0; slot < HEX_HOIST_CELL; ++slot) {
                if (slot < count) {
                    float flux = mpas_mul(sdd[slot], ru_p[E2(k, ed[slot], nedges)]);
                    flux = mpas_mul(flux, inv_area);
                    r = mpas_sub(r, flux);
                    t = mpas_sub(t, mpas_mul(mpas_mul(flux, 0.5f), mpas_add(
                        theta_m[C2(k, cb[slot], ncells)],
                        theta_m[C2(k, ca[slot], ncells)])));
                }
            }
        } else {
            for (int slot = 0; slot < count; ++slot) {
                const int edge = edges_on_cell[CES(cell, slot, max_edges)];
                const int c0 = cells_on_edge[2 * edge];
                const int c1 = cells_on_edge[2 * edge + 1];
                float flux = mpas_mul(
                    edge_sign_on_cell[CES(cell, slot, max_edges)], dts);
                flux = mpas_mul(flux, dv_edge[edge]);
                flux = mpas_mul(flux, ru_p[E2(k, edge, nedges)]);
                flux = mpas_mul(flux, inv_area_cell[cell]);
                r = mpas_sub(r, flux);
                t = mpas_sub(t, mpas_mul(mpas_mul(flux, 0.5f), mpas_add(
                    theta_m[C2(k, c1, ncells)],
                    theta_m[C2(k, c0, ncells)])));
            }
        }
        r = mpas_add(mpas_add(rho_pp[index], mpas_mul(dts, tend_rho[index])),
            r);
        r = mpas_sub(r, mpas_mul(mpas_mul(dts, cofrz[k]), mpas_sub(
            mpas_mul(ewm[k + 1], rw_p[C2(k + 1, cell, ncells)]),
            mpas_mul(ewm[k], rw_p[index]))));
        t = mpas_add(mpas_add(rtheta_pp[index], mpas_mul(dts, tend_rt[index])),
            t);
        t = mpas_sub(t, mpas_mul(mpas_mul(dts, rdzw[k]), mpas_sub(
            mpas_mul(mpas_mul(ewm[k + 1], coftz[C2(k + 1, cell, ncells)]),
                rw_p[C2(k + 1, cell, ncells)]),
            mpas_mul(mpas_mul(ewm[k], coftz[index]), rw_p[index]))));
        rs[index] = r;
        ts[index] = t;
    }
}

#ifndef MPAS_FTZ_FALLBACK_ENABLED
#define MPAS_FTZ_FALLBACK_ENABLED 1
#endif

__device__ __forceinline__ unsigned int mpas_f32_magnitude_bits(
    const float value)
{
    return __float_as_uint(value) & 0x7fffffffu;
}

__device__ __forceinline__ bool mpas_is_subnormal_f32(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int magnitude = mpas_f32_magnitude_bits(value);
    return magnitude != 0u && (magnitude & 0x7f800000u) == 0u;
#else
    return false;
#endif
}

// A plain float/double cast is one of the measured DAZ mechanisms, so decode
// a subnormal float from its integer mantissa instead.
__device__ __forceinline__ double mpas_f32_to_f64_ieee(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int bits = __float_as_uint(value);
    const unsigned int magnitude = bits & 0x7fffffffu;
    if (magnitude != 0u && (magnitude & 0x7f800000u) == 0u) {
        const double decoded = ldexp(
            (double)(magnitude & 0x007fffffu), -149);
        return (bits & 0x80000000u) != 0u ? -decoded : decoded;
    }
#endif
    return (double)value;
}

// __double2float_rn flushes an FP32-subnormal result on the certified route,
// so pack that narrow result from the rounded integer mantissa.
__device__ __forceinline__ float mpas_f64_to_f32_ieee(const double value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const double magnitude = fabs(value);
    if (magnitude > 0.0 && magnitude < 1.1754943508222875e-38) {
        const double scaled = rint(
            magnitude * 7.1362384635297994e+44);  // 2^149
        const unsigned int mantissa = (unsigned int)scaled;
        const unsigned int sign =
            (__double_as_longlong(value) < 0LL) ? 0x80000000u : 0u;
        return __uint_as_float(sign | mantissa);
    }
#endif
    return __double2float_rn(value);
}

__device__ __forceinline__ float mpas_add(
    const float left, const float right)
{
    const float ordinary = left + right;
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int result_magnitude = mpas_f32_magnitude_bits(ordinary);
    const unsigned int result_exponent = result_magnitude >> 23;
    // A result at exponent field >=25 cannot have been rounded differently
    // by an FP32 subnormal operand, which is then below half an ulp.
    if (result_exponent > 24u) return ordinary;
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) + mpas_f32_to_f64_ieee(right));
    }
#endif
#if MPAS_FTZ_FALLBACK_ENABLED
    // Two normal binary32 values can cancel into the subnormal range only
    // while both exponent fields are <= 23; above that, one ulp is already
    // at least the smallest normal value.
    if (left_exponent <= 23u && right_exponent <= 23u
            && result_exponent == 0u
            && left_magnitude != right_magnitude
            && left_magnitude != 0u && right_magnitude != 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) + mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_sub(
    const float left, const float right)
{
    const float ordinary = left - right;
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int result_magnitude = mpas_f32_magnitude_bits(ordinary);
    const unsigned int result_exponent = result_magnitude >> 23;
    if (result_exponent > 24u) return ordinary;
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) - mpas_f32_to_f64_ieee(right));
    }
#endif
#if MPAS_FTZ_FALLBACK_ENABLED
    if (left_exponent <= 23u && right_exponent <= 23u
            && result_exponent == 0u
            && left_magnitude != right_magnitude
            && left_magnitude != 0u && right_magnitude != 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) - mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_mul(
    const float left, const float right)
{
    const float ordinary = left * right;
#if MPAS_FTZ_FALLBACK_ENABLED
    // A normal finite/overflow result proves neither operand was lost to DAZ
    // and no FTZ result occurred.  Inspect operands only on the rare zero or
    // subnormal-result envelope.
    if ((mpas_f32_magnitude_bits(ordinary) & 0x7f800000u) == 0u) {
        const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
        const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
        if (left_magnitude != 0u && right_magnitude != 0u) {
            return mpas_f64_to_f32_ieee(
                mpas_f32_to_f64_ieee(left) * mpas_f32_to_f64_ieee(right));
        }
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_div(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) / mpas_f32_to_f64_ieee(right));
    }
#endif
    const float ordinary = left / right;
#if MPAS_FTZ_FALLBACK_ENABLED
    if (left_magnitude != 0u && right_magnitude != 0u
            && left_exponent + 126u <= right_exponent
            && (mpas_f32_magnitude_bits(ordinary) & 0x7f800000u) == 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) / mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_sqrt(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(value)) {
        return mpas_f64_to_f32_ieee(sqrt(mpas_f32_to_f64_ieee(value)));
    }
#endif
    return sqrtf(value);
}

__device__ __forceinline__ float mpas_abs(const float value)
{
    return __uint_as_float(__float_as_uint(value) & 0x7fffffffu);
}

__device__ __forceinline__ float mpas_copysign(
    const float magnitude, const float sign)
{
    return __uint_as_float(
        (__float_as_uint(magnitude) & 0x7fffffffu)
        | (__float_as_uint(sign) & 0x80000000u));
}

__device__ __forceinline__ float mpas_min(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(left) || mpas_is_subnormal_f32(right)) {
        return mpas_f32_to_f64_ieee(right) < mpas_f32_to_f64_ieee(left)
            ? right : left;
    }
#endif
    return fminf(left, right);
}

__device__ __forceinline__ float mpas_max(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(left) || mpas_is_subnormal_f32(right)) {
        return mpas_f32_to_f64_ieee(right) > mpas_f32_to_f64_ieee(left)
            ? right : left;
    }
#endif
    return fmaxf(left, right);
}

#define C2(k,c,nc) ((k)*(nc) + (c))
#define E2(k,e,ne) ((k)*(ne) + (e))
#define S3(s,k,c,nl,nc) ((((s)*(nl) + (k))*(nc)) + (c))

extern "C" __global__ void moist_cell_coefficients_v841_f32(
    const int nlev, const int ncells, const int nmass, const float *scalars,
    float *qtot, float *cqw, int *invalid)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    for (int k = 0; k < nlev; ++k) {
        const int i = C2(k, cell, ncells);
        float total = 0.0f;
        // nmass, not nScalars: only the mass-LOADING species enter qtot.
        // The species row orders them as a contiguous leading run, so one
        // count is the whole rule (hexcore.species_row).  A number
        // concentration folded in here would collapse 1/(1+qtot); a rime
        // MASS that is a component of another species would double-count it.
        for (int species = 0; species < nmass; ++species) {
            const float value = scalars[S3(species, k, cell, nlev, ncells)];
            if (!isfinite(value)) atomicExch(invalid, 1);
            total = mpas_add(total, value);
        }
        if (!isfinite(total)) atomicExch(invalid, 1);
        qtot[i] = total;
    }
    // Native Fortran assigns cqw only for k=2..nVertLevels.  The unused
    // k=1/zero-based boundary is intentionally left untouched here.
    for (int k = 1; k < nlev; ++k) {
        const int i = C2(k, cell, ncells);
        const float total = mpas_mul(0.5f, mpas_add(
            qtot[i], qtot[C2(k - 1, cell, ncells)]));
        const float value = mpas_div(1.0f, mpas_add(1.0f, total));
        if (!isfinite(total) || !isfinite(value)) atomicExch(invalid, 1);
        cqw[i] = value;
    }
}

extern "C" __global__ void moist_edge_coefficients_v841_f32(
    const int nlev, const int ncells, const int nedges, const int nmass,
    const int *cells_on_edge, const float *scalars,
    float *cqu, int *invalid)
{
    const int edge = blockDim.x * blockIdx.x + threadIdx.x;
    if (edge >= nedges) return;
    const int cell1 = cells_on_edge[2 * edge];
    const int cell2 = cells_on_edge[2 * edge + 1];
    for (int k = 0; k < nlev; ++k) {
        float total = 0.0f;
        // See moist_cell_coefficients_v841_f32: nmass is the loading run.
        // The per-species average is summed in species order, NOT summed
        // then averaged -- that ordering is FP32-observable and is what the
        // frozen WSM6 arm's bytes were measured under.
        for (int species = 0; species < nmass; ++species) {
            const float q1 = scalars[S3(species, k, cell1, nlev, ncells)];
            const float q2 = scalars[S3(species, k, cell2, nlev, ncells)];
            if (!isfinite(q1) || !isfinite(q2)) atomicExch(invalid, 1);
            total = mpas_add(total, mpas_mul(0.5f, mpas_add(q1, q2)));
        }
        const float value = mpas_div(1.0f, mpas_add(1.0f, total));
        if (!isfinite(total) || !isfinite(value)) atomicExch(invalid, 1);
        cqu[E2(k, edge, nedges)] = value;
    }
}

extern "C" __global__ void moist_dpdz_v841_f32(
    const int nlev, const int ncells, const float gravity,
    const float *rho_base, const float *density_perturbation,
    const float *qtot, float *dpdz, int *invalid)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    for (int k = 0; k < nlev; ++k) {
        const int i = C2(k, cell, ncells);
        const float moist_base = mpas_mul(rho_base[i], qtot[i]);
        const float moist_perturbation = mpas_mul(density_perturbation[i],
            mpas_add(1.0f, qtot[i]));
        const float value = mpas_mul(mpas_sub(0.0f, gravity),
            mpas_add(moist_base, moist_perturbation));
        if (!isfinite(rho_base[i]) || !isfinite(density_perturbation[i])
                || !isfinite(qtot[i]) || !isfinite(value))
            atomicExch(invalid, 1);
        dpdz[i] = value;
    }
}

extern "C" __global__ void euler_w_moist_v841_f32(
    const int nlev, const int ncells, const float *pressure_p,
    const float *dpdz, const float *cqw, const float *rdzu,
    const float *fzm, const float *fzp, const int has_mixing,
    const float *mixing, float *result, int *invalid)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    for (int k = 0; k <= nlev; ++k) {
        const int index = C2(k, cell, ncells);
        if (k == 0 || k == nlev) {
            result[index] = 0.0f;
        } else {
            const float pressure_term = mpas_mul(rdzu[k], mpas_sub(
                pressure_p[C2(k, cell, ncells)],
                pressure_p[C2(k - 1, cell, ncells)]));
            const float buoyancy = mpas_add(
                mpas_mul(fzm[k], dpdz[C2(k, cell, ncells)]),
                mpas_mul(fzp[k], dpdz[C2(k - 1, cell, ncells)]));
            const float value = mpas_sub(has_mixing ? mixing[index] : 0.0f, mpas_mul(cqw[index],
                mpas_sub(pressure_term, buoyancy)));
            if (!isfinite(cqw[index]) || !isfinite(value))
                atomicExch(invalid, 1);
            result[index] = value;
        }
    }
}

// mpas_atm_time_integration.F:6931-6937: resolved tendency diagnostic
// precedes the carried microphysics heating, Euler mixing and held physics.
extern "C" __global__ void add_lagged_diabatic_theta_v842_f32(
    const int nlev, const int ncells, const float *rho,
    const float *diabatic_theta, float *tend_rt)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    for (int k = 0; k < nlev; ++k) {
        const int i = C2(k, cell, ncells);
        tend_rt[i] = mpas_add(tend_rt[i], mpas_mul(rho[i], diabatic_theta[i]));
    }
}

// mpas_atm_time_integration.F:7949 (atm_bdy_adjust_dynamics_speczone_tend):
// a limited-area run zeroes rt_diabatic_tend in the specified zone at every
// RK stage, in place, so the final recovery (:4436-4437) removes no carry
// there.  Launched only when a carry exists.
extern "C" __global__ void zero_speczone_lagged_diabatic_theta_v842_f32(
    const int nlev, const int ncells, const int nspec,
    const int *spec_cells, float *diabatic_theta)
{
    const int element = blockDim.x * blockIdx.x + threadIdx.x;
    if (element >= nlev * nspec) return;
    const int slot = element % nspec;
    const int k = element / nspec;
    diabatic_theta[C2(k, spec_cells[slot], ncells)] = 0.0f;
}

extern "C" __global__ void modified_theta_dynamics_rate_v841_f32(
    const int nlev, const int ncells, const float *tend_rtheta,
    const float *tend_rho, const float *rho, const float *theta_m,
    float *result, int *invalid)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    for (int k = 0; k < nlev; ++k) {
        const int i = C2(k, cell, ncells);
        const float value = mpas_div(mpas_sub(tend_rtheta[i],
            mpas_mul(tend_rho[i], theta_m[i])), rho[i]);
        if (!isfinite(rho[i]) || rho[i] <= 0.0f || !isfinite(value))
            atomicExch(invalid, 1);
        result[i] = value;
    }
}

extern "C" __global__ void gf_dry_theta_dynamics_rate_v841_f32(
    const int nlev, const int ncells, const float rvord,
    const float *modified_rate, const float *theta_m,
    const float *qv, float *rthdynten, float *rqvdynten, int *invalid)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    for (int k = 0; k < nlev; ++k) {
        const int i = C2(k, cell, ncells);
        const float rqv = 0.0f;
        const float fac_m = mpas_div(1.0f,
            mpas_add(1.0f, mpas_mul(rvord, qv[i])));
        const float theta_local = mpas_mul(theta_m[i], fac_m);
        const float value = mpas_mul(fac_m, mpas_sub(modified_rate[i],
            mpas_mul(mpas_mul(theta_local, rvord), rqv)));
        if (!isfinite(qv[i]) || !isfinite(fac_m) || fac_m <= 0.0f
                || !isfinite(value)) atomicExch(invalid, 1);
        rqvdynten[i] = rqv;
        rthdynten[i] = value;
    }
}

