        z, NMP_EXP2F_SHIFT,
        NMP_EXP2F_P0 / 32.0 / 32.0 / 32.0,
        NMP_EXP2F_P1 / 32.0 / 32.0,
        NMP_EXP2F_P2 / 32.0, 0u));
