                t = RLW_AD(t, RLW_MU(fac000, A2(absa, 585, ind0 + 1, ig)));
                t = RLW_AD(t, RLW_MU(fac210, A2(absa, 585, ind0 + 8, ig)));
                t = RLW_AD(t, RLW_MU(fac110, A2(absa, 585, ind0 + 9, ig)));
