extern "C" __global__ void ozone_latitude(int nc,int nl,const float *lat,
    const float *lat_oz,const float *table,float *monthly) {
    int idx=blockIdx.x*blockDim.x+threadIdx.x;
    if(idx>=nc*nl*12) return;
