        theta_after[i], mpas_add(1.0f, mpas_mul(rvord, qv_coupled)));
    const float value = mpas_div(mpas_sub(theta_m_after, theta_m_before[i]), dt);
    if (!isfinite(value)) atomicExch(invalid, 1);
    rate[i] = value;
}

