    if (a > 0.0 && a < 1.1754943508222875e-38) {
        double scaled = rint(a * 7.1362384635297994e+44);
        unsigned int m = (unsigned int)scaled;
        unsigned int s = (__double_as_longlong(y) < 0LL) ? 0x80000000u : 0u;
        return __uint_as_float(s | m);
