    float refrat_planck_b = RLW_DV(CHI35(3, 43), CHI35(2, 43));
    // P = 317.3480 mb                      chi_mls(1,7)/chi_mls(2,7)
    float refrat_m_a = RLW_DV(CHI35(1, 7), CHI35(2, 7));

