                                              RLW_SU(o3m2, o3m1)));

            float tau_major = rlw_b35_major(f0, absa, ind0, ig, s0.comb);
            float tau_major1 = rlw_b35_major(f1, absa, ind1, ig, s1.comb);

            float t = RLW_AD(tau_major, tau_major1);
            t = RLW_AD(t, tauself);
            t = RLW_AD(t, taufor);
            t = RLW_AD(t, RLW_MU(abso3, FS(SL_COLO3)));
