                                       chi_mls[2 + 7 * 2]);
        float refrat_m_a = RLW_DV(chi_mls[0 + 7 * 2], chi_mls[2 + 7 * 2]);

        int jpv = IS(SI_JP);
        float colh2o = FS(SL_COLH2O);
        float colo3 = FS(SL_COLO3);

