__device__ __forceinline__ float esat_horner(float t, const float *c)
{
    float acc = FA(c[5], FM(t, c[6]));
    acc = FA(c[4], FM(t, acc));
    acc = FA(c[3], FM(t, acc));
    acc = FA(c[2], FM(t, acc));
    acc = FA(c[1], FM(t, acc));
