static __device__ __forceinline__ real rsw_rn_add(real a, real b)
{
    real r;
    asm("add.rn.f32 %0, %1, %2;" : "=f"(r) : "f"(a), "f"(b));
    return mpas_sw_nan_result(r,a,b);
