static __device__ __forceinline__ real rsw_rn_sub(real a, real b)
{
    real r;
    asm("sub.rn.f32 %0, %1, %2;" : "=f"(r) : "f"(a), "f"(b));
    return mpas_sw_nan_result(r,a,b);
