                             fac00[L], fac01[L], fac10[L], fac11[L]);
        const real* sf = tab + RSW_T_KG19_SFLUXREF;
        real a = sf[ig + 8 * (s.js - 1)], b = sf[ig + 8 * s.js];
        v = AD(a, MU(s.fs, SU(b, a)));
        break;
    }
    case 20:
