extern "C" __global__ void ntiedtke_llo3_mask(const CArray<int, 2, 0, 1> _raw_top, const CArray<int, 2, 1, 1> _raw_label, CArray<int, 1, 1, 1> _raw_mask, CIndexer<2, 1> _in_ind, CIndexer<1, 1> _out_ind, const int _block_stride) {
