    del[t] = DV(d[t], b[t]);                                       // :5570
    for (int k = ntop + 1; k <= NMP_NSOIL; ++k) {                  // :5574-5578
        int i = k + NMP_OFF;
        real recip = DV(1.0f, AD(b[i], MU(a[i], p[i - 1])));
