        del[i] = MU(SU(d[i], MU(a[i], del[i - 1])), recip);
    }
    p[NMP_NSOIL + NMP_OFF] = del[NMP_NSOIL + NMP_OFF];             // :5582
    for (int k = ntop + 1; k <= NMP_NSOIL; ++k) {                  // :5586-5589
