__device__ __forceinline__ bool mynn_gt(real a, real b)
{
    unsigned int p;
    asm("{ .reg .pred q; setp.gt.f32 q, %1, %2; selp.u32 %0, 1, 0, q; }"
        : "=r"(p) : "f"(a), "f"(b));
    return p != 0u;
}

__device__ __forceinline__ real mynn_max2(real a, real b)
{
    return mynn_gt(b, a) ? b : a;
}

