extern "C" __global__ void rp_prep(
    int ncol, int nk, int nl, int sw, int icloud, int warm,
    int fqc, int fqr, int fqi, int fqs, int hc, int hi, int hs,
    int inflg, int iceflg, int o3input, int ferrier, float g,
    const float* p, const float* pw, const float* t, const float* tw,
    const float* dz, const float* qv, const float* qc, const float* qr,
    const float* qi, const float* qs, const float* cf, const float* oz,
    const float* rc, const float* ri, const float* rs,
    const float* land, const float* ice, const float* snow,
    const float* retab, const float* pp, const float* tp,
    const float* ow, const float* ph,
    float* pl, float* tl, float* pa, float* ta, float* hg,
    float* hv, float* ov, float* o31, float* pd,
    float* cl, float* cw, float* iw, float* snw,
    float* rel, float* rei, float* res) {
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= ncol) return;
    int a = c*nk, b = c*nl, e = c*(nl+1), w = c*(nk+1);
    float dzsum = 0.0f;
    for (int k=0; k<=nk; ++k) {
        pl[e+k] = RP_DV(pw[w+k], 100.0f);
        tl[e+k] = tw[w+k];
    }
    for (int k=0; k<nk; ++k) {
        pa[b+k] = RP_DV(p[a+k], 100.0f);
        ta[b+k] = t[a+k];
        pd[a+k] = RP_SU(pl[e+k], pl[e+k+1]);
        float v = rp_max(0.0f, qv[a+k]);
        v = rp_max(v, 1.e-12f);
        hv[b+k] = RP_MU(v, 1.607793f);
        hg[b+k] = RP_AD(dzsum, RP_MU(0.5f, dz[a+k]));
        dzsum = RP_AD(dzsum, dz[a+k]);
    }
    float lastdz = dz[a+nk-1];
    if (sw) {
        pa[b+nk] = RP_MU(0.5f, pl[e+nk]);
        ta[b+nk] = RP_AD(tl[e+nk], 0.0f);
        pl[e+nk+1] = 1.e-5f;
        tl[e+nk+1] = RP_AD(tl[e+nk], 0.0f);
        hv[b+nk] = hv[b+nk-1];
        hg[b+nk] = RP_AD(dzsum, RP_MU(0.5f, lastdz));
    } else {
        // The final interface is overwritten with zero below. Only the
        // preceding nl-nk-1 decrements must stay positive. Ordinary WRF
        // tops retain their prescribed 4-hPa spacing.
        float dp = 4.0f;
        if (pl[e+nk] <= RP_MU(4.0f, (float)(nl-nk-1)))
            dp = rp_min(4.0f, RP_DV(pl[e+nk], (float)(nl-nk)));
        for (int k=nk; k<nl; ++k) {
            pl[e+k+1] = RP_SU(pl[e+k], dp);
            pa[b+k] = RP_MU(0.5f, RP_AD(pl[e+k], pl[e+k+1]));
            hv[b+k] = hv[b+nk-1];
            hg[b+k] = RP_AD(dzsum, RP_MU(0.5f, lastdz));
            dzsum = RP_AD(dzsum, lastdz);
        }
        pl[e+nl] = 0.0f;
        pa[b+nl-1] = RP_MU(0.5f, RP_AD(pl[e+nl-1], pl[e+nl]));
        float anchor = RP_SU(tl[e+nk-1], rp_varint(pl[e+nk-1], pp, tp));
        for (int k=nk; k<=nl; ++k)
            tl[e+k] = RP_AD(rp_varint(pl[e+k], pp, tp), anchor);
        for (int k=nk-1; k<nl; ++k)
            ta[b+k] = RP_MU(0.5f, RP_AD(tl[e+k+1], tl[e+k]));
    }
    float obase = 0.0f;
    if (o3input == 2)
        obase = RP_SU(oz[a+nk-1], RP_MU(rp_o3(pl[e+nk-1], pl[e+nk], ow, ph), 0.603461f));
    for (int k=0; k<nl; ++k) {
        float clim = RP_MU(rp_o3(pl[e+k], pl[e+k+1], ow, ph), 0.603461f);
        float v = RP_AD(obase, clim);
        ov[b+k] = o3input == 2 ? (k<nk ? oz[a+k] : (v<=0.0f ? clim : v)) : clim;
        if (k<nk) o31[a+k] = ov[b+k];
        cl[b+k] = 0.0f; cw[b+k] = 0.0f; iw[b+k] = 0.0f; snw[b+k] = 0.0f;
        rel[b+k] = 10.0f; rei[b+k] = 10.0f; res[b+k] = 10.0f;
        if (k>=nk) continue;
        int j = a+k;
        float qcl=0.0f, qrain=0.0f, qice=0.0f, qsnow=0.0f;
        if (icloud) {
            cl[b+k] = cf[j];
            if (fqc) qcl = rp_max(0.0f, qc[j]);
            if (fqr) qrain = rp_max(0.0f, qr[j]);
            if (!fqi && !warm && t[j]<273.15f) {
                qice=qcl; qsnow=qrain; qcl=0.0f; qrain=0.0f;
            }
            if (fqi) qice = rp_max(0.0f, qi[j]);
            if (fqs) qsnow = rp_max(0.0f, qs[j]);
        }
        // FER_MP_HIRES remaps total ice outside ICLOUD in both wrappers.
        if (ferrier) {
            qice = rp_max(0.0f, qi[j]);
            qsnow = 0.0f;
            qcl = rp_max(0.0f, qc[j]);
        }
        float rec=0.0f, ric=0.0f, rsc=0.0f;
        if (icloud) {
            rec = hc ? rp_max(2.5f, RP_RADIUS(rc[j])) : 5.0f;
            float xdiff = RP_SU(land[c], 1.5f);
            if (hc && xdiff>0.0f && rec<=2.5f && cf[j]>0.0f) rec=(sw && RP_CLOUD_FORM) ? 9.6f : 10.5f;
            if (hc && xdiff<0.0f && rec<=2.5f && cf[j]>0.0f) rec=(sw && RP_CLOUD_FORM) ? 5.4f : 7.5f;
            ric = hi ? rp_max(5.0f, RP_RADIUS(ri[j])) : 10.0f;
            if (hi && ric<=5.0f && cf[j]>0.0f)
                ric = rp_max(rp_rei(t[j], retab, 75), 5.0f);
            rsc = hs ? rp_max(10.0f, RP_RADIUS(rs[j])) : 10.0f;
            if (!hs && hi && hc) {
                rsc = rp_max(10.0f, RP_RADIUS(ri[j]));
                qsnow=qi[j]; qice=0.0f; ric=10.0f;
            }
        }
        float den = rp_max(0.01f, cl[b+k]);
        cw[b+k] = RP_DV(rp_path(qcl, pd[j], g), den);
        float iq = iceflg>=4 ? qice : RP_AD(qice, qsnow);
        iw[b+k] = RP_DV(rp_path(iq, pd[j], g), den);
        if (iceflg==5) {
            float smf=RP_CLOUD_FORM ? 1.0f : 0.99f;
            if (rsc>130.0f) {
                float q=RP_DV(130.0f, rsc);
                smf=rp_min(smf, RP_MU(q,q)); rsc=130.0f;
            }
            snw[b+k] = RP_DV(rp_path(RP_MU(qsnow,smf), pd[j], g), den);
        }
        float rliq = RP_AD(8.0f, RP_MU(6.0f, rp_clip(RP_MU(RP_SU(273.16f, ta[b+k]), 0.05f))));
        float wt = rp_clip(RP_MU(RP_MU(0.001f, snow[c]), 10.0f));
        rliq = RP_AD(rliq, RP_MU(RP_SU(14.0f,rliq), wt));
        wt = rp_clip(RP_SU(1.0f, RP_SU(2.0f,land[c])));
        rliq = RP_AD(rliq, RP_MU(RP_SU(14.0f,rliq), wt));
        rliq = RP_AD(rliq, RP_MU(RP_SU(14.0f,rliq), rp_clip(ice[c])));
        float rice = rp_rei(ta[b+k], retab, 94);
        if (inflg>=3) rliq=rec;
        if (iceflg>=4) rice=ric;
        if (iceflg==3) rice=rp_min(140.0f, RP_MU(rice,1.0315f));
        rel[b+k]=rliq; rei[b+k]=rice;
        if (inflg==5) res[b+k]=rsc;
    }
}

extern "C" __global__ void rp_scon(int n, const float* sol, const float* obsc, float* out) {
    int i=blockIdx.x*blockDim.x+threadIdx.x;
    if (i<n) out[i]=RP_MU(sol[i], RP_SU(1.0f,obsc[i]));
}

extern "C" __global__ void rp_day(int n, const float* coszen, unsigned char* night) {
    int i=blockIdx.x*blockDim.x+threadIdx.x;
    if (i<n) night[i]=coszen[i]<=0.0f;
}

// WRF 4.6.1 public-domain module_radiation_driver.F:3676-3749.
// QI alone takes the zero arm. No clipping before the float32 sum.
extern "C" __global__ void rp_cldfra2(
    int n, int fqc, int fqi, const float* qc, const float* qi, float* cf) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;
    float condensate;
    if (fqi && fqc) condensate = RP_AD(qc[i], qi[i]);
    else if (fqc) condensate = qc[i];
    else { cf[i] = 0.0f; return; }
    cf[i] = condensate > 1.0e-6f ? 1.0f : 0.0f;
}

#include <cupy/complex.cuh>
#include <cupy/carray.cuh>
#include <cupy/atomics.cuh>
#include <cupy/math_constants.h>

#include <cub/block/block_reduce.cuh>
#include <cub/block/block_load.cuh>

typedef bool type_in0_raw;
typedef bool type_out0_raw;
typedef int IndexT;
typedef int sizeT;



typedef bool _type_reduce;

static_assert(sizeof(_type_reduce) <= 32,
    "The intermediate reduction type is assumed to be at most 32 bytes.");

// Compile-time constants for CUB template specializations
#define ITEMS_PER_THREAD  4
#define BLOCK_SIZE        512

// for hipCUB: use the hipcub namespace
#ifdef __HIP_DEVICE_COMPILE__
#define cub hipcub
#endif

#if defined FIRST_PASS
    typedef type_in0_raw  type_mid_in;
    typedef _type_reduce  type_mid_out;
    #define POST_MAP(a)   out0 = a;
#elif defined SECOND_PASS
    typedef _type_reduce  type_mid_in;
    typedef type_out0_raw type_mid_out;
    #define POST_MAP(a)   (out0 = a)
#else  // one-pass reduction
    typedef type_in0_raw  type_mid_in;
    typedef type_out0_raw type_mid_out;
    #define POST_MAP(a)   (out0 = a)
#endif

struct _reduction_op {
    __device__ __forceinline__ _type_reduce operator()(
        const _type_reduce &a, const _type_reduce &b) const {
        return a | b;
    }
};

extern "C"
__global__ void cupy_cub_any_pass2(const void* _raw_in0, void* _raw_out0, const int _segment_size, const int _array_size) {
  unsigned int _tid = threadIdx.x;

  // Specialize BlockLoad type for faster (?) loading
  typedef cub::BlockLoad<_type_reduce, BLOCK_SIZE,
                         ITEMS_PER_THREAD, cub::BLOCK_LOAD_DIRECT> BlockLoadT;

  // Shared memory for loading
  __shared__ typename BlockLoadT::TempStorage temp_storage_load;

  // Specialize BlockReduce type for our thread block
  typedef cub::BlockReduce<_type_reduce, BLOCK_SIZE> BlockReduceT;

  // Shared memory for reduction
  __shared__ typename BlockReduceT::TempStorage temp_storage;

  // Declare reduction operation
  _reduction_op op;

  // input & output raw pointers
  const type_mid_in* _in0 = static_cast<const type_mid_in*>(_raw_in0);
  type_mid_out* _out0 = static_cast<type_mid_out*>(_raw_out0);

  // Per-thread tile data
  _type_reduce _sdata[ITEMS_PER_THREAD];
  #pragma unroll
  for (int j = 0; j < ITEMS_PER_THREAD; j++) {
      _sdata[j] = _type_reduce(false);
  }

  // each block handles the reduction of 1 segment
  size_t segment_idx = size_t(blockIdx.x) * _segment_size;
  const type_mid_in* segment_head = _in0 + segment_idx;
  size_t i = 0;  // tile head within the segment
  int tile_size = (BLOCK_SIZE * ITEMS_PER_THREAD < _segment_size ?
                   BLOCK_SIZE * ITEMS_PER_THREAD :
                   _segment_size);
  sizeT _seg_size = _segment_size;

  #if defined FIRST_PASS
  // for two-pass reduction only: "last segment" is special
  if (_array_size > 0) {
      if (_array_size - segment_idx <= _segment_size) {
          _seg_size = _array_size - segment_idx;
      }
      #ifdef __HIP_DEVICE_COMPILE__
      // We don't understand HIP...
      __syncthreads();  // Propagate the new value back to memory
      #endif
  }
  #endif

  // loop over tiles within 1 segment
  _type_reduce aggregate = _type_reduce(false);
  for (i = 0; i < _seg_size; i += BLOCK_SIZE * ITEMS_PER_THREAD) {
      // for the last tile
      if (_seg_size - i <= tile_size) { tile_size = _seg_size - i; }

      // load a tile
      BlockLoadT(temp_storage_load).Load(segment_head + i, _sdata, tile_size,
                                         _type_reduce(false));

      // Compute block reduction
      // Note that the output is only meaningful for thread 0
      aggregate = op(aggregate, BlockReduceT(temp_storage).Reduce(_sdata, op));

      __syncthreads();  // for reusing temp_storage
  }

  if (_tid == 0) {
      type_mid_out& out0 = *(_out0 + blockIdx.x);
      POST_MAP(aggregate);
  }
}

#ifndef MPAS_FTZ_FALLBACK_ENABLED
#define MPAS_FTZ_FALLBACK_ENABLED 1
#endif

__device__ __forceinline__ unsigned int mpas_f32_magnitude_bits(
    const float value)
{
    return __float_as_uint(value) & 0x7fffffffu;
}

__device__ __forceinline__ bool mpas_is_subnormal_f32(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int magnitude = mpas_f32_magnitude_bits(value);
    return magnitude != 0u && (magnitude & 0x7f800000u) == 0u;
#else
    return false;
#endif
}

// A plain float/double cast is one of the measured DAZ mechanisms, so decode
// a subnormal float from its integer mantissa instead.
__device__ __forceinline__ double mpas_f32_to_f64_ieee(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int bits = __float_as_uint(value);
    const unsigned int magnitude = bits & 0x7fffffffu;
    if (magnitude != 0u && (magnitude & 0x7f800000u) == 0u) {
        const double decoded = ldexp(
            (double)(magnitude & 0x007fffffu), -149);
        return (bits & 0x80000000u) != 0u ? -decoded : decoded;
    }
#endif
    return (double)value;
}

// __double2float_rn flushes an FP32-subnormal result on the certified route,
// so pack that narrow result from the rounded integer mantissa.
__device__ __forceinline__ float mpas_f64_to_f32_ieee(const double value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const double magnitude = fabs(value);
    if (magnitude > 0.0 && magnitude < 1.1754943508222875e-38) {
        const double scaled = rint(
            magnitude * 7.1362384635297994e+44);  // 2^149
        const unsigned int mantissa = (unsigned int)scaled;
        const unsigned int sign =
            (__double_as_longlong(value) < 0LL) ? 0x80000000u : 0u;
        return __uint_as_float(sign | mantissa);
    }
#endif
    return __double2float_rn(value);
}

__device__ __forceinline__ float mpas_add(
    const float left, const float right)
{
    const float ordinary = left + right;
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int result_magnitude = mpas_f32_magnitude_bits(ordinary);
    const unsigned int result_exponent = result_magnitude >> 23;
    // A result at exponent field >=25 cannot have been rounded differently
    // by an FP32 subnormal operand, which is then below half an ulp.
    if (result_exponent > 24u) return ordinary;
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) + mpas_f32_to_f64_ieee(right));
    }
#endif
#if MPAS_FTZ_FALLBACK_ENABLED
    // Two normal binary32 values can cancel into the subnormal range only
    // while both exponent fields are <= 23; above that, one ulp is already
    // at least the smallest normal value.
    if (left_exponent <= 23u && right_exponent <= 23u
            && result_exponent == 0u
            && left_magnitude != right_magnitude
            && left_magnitude != 0u && right_magnitude != 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) + mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_sub(
    const float left, const float right)
{
    const float ordinary = left - right;
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int result_magnitude = mpas_f32_magnitude_bits(ordinary);
    const unsigned int result_exponent = result_magnitude >> 23;
    if (result_exponent > 24u) return ordinary;
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) - mpas_f32_to_f64_ieee(right));
    }
#endif
#if MPAS_FTZ_FALLBACK_ENABLED
    if (left_exponent <= 23u && right_exponent <= 23u
            && result_exponent == 0u
            && left_magnitude != right_magnitude
            && left_magnitude != 0u && right_magnitude != 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) - mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_mul(
    const float left, const float right)
{
    const float ordinary = left * right;
#if MPAS_FTZ_FALLBACK_ENABLED
    // A normal finite/overflow result proves neither operand was lost to DAZ
    // and no FTZ result occurred.  Inspect operands only on the rare zero or
    // subnormal-result envelope.
    if ((mpas_f32_magnitude_bits(ordinary) & 0x7f800000u) == 0u) {
        const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
        const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
        if (left_magnitude != 0u && right_magnitude != 0u) {
            return mpas_f64_to_f32_ieee(
                mpas_f32_to_f64_ieee(left) * mpas_f32_to_f64_ieee(right));
        }
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_div(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) / mpas_f32_to_f64_ieee(right));
    }
#endif
    const float ordinary = left / right;
#if MPAS_FTZ_FALLBACK_ENABLED
    if (left_magnitude != 0u && right_magnitude != 0u
            && left_exponent + 126u <= right_exponent
            && (mpas_f32_magnitude_bits(ordinary) & 0x7f800000u) == 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) / mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_sqrt(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(value)) {
        return mpas_f64_to_f32_ieee(sqrt(mpas_f32_to_f64_ieee(value)));
    }
#endif
    return sqrtf(value);
}

__device__ __forceinline__ float mpas_abs(const float value)
{
    return __uint_as_float(__float_as_uint(value) & 0x7fffffffu);
}

__device__ __forceinline__ float mpas_copysign(
    const float magnitude, const float sign)
{
    return __uint_as_float(
        (__float_as_uint(magnitude) & 0x7fffffffu)
        | (__float_as_uint(sign) & 0x80000000u));
}

__device__ __forceinline__ float mpas_min(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(left) || mpas_is_subnormal_f32(right)) {
        return mpas_f32_to_f64_ieee(right) < mpas_f32_to_f64_ieee(left)
            ? right : left;
    }
#endif
    return fminf(left, right);
}

__device__ __forceinline__ float mpas_max(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(left) || mpas_is_subnormal_f32(right)) {
        return mpas_f32_to_f64_ieee(right) > mpas_f32_to_f64_ieee(left)
            ? right : left;
    }
#endif
    return fmaxf(left, right);
}

#define GWDO_NLEV 55

extern "C" __global__ void bl_ysu_gwdo_v841_f32(
    const int nlev, const int ncells, const float dt,
    const float len_disp, const float gravity, const float cp,
    const float rd, const float fv, const float pi,
    const float *u, const float *v, const float *temperature,
    const float *qv, const float *p_mass_dry_hyd,
    const float *p_interface_dry_hyd, const float *exner,
    const float *zmid, const float *rublten_in,
    const float *rvblten_in, const float *mesh_density,
    const float *var2d, const float *oc1, const float *oa1,
    const float *oa2, const float *oa3, const float *oa4,
    const float *ol1, const float *ol2, const float *ol3,
    const float *ol4, float *rublten_out, float *rvblten_out,
    float *dtaux3d, float *dtauy3d, float *dusfcg,
    float *dvsfcg, float *rubldiff, float *rvbldiff,
    int *invalid)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    if (nlev != GWDO_NLEV) {
        atomicExch(invalid, 1);
        return;
    }

    const float md = mesh_density[cell];
    bool bad = !isfinite(dt) || dt <= 0.0f || !isfinite(len_disp)
        || len_disp <= 0.0f || !isfinite(md) || md <= 0.0f || md > 1.0f
        || !isfinite(var2d[cell]) || var2d[cell] < 0.0f
        || !isfinite(oc1[cell]) || oc1[cell] < 0.0f;
    const float oa_input[4] = {oa1[cell], oa2[cell], oa3[cell], oa4[cell]};
    const float ol_input[4] = {ol1[cell], ol2[cell], ol3[cell], ol4[cell]};
    for (int j = 0; j < 4; ++j) {
        bad = bad || !isfinite(oa_input[j]) || oa_input[j] < -1.0f
            || oa_input[j] > 1.0f || !isfinite(ol_input[j])
            || ol_input[j] < 0.0f || ol_input[j] > 1.0f;
    }
    for (int k = 0; k < nlev; ++k) {
        const int i = k * ncells + cell;
        bad = bad || !isfinite(u[i]) || !isfinite(v[i])
            || !isfinite(temperature[i]) || temperature[i] <= 0.0f
            || !isfinite(qv[i]) || qv[i] < 0.0f
            || !isfinite(p_mass_dry_hyd[i]) || p_mass_dry_hyd[i] <= 0.0f
            || !isfinite(exner[i]) || exner[i] <= 0.0f
            || !isfinite(zmid[i]) || !isfinite(rublten_in[i])
            || !isfinite(rvblten_in[i]);
        const int ii = k * ncells + cell;
        const int ii_above = (k + 1) * ncells + cell;
        bad = bad || !isfinite(p_interface_dry_hyd[ii])
            || p_interface_dry_hyd[ii] <= 0.0f;
        if (k + 1 < nlev) {
            bad = bad || !(p_mass_dry_hyd[i] > p_mass_dry_hyd[i + ncells])
                || !(zmid[i + ncells] > zmid[i]);
        }
        if (k == nlev - 1) {
            bad = bad || !isfinite(p_interface_dry_hyd[ii_above])
                || p_interface_dry_hyd[ii_above] <= 0.0f;
        }
        bad = bad || !(p_interface_dry_hyd[ii]
            > p_interface_dry_hyd[ii_above]);
    }
    if (bad) {
        atomicExch(invalid, 1);
        return;
    }

    float vtj[GWDO_NLEV];
    float vtk[GWDO_NLEV];
    float rho[GWDO_NLEV];
    float delta_p[GWDO_NLEV];
    float u1[GWDO_NLEV];
    float v1[GWDO_NLEV];
    float usqj[GWDO_NLEV];
    float bnv2[GWDO_NLEV];
    float velco[GWDO_NLEV - 1];
    float taup[GWDO_NLEV + 1];
    float taufb[GWDO_NLEV + 1];
    float taud[GWDO_NLEV];
    for (int k = 0; k < nlev; ++k) {
        usqj[k] = 0.0f;
        bnv2[k] = 0.0f;
        taud[k] = 0.0f;
    }
    for (int k = 0; k <= nlev; ++k) {
        taup[k] = 0.0f;
        taufb[k] = 0.0f;
    }

    const float dx = mpas_div(len_disp, powf(md, 0.25f));
    const float diagonal = mpas_sqrt(
        mpas_add(mpas_mul(dx, dx), mpas_mul(dx, dx)));
    const float dxy4[4] = {dx, dx, diagonal, diagonal};
    const float dxy4p[4] = {dx, dx, diagonal, diagonal};
    for (int k = 0; k < nlev; ++k) {
        const int i = k * ncells + cell;
        const int ip = (k + 1) * ncells + cell;
        const float virtual_factor = mpas_add(1.0f, mpas_mul(fv, qv[i]));
        vtj[k] = mpas_mul(temperature[i], virtual_factor);
        vtk[k] = mpas_div(vtj[k], exner[i]);
        rho[k] = mpas_div(
            mpas_mul(mpas_div(1.0f, rd), p_mass_dry_hyd[i]), vtj[k]);
        delta_p[k] = mpas_sub(
            p_interface_dry_hyd[i], p_interface_dry_hyd[ip]);
        u1[k] = u[i];
        v1[k] = v[i];
    }

    const float zlowtop = mpas_mul(2.0f, var2d[cell]);
    int klowtop = 0;
    for (int k = 1; k < nlev; ++k) {
        const float height = mpas_sub(
            zmid[k * ncells + cell], zmid[cell]);
        if (zlowtop > 0.0f && klowtop == 0 && height >= zlowtop)
            klowtop = k + 2;
    }
    int kbl = klowtop;
    if (kbl > nlev) kbl = nlev;
    if (kbl < 2) kbl = 2;
    const float delks = mpas_div(
        1.0f, mpas_sub(p_interface_dry_hyd[cell],
            p_interface_dry_hyd[(kbl - 1) * ncells + cell]));
    const float delks1 = mpas_div(
        1.0f, mpas_sub(p_mass_dry_hyd[cell],
            p_mass_dry_hyd[(kbl - 1) * ncells + cell]));
    float ubar = 0.0f;
    float vbar = 0.0f;
    float rhobar = 0.0f;
    for (int k = 0; k < nlev; ++k) {
        if (k + 1 < kbl) {
            const float weight = mpas_mul(delta_p[k], delks);
            ubar = mpas_add(ubar, mpas_mul(weight, u1[k]));
            vbar = mpas_add(vbar, mpas_mul(weight, v1[k]));
            rhobar = mpas_add(rhobar, mpas_mul(weight, rho[k]));
        }
    }

    const int nwdir[8] = {6, 7, 5, 8, 2, 3, 1, 4};
    const float fdir = mpas_div(8.0f, mpas_mul(2.0f, pi));
    const float wdir = mpas_add(atan2f(ubar, vbar), pi);
    const int nearest = (int)floorf(mpas_add(mpas_mul(fdir, wdir), 0.5f));
    const int nwd = nwdir[nearest % 8];
    const int direction = (nwd - 1) % 4;
    const int sign = 1 - 2 * ((nwd - 1) / 4);
    const float oa = mpas_mul((float)sign, oa_input[direction]);
    const float ol = ol_input[direction];
    const float ol_perp[4] = {
        ol_input[1], ol_input[0], ol_input[3], ol_input[2]};
    const float olp = ol_perp[direction];
    float od = mpas_div(olp, mpas_max(ol, 1.0e-5f));
    od = mpas_max(mpas_min(od, 10.0f), 0.1f);
    const float dxy = dxy4[direction];
    const float dxyp = dxy4p[direction];

    for (int k = 0; k < nlev - 1; ++k) {
        const int i = k * ncells + cell;
        const int ia = i + ncells;
        const float ti = mpas_div(
            2.0f, mpas_add(temperature[i], temperature[ia]));
        const float rdz = mpas_div(1.0f, mpas_sub(zmid[ia], zmid[i]));
        const float du = mpas_sub(u1[k], u1[k + 1]);
        const float dv = mpas_sub(v1[k], v1[k + 1]);
        const float dw2 = mpas_add(mpas_mul(du, du), mpas_mul(dv, dv));
        const float shr2 = mpas_mul(
            mpas_mul(mpas_max(dw2, 1.0f), rdz), rdz);
        const float stability = mpas_add(
            mpas_div(gravity, cp), mpas_mul(rdz, mpas_sub(vtj[k + 1], vtj[k])));
        const float bvf2 = mpas_mul(mpas_mul(gravity, stability), ti);
        usqj[k] = mpas_max(mpas_div(bvf2, shr2), -100.0f);
        bnv2[k] = mpas_div(
            mpas_mul(mpas_mul(mpas_mul(2.0f, gravity), rdz),
                mpas_sub(vtk[k + 1], vtk[k])),
            mpas_add(vtk[k + 1], vtk[k]));
    }

    float ulow = mpas_sqrt(mpas_add(mpas_mul(ubar, ubar), mpas_mul(vbar, vbar)));
    ulow = mpas_max(ulow, 1.0f);
    const float rulow = mpas_div(1.0f, ulow);
    for (int k = 0; k < nlev - 1; ++k) {
        float aligned = mpas_add(
            mpas_mul(mpas_add(u1[k], u1[k + 1]), ubar),
            mpas_mul(mpas_add(v1[k], v1[k + 1]), vbar));
        velco[k] = mpas_mul(mpas_mul(0.5f, aligned), rulow);
        if (velco[k] < 1.0f && velco[k] > 0.0f) velco[k] = 1.0f;
    }
    bool ldrag = velco[0] <= 0.0f;
    for (int kf = 2; kf <= nlev; ++kf) {
        if (kf < kbl && velco[kf - 1] <= 0.0f) ldrag = true;
    }

    const float first_weight = mpas_mul(
        mpas_sub(p_mass_dry_hyd[cell], p_mass_dry_hyd[ncells + cell]),
        delks1);
    bnv2[0] = mpas_mul(first_weight, bnv2[0]);
    usqj[0] = mpas_mul(first_weight, usqj[0]);
    for (int kf = 2; kf <= nlev; ++kf) {
        if (kf < kbl) {
            const int k = kf - 1;
            const float pressure_weight = mpas_mul(
                mpas_sub(p_mass_dry_hyd[k * ncells + cell],
                    p_mass_dry_hyd[(k + 1) * ncells + cell]), delks1);
            bnv2[0] = mpas_add(bnv2[0], mpas_mul(bnv2[k], pressure_weight));
            usqj[0] = mpas_add(usqj[0], mpas_mul(usqj[k], pressure_weight));
        }
    }
    ldrag = ldrag || bnv2[0] <= 0.0f || ulow == 1.0f || var2d[cell] <= 0.0f;
    for (int kf = 2; kf <= nlev; ++kf) {
        if (kf < kbl) usqj[kf - 1] = usqj[0];
    }

    float bnv = 0.0f;
    float fr = 0.0f;
    float xn = 0.0f;
    float yn = 0.0f;
    if (!ldrag) {
        bnv = mpas_sqrt(bnv2[0]);
        fr = mpas_mul(mpas_mul(mpas_mul(bnv, rulow), var2d[cell]), od);
        fr = mpas_min(fr, 10.0f);
        xn = mpas_mul(ubar, rulow);
        yn = mpas_mul(vbar, rulow);
    }

    float coefm = 0.0f;
    float taub = 0.0f;
    if (!ldrag) {
        float efact = powf(mpas_add(oa, 2.0f), mpas_mul(0.8f, fr));
        efact = mpas_min(mpas_max(efact, 0.0f), 10.0f);
        coefm = powf(mpas_add(1.0f, ol), mpas_add(oa, 1.0f));
        const float xlinv = mpas_div(coefm, dx);
        const float tem = mpas_mul(mpas_mul(fr, fr), oc1[cell]);
        const float gfobnv = mpas_div(
            tem, mpas_mul(mpas_add(tem, 0.5f), bnv));
        taub = mpas_mul(xlinv, rhobar);
        taub = mpas_mul(taub, ulow);
        taub = mpas_mul(taub, ulow);
        taub = mpas_mul(taub, ulow);
        taub = mpas_mul(mpas_mul(taub, gfobnv), efact);
    }
    for (int kf = 1; kf <= nlev; ++kf) {
        if (kf <= kbl) taup[kf - 1] = taub;
    }

    bool icrilv = false;
    for (int kf = 2; kf < nlev; ++kf) {
        const int k = kf - 1;
        const int kp1 = k + 1;
        float brvf = 0.0f;
        if (kf >= kbl) {
            icrilv = icrilv || usqj[k] < 0.25f || velco[k] <= 0.0f;
            brvf = mpas_sqrt(mpas_max(bnv2[k], 1.0e-5f));
        }
        if (kf >= kbl && !ldrag && !icrilv && taup[k] > 0.0f) {
            const float temv = mpas_div(1.0f, velco[k]);
            float tem1 = mpas_div(coefm, dxy);
            tem1 = mpas_mul(tem1, mpas_add(rho[kp1], rho[k]));
            tem1 = mpas_mul(tem1, brvf);
            tem1 = mpas_mul(tem1, velco[k]);
            tem1 = mpas_mul(tem1, 0.5f);
            float hd = mpas_sqrt(mpas_div(taup[k], tem1));
            const float fro = mpas_mul(mpas_mul(brvf, hd), temv);
            const float tem2 = mpas_sqrt(usqj[k]);
            const float tem = mpas_add(1.0f, mpas_mul(tem2, fro));
            const float rim = mpas_div(
                mpas_mul(usqj[k], mpas_sub(1.0f, fro)), mpas_mul(tem, tem));
            if (rim <= 0.25f) {
                const float temc = mpas_add(2.0f, mpas_div(1.0f, tem2));
                hd = mpas_div(
                    mpas_mul(velco[k],
                        mpas_sub(mpas_mul(2.0f, mpas_sqrt(temc)), temc)),
                    brvf);
                taup[kp1] = mpas_mul(tem1, mpas_mul(hd, hd));
            } else {
                taup[kp1] = taup[k];
            }
        }
    }

    if (!ldrag) {
        int kblk = 0;
        float fbdpe = 0.0f;
        float zblk = 0.0f;
        for (int kf = nlev; kf >= 2; --kf) {
            if (kblk == 0 && kf <= kbl) {
                const int k = kf - 1;
                float contribution = mpas_mul(
                    bnv2[k], mpas_sub(zmid[(kbl - 1) * ncells + cell],
                        zmid[k * ncells + cell]));
                contribution = mpas_mul(contribution, delta_p[k]);
                contribution = mpas_div(contribution, gravity);
                contribution = mpas_div(contribution, rho[k]);
                fbdpe = mpas_add(fbdpe, contribution);
                const float fbdke = mpas_mul(0.5f,
                    mpas_add(mpas_mul(u1[k], u1[k]), mpas_mul(v1[k], v1[k])));
                if (fbdpe >= fbdke) {
                    kblk = kf < kbl ? kf : kbl;
                    zblk = mpas_sub(zmid[(kblk - 1) * ncells + cell], zmid[cell]);
                }
            }
        }
        if (kblk != 0) {
            const float fbdcd = mpas_max(
                mpas_sub(2.0f, mpas_div(1.0f, od)), 0.0f);
            float value = mpas_mul(0.5f, rhobar);
            value = mpas_mul(value, coefm);
            value = mpas_div(value, mpas_mul(dx, dx));
            value = mpas_mul(value, fbdcd);
            value = mpas_mul(value, dxyp);
            value = mpas_mul(value, olp);
            value = mpas_mul(value, zblk);
            value = mpas_mul(value, mpas_mul(ulow, ulow));
            taufb[0] = value;
            const float tautem = mpas_div(taufb[0], (float)(kblk - 1));
            for (int kf = 2; kf <= kblk; ++kf)
                taufb[kf - 1] = mpas_sub(taufb[kf - 2], tautem);
            for (int k = 0; k <= nlev; ++k)
                taup[k] = mpas_add(taup[k], taufb[k]);
        }
    }

    for (int k = 0; k < nlev; ++k) {
        taud[k] = mpas_div(
            mpas_mul(mpas_sub(taup[k + 1], taup[k]), gravity), delta_p[k]);
    }
    float dtfac = 1.0f;
    for (int kf = 1; kf < nlev; ++kf) {
        const int k = kf - 1;
        if (kf <= kbl && taud[k] != 0.0f) {
            const float limiter = mpas_abs(
                mpas_div(velco[k], mpas_mul(dt, taud[k])));
            dtfac = mpas_min(dtfac, limiter);
        }
    }

    float surface_u = 0.0f;
    float surface_v = 0.0f;
    for (int k = 0; k < nlev; ++k) {
        const int i = k * ncells + cell;
        taud[k] = mpas_mul(taud[k], dtfac);
        const float du = mpas_mul(taud[k], xn);
        const float dv = mpas_mul(taud[k], yn);
        dtaux3d[i] = du;
        dtauy3d[i] = dv;
        surface_u = mpas_add(surface_u, mpas_mul(du, delta_p[k]));
        surface_v = mpas_add(surface_v, mpas_mul(dv, delta_p[k]));
        rublten_out[i] = mpas_add(rublten_in[i], du);
        rvblten_out[i] = mpas_add(rvblten_in[i], dv);
        rubldiff[i] = mpas_sub(rublten_out[i], rublten_in[i]);
        rvbldiff[i] = mpas_sub(rvblten_out[i], rvblten_in[i]);
        if (!isfinite(du) || !isfinite(dv) || !isfinite(rublten_out[i])
                || !isfinite(rvblten_out[i]) || !isfinite(rubldiff[i])
                || !isfinite(rvbldiff[i])) bad = true;
    }
    dusfcg[cell] = mpas_mul(mpas_div(-1.0f, gravity), surface_u);
    dvsfcg[cell] = mpas_mul(mpas_div(-1.0f, gravity), surface_v);
    if (!isfinite(dusfcg[cell]) || !isfinite(dvsfcg[cell]) || bad)
        atomicExch(invalid, 1);
}

