                R tbar=R(0.5f)*(t1+t2),qvbar=R(0.5f)*(qv1+qv2);
                R qlbar=R(0.5f)*(ql1+ql2),qibar=R(0.5f)*(qi1+qi2);
                R lhv=lv1-lv2*tbar,lhs=ls1-ls2*tbar;
