    }
    if(mask&(1u<<14)) {
        R result=0.0f;
        for(int k=0;k<nl;k++) {
            R h=rmax(R(0.5f)*(R(wc[k])+R(wc[k+1])),0.0f)*rmax(R(uh[c*nl+k])/R(area[c]),0.0f);
            R zb=rmax(R(zc[k])-R(zc[0]),2000.0f),zt=rmin(R(zc[k+1])-R(zc[0]),5000.0f);
            result+=h*rmax(0.0f,zt-zb);
        }
        out[14*nc+c]=rmax(result,out[14*nc+c]).v;
    }
}
