extern "C" __global__ void reset_diag(int nc,unsigned mask,float* out) {
    int c=blockDim.x*blockIdx.x+threadIdx.x;
    if(c>=nc) return;
    for(int j=14;j<17;j++) if(mask&(1u<<j)) out[j*nc+c]=0.0f;
