extern "C" __global__ void validate_transport_indices_v841(
    const int ncells, const int nedges, const int max_edges,
    const int width, const int *n_edges_on_cell, const int *edges_on_cell,
    const int *cells_on_cell, const int *cells_on_edge,
    const int *n_adv, const int *adv_cells, int *invalid)
{
    const int index = blockDim.x * blockIdx.x + threadIdx.x;
    if (index < ncells) {
        const int count = n_edges_on_cell[index];
        if (count < 0 || count > max_edges) atomicExch(invalid, 1);
        const int safe_count = count < 0 ? 0 : (count > max_edges ? max_edges : count);
        for (int slot = 0; slot < safe_count; ++slot) {
            const int edge = edges_on_cell[CES(index, slot, max_edges)];
            const int cell = cells_on_cell[CES(index, slot, max_edges)];
            if (edge < 0 || edge >= nedges || cell < 0 || cell >= ncells)
                atomicExch(invalid, 1);
        }
    }
    if (index < nedges) {
        const int c0 = cells_on_edge[2 * index];
        const int c1 = cells_on_edge[2 * index + 1];
        if (c0 < 0 || c0 >= ncells || c1 < 0 || c1 >= ncells)
            atomicExch(invalid, 1);
        const int count = n_adv[index];
        if (count < 0 || count > width) atomicExch(invalid, 1);
        const int safe_count = count < 0 ? 0 : (count > width ? width : count);
        for (int slot = 0; slot < safe_count; ++slot) {
            const int cell = adv_cells[ADV(index, slot, width)];
            if (cell < 0 || cell >= ncells) atomicExch(invalid, 1);
        }
    }
}

extern "C" __global__ void transport_standard_finish_v841(
    const int ntracers, const int nlev, const int ncells,
    const int nedges, const int max_edges, const float dt,
    const int *n_edges_on_cell, const int *edges_on_cell,
    const float *acoustic_sign, const float *inv_area_cell,
    const float *velocity, const float *edge_values,
    const float *vertical_flux, const float *rdzw,
    const float *old, const float *rho_old, const float *target_density,
    const float *source, float *output)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    for (int tracer = 0; tracer < ntracers; ++tracer) {
        for (int k = 0; k < nlev; ++k) {
            const int index = Q3(tracer, k, cell, nlev, ncells);
            float horizontal = 0.0f;
            for (int slot = 0; slot < n_edges_on_cell[cell]; ++slot) {
                const int edge = edges_on_cell[CES(cell, slot, max_edges)];
                const float sign = -acoustic_sign[CES(cell, slot, max_edges)];
                horizontal = mpas_add(horizontal, mpas_mul(mpas_mul(
                    sign, velocity[E2(k, edge, nedges)]),
                    edge_values[QE3(tracer, k, edge, nlev, nedges)]));
            }
            const float tendency = mpas_add(
                mpas_mul(horizontal, inv_area_cell[cell]), source[index]);
            const float vertical = mpas_mul(rdzw[k], mpas_sub(
                vertical_flux[QI3(tracer, k + 1, cell, nlev, ncells)],
                vertical_flux[QI3(tracer, k, cell, nlev, ncells)]));
            const float numerator = mpas_add(
                mpas_mul(old[index], rho_old[C2(k, cell, ncells)]),
                mpas_mul(dt, mpas_sub(tendency, vertical)));
            const float rho_new_inv = mpas_div(
                1.0f, target_density[C2(k, cell, ncells)]);
            output[index] = mpas_mul(numerator, rho_new_inv);
        }
    }
}

extern "C" __global__ void transport_target_density_v841(
    const int nlev, const int ncells, const int nedges, const int max_edges,
    const int advance_density, const float dt,
    const int *n_edges_on_cell, const int *edges_on_cell,
    const float *acoustic_sign, const float *dv_edge,
    const float *inv_area_cell, const float *velocity,
    const float *vertical_velocity, const float *rdzw,
    const float *rho_old, const float *rho_new, float *target_density)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    for (int k = 0; k < nlev; ++k) {
        const int index = C2(k, cell, ncells);
        if (!advance_density) {
            target_density[index] = rho_new[index];
        } else {
            float horizontal = 0.0f;
            for (int slot = 0; slot < n_edges_on_cell[cell]; ++slot) {
                const int edge = edges_on_cell[CES(cell, slot, max_edges)];
                const float sign = -acoustic_sign[CES(cell, slot, max_edges)];
                float contribution = mpas_mul(
                    sign, velocity[E2(k, edge, nedges)]);
                contribution = mpas_mul(contribution, dv_edge[edge]);
                contribution = mpas_mul(contribution, inv_area_cell[cell]);
                horizontal = mpas_add(horizontal, contribution);
            }
            target_density[index] = mpas_add(rho_old[index], mpas_mul(dt,
                mpas_sub(horizontal, mpas_mul(rdzw[k], mpas_sub(
                    vertical_velocity[C2(k + 1, cell, ncells)],
                    vertical_velocity[index])))));
        }
    }
}

extern "C" __global__ void transport_edge_values_mono_v841(
    const int ntracers, const int nlev, const int ncells,
    const int nedges, const int width, const float coefficient,
    const float *stage, const float *velocity,
    const float *adv, const float *adv3,
    const int *n_adv, const int *adv_cells, float *edge_values)
{
    const int edge = blockDim.x * blockIdx.x + threadIdx.x;
    if (edge >= nedges) return;
    const int count = n_adv[edge];
    if (count == 10) {
        for (int k = 0; k < nlev; ++k) {
            const float vel = velocity[E2(k, edge, nedges)];
            const float sign = mpas_copysign(1.0f, vel);
            for (int tracer = 0; tracer < ntracers; ++tracer) {
                const int first_cell = adv_cells[ADV(edge, 0, width)];
                float weight = mpas_add(adv[ADV(edge, 0, width)],
                    mpas_mul(mpas_mul(coefficient, sign),
                        adv3[ADV(edge, 0, width)]));
                float value = mpas_mul(weight,
                    stage[Q3(tracer, k, first_cell, nlev, ncells)]);
                for (int slot = 1; slot < 10; ++slot) {
                    const int cell = adv_cells[ADV(edge, slot, width)];
                    weight = mpas_add(adv[ADV(edge, slot, width)],
                        mpas_mul(mpas_mul(coefficient, sign),
                            adv3[ADV(edge, slot, width)]));
                    value = mpas_add(value, mpas_mul(weight,
                        stage[Q3(tracer, k, cell, nlev, ncells)]));
                }
                edge_values[QE3(tracer, k, edge, nlev, nedges)] =
                    mpas_mul(vel, value);
            }
        }
    } else {
        for (int tracer = 0; tracer < ntracers; ++tracer) {
            for (int k = 0; k < nlev; ++k) {
                edge_values[QE3(tracer, k, edge, nlev, nedges)] = 0.0f;
            }
        }
        for (int slot = 0; slot < count; ++slot) {
            const int cell = adv_cells[ADV(edge, slot, width)];
            for (int k = 0; k < nlev; ++k) {
                const float vel = velocity[E2(k, edge, nedges)];
                const float sign = mpas_copysign(1.0f, vel);
                float scalar_weight = mpas_add(adv[ADV(edge, slot, width)],
                    mpas_mul(mpas_mul(coefficient, sign),
                        adv3[ADV(edge, slot, width)]));
                scalar_weight = mpas_mul(vel, scalar_weight);
                for (int tracer = 0; tracer < ntracers; ++tracer) {
                    const int index = QE3(tracer, k, edge, nlev, nedges);
                    edge_values[index] = mpas_add(edge_values[index],
                        mpas_mul(scalar_weight,
                            stage[Q3(tracer, k, cell, nlev, ncells)]));
                }
            }
        }
    }
}

extern "C" __global__ void fct_edge_residual_v841(
    const int ntracers, const int nlev, const int ncells, const int nedges,
    const float dt, const float *source_old, const float *velocity,
    const float *dv_edge, const int *cells_on_edge,
    const float *high_flux, float *upwind_flux, float *horizontal_residual)
{
    const int edge = blockDim.x * blockIdx.x + threadIdx.x;
    if (edge >= nedges) return;
    const int c0 = cells_on_edge[2 * edge];
    const int c1 = cells_on_edge[2 * edge + 1];
    for (int tracer = 0; tracer < ntracers; ++tracer) {
        for (int k = 0; k < nlev; ++k) {
            const int index = QE3(tracer, k, edge, nlev, nedges);
            const float vel = velocity[E2(k, edge, nedges)];
            const float upwind = mpas_mul(mpas_mul(dv_edge[edge], dt),
                mpas_add(mpas_mul(plus(vel), source_old[Q3(
                    tracer, k, c0, nlev, ncells)]),
                    mpas_mul(minus(vel), source_old[Q3(
                    tracer, k, c1, nlev, ncells)])));
            upwind_flux[index] = upwind;
            horizontal_residual[index] = mpas_sub(
                mpas_mul(dt, high_flux[index]), upwind);
        }
    }
}

extern "C" __global__ void fct_horizontal_low_order_v841(
    const int ntracers, const int nlev, const int ncells,
    const int nedges, const int max_edges,
    const int *n_edges_on_cell, const int *edges_on_cell,
    const float *acoustic_sign, const float *inv_area_cell,
    const float *upwind_flux, const float *horizontal_residual,
    float *mass, float *scale_in, float *scale_out)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    const float inverse_area = inv_area_cell[cell];
    for (int tracer = 0; tracer < ntracers; ++tracer) {
        for (int k = 0; k < nlev; ++k) {
            const int index = Q3(tracer, k, cell, nlev, ncells);
            float cell_mass = mass[index];
            float incoming = scale_in[index];
            float outgoing = scale_out[index];
            for (int slot = 0; slot < n_edges_on_cell[cell]; ++slot) {
                const int edge = edges_on_cell[CES(cell, slot, max_edges)];
                const float sign = -acoustic_sign[CES(cell, slot, max_edges)];
                const int qe = QE3(tracer, k, edge, nlev, nedges);
                cell_mass = mpas_add(cell_mass, mpas_mul(
                    mpas_mul(sign, upwind_flux[qe]), inverse_area));
                const float signed_residual = mpas_mul(
                    -sign, horizontal_residual[qe]);
                outgoing = mpas_sub(outgoing,
                    mpas_mul(plus(signed_residual), inverse_area));
                incoming = mpas_sub(incoming,
                    mpas_mul(minus(signed_residual), inverse_area));
            }
            mass[index] = cell_mass;
            scale_in[index] = incoming;
            scale_out[index] = outgoing;
        }
    }
}

extern "C" __global__ void fct_finish_v841(
    const int ntracers, const int nlev, const int ncells,
    const int nedges, const int max_edges,
    const int *n_edges_on_cell, const int *edges_on_cell,
    const float *acoustic_sign, const float *inv_area_cell, const float *rdzw,
    const float *horizontal_residual, const float *vertical_residual,
    const float *target_density, const float *mass, float *output)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    const float inverse_area = inv_area_cell[cell];
    for (int tracer = 0; tracer < ntracers; ++tracer) {
        for (int k = 0; k < nlev; ++k) {
            const int index = Q3(tracer, k, cell, nlev, ncells);
            float value = mass[index];
            for (int slot = 0; slot < n_edges_on_cell[cell]; ++slot) {
                const int edge = edges_on_cell[CES(cell, slot, max_edges)];
                const float sign = -acoustic_sign[CES(cell, slot, max_edges)];
                value = mpas_add(value, mpas_mul(mpas_mul(sign,
                    horizontal_residual[QE3(
                        tracer, k, edge, nlev, nedges)]), inverse_area));
            }
            value = mpas_sub(value, mpas_mul(rdzw[k], mpas_sub(
                vertical_residual[QI3(
                    tracer, k + 1, cell, nlev, ncells)],
                vertical_residual[QI3(
                    tracer, k, cell, nlev, ncells)])));
            output[index] = mpas_max(0.0f,
                mpas_div(value, target_density[C2(k, cell, ncells)]));
        }
    }
}

#ifndef HEX_HOIST_ADV
#define HEX_HOIST_ADV 10
#endif
#ifndef HEX_HOIST_CELL
#define HEX_HOIST_CELL 10
#endif
/* Thread per (tracer, edge) form of transport_edge_values: the edge's
   advection stencil is read once into registers and the thread walks the
   levels.  Each (tracer, level) runs the element body unchanged, including
   the subnormal-sensitivity test and its exact re-evaluation, so every edge
   value carries the same bits. */
extern "C" __global__ void transport_edge_values_hoist_v841(
    const int ntracers, const int nlev, const int ncells,
    const int nedges, const int width, const float coefficient,
    const float *stage, const float *velocity,
    const float *adv, const float *adv3,
    const int *n_adv, const int *adv_cells,
    float *edge_values, const int lpt)
{
    const int hex_chunks = (nlev + lpt - 1) / lpt;
    const int element = blockDim.x * blockIdx.x + threadIdx.x;
    if (element >= ntracers * nedges * hex_chunks) return;
    const int edge = element % nedges;
    const int tracer = (element / nedges) % ntracers;
    const int hex_k0 = (element / nedges / ntracers) * lpt;
    const int hex_k1 = min(nlev, hex_k0 + lpt);
    const int count = n_adv[edge];
    int cl[HEX_HOIST_ADV];
    float b[HEX_HOIST_ADV];
    float t[HEX_HOIST_ADV];
    const bool hoisted = count <= HEX_HOIST_ADV;
#pragma unroll
    for (int slot = 0; slot < HEX_HOIST_ADV; ++slot) {
        const bool live = hoisted && slot < count;
        cl[slot] = live ? adv_cells[ADV(edge, slot, width)] : 0;
        b[slot] = live ? adv[ADV(edge, slot, width)] : 0.0f;
        t[slot] = live ? adv3[ADV(edge, slot, width)] : 0.0f;
    }
    for (int k = hex_k0; k < hex_k1; ++k) {
        float value = 0.0f;
        const float velocity_sign = mpas_copysign(
            1.0f, velocity[E2(k, edge, nedges)]);
        bool ftz_sensitive = false;
        if (hoisted) {
#pragma unroll
            for (int slot = 0; slot < HEX_HOIST_ADV; ++slot) {
                if (slot < count) {
                    const float base_weight = b[slot];
                    const float third_weight = t[slot];
                    const float stage_value = stage[Q3(
                        tracer, k, cl[slot], nlev, ncells)];
                    const float correction = coefficient * velocity_sign
                        * third_weight;
                    const float weight = base_weight + correction;
                    const float contribution = weight * stage_value;
                    const float next = value + contribution;
#if MPAS_FTZ_FALLBACK_ENABLED
                    const unsigned int coefficient_mag =
                        mpas_f32_magnitude_bits(coefficient);
                    const unsigned int third_mag =
                        mpas_f32_magnitude_bits(third_weight);
                    const unsigned int correction_mag =
                        mpas_f32_magnitude_bits(correction);
                    const unsigned int base_mag =
                        mpas_f32_magnitude_bits(base_weight);
                    const unsigned int weight_mag =
                        mpas_f32_magnitude_bits(weight);
                    const unsigned int stage_mag =
                        mpas_f32_magnitude_bits(stage_value);
                    const unsigned int contribution_mag =
                        mpas_f32_magnitude_bits(contribution);
                    const unsigned int value_mag =
                        mpas_f32_magnitude_bits(value);
                    const unsigned int next_mag = mpas_f32_magnitude_bits(next);
                    ftz_sensitive = ftz_sensitive
                        || (base_mag != 0u && (base_mag >> 23) == 0u)
                        || (third_mag != 0u && (third_mag >> 23) == 0u)
                        || (stage_mag != 0u && (stage_mag >> 23) == 0u)
                        || (correction_mag == 0u && coefficient_mag != 0u
                            && third_mag != 0u)
                        || (weight_mag == 0u && base_mag != correction_mag
                            && base_mag != 0u && correction_mag != 0u)
                        || (contribution_mag == 0u && weight_mag != 0u
                            && stage_mag != 0u)
                        || (next_mag == 0u && value_mag != contribution_mag
                            && value_mag != 0u && contribution_mag != 0u);
#endif
                    value = next;
                }
            }
        } else {
            for (int slot = 0; slot < count; ++slot) {
                const int cell = adv_cells[ADV(edge, slot, width)];
                const float base_weight = adv[ADV(edge, slot, width)];
                const float third_weight = adv3[ADV(edge, slot, width)];
                const float stage_value = stage[Q3(
                    tracer, k, cell, nlev, ncells)];
                const float correction = coefficient * velocity_sign
                    * third_weight;
                const float weight = base_weight + correction;
                const float contribution = weight * stage_value;
                const float next = value + contribution;
#if MPAS_FTZ_FALLBACK_ENABLED
                const unsigned int coefficient_mag =
                    mpas_f32_magnitude_bits(coefficient);
                const unsigned int third_mag =
                    mpas_f32_magnitude_bits(third_weight);
                const unsigned int correction_mag =
                    mpas_f32_magnitude_bits(correction);
                const unsigned int base_mag =
                    mpas_f32_magnitude_bits(base_weight);
                const unsigned int weight_mag =
                    mpas_f32_magnitude_bits(weight);
                const unsigned int stage_mag =
                    mpas_f32_magnitude_bits(stage_value);
                const unsigned int contribution_mag =
                    mpas_f32_magnitude_bits(contribution);
                const unsigned int value_mag =
                    mpas_f32_magnitude_bits(value);
                const unsigned int next_mag = mpas_f32_magnitude_bits(next);
                ftz_sensitive = ftz_sensitive
                    || (base_mag != 0u && (base_mag >> 23) == 0u)
                    || (third_mag != 0u && (third_mag >> 23) == 0u)
                    || (stage_mag != 0u && (stage_mag >> 23) == 0u)
                    || (correction_mag == 0u && coefficient_mag != 0u
                        && third_mag != 0u)
                    || (weight_mag == 0u && base_mag != correction_mag
                        && base_mag != 0u && correction_mag != 0u)
                    || (contribution_mag == 0u && weight_mag != 0u
                        && stage_mag != 0u)
                    || (next_mag == 0u && value_mag != contribution_mag
                        && value_mag != 0u && contribution_mag != 0u);
#endif
                value = next;
            }
        }
        if (ftz_sensitive) {
            value = 0.0f;
            for (int slot = 0; slot < count; ++slot) {
                const int cell = adv_cells[ADV(edge, slot, width)];
                const float weight = mpas_add(
                    adv[ADV(edge, slot, width)],
                    mpas_mul(mpas_mul(coefficient, velocity_sign),
                        adv3[ADV(edge, slot, width)]));
                value = mpas_add(value, mpas_mul(weight,
                    stage[Q3(tracer, k, cell, nlev, ncells)]));
            }
        }
        edge_values[QE3(tracer, k, edge, nlev, nedges)] = value;
    }
}

/* Element form of transport_standard_finish_v841: one thread per
   (level, cell), cell fastest, walking the tracers.  The per-cell loop of
   the original left most of the card idle (one thread per cell, every level
   and tracer serial).  Each (tracer, level, cell) runs the original body
   unchanged; the tracer-independent sign*velocity product of each slot is
   the same helper call on the same operands, formed once per slot. */
extern "C" __global__ void transport_standard_finish_elem_v841(
    const int ntracers, const int nlev, const int ncells,
    const int nedges, const int max_edges, const float dt,
    const int *n_edges_on_cell, const int *edges_on_cell,
    const float *acoustic_sign, const float *inv_area_cell,
    const float *velocity, const float *edge_values,
    const float *vertical_flux, const float *rdzw,
    const float *old, const float *rho_old, const float *target_density,
    const float *source, float *output)
{
    const int element = blockDim.x * blockIdx.x + threadIdx.x;
    if (element >= nlev * ncells) return;
    const int cell = element % ncells;
    const int k = element / ncells;
    const int count = n_edges_on_cell[cell];
    const bool hoisted = count <= HEX_HOIST_CELL;
    int ed[HEX_HOIST_CELL];
    float sv[HEX_HOIST_CELL];
#pragma unroll
    for (int slot = 0; slot < HEX_HOIST_CELL; ++slot) {
        const bool live = hoisted && slot < count;
        const int edge = live ? edges_on_cell[CES(cell, slot, max_edges)] : 0;
        ed[slot] = edge;
        sv[slot] = live ? mpas_mul(-acoustic_sign[CES(cell, slot, max_edges)],
            velocity[E2(k, edge, nedges)]) : 0.0f;
    }
    const float inv_area = inv_area_cell[cell];
    const float rdzw_k = rdzw[k];
    const float rho_old_k = rho_old[C2(k, cell, ncells)];
    const float rho_new_inv = mpas_div(1.0f, target_density[C2(k, cell, ncells)]);
    for (int tracer = 0; tracer < ntracers; ++tracer) {
        const int index = Q3(tracer, k, cell, nlev, ncells);
        float horizontal = 0.0f;
        if (hoisted) {
#pragma unroll
            for (int slot = 0; slot < HEX_HOIST_CELL; ++slot) {
                if (slot < count) {
                    horizontal = mpas_add(horizontal, mpas_mul(sv[slot],
                        edge_values[QE3(tracer, k, ed[slot], nlev, nedges)]));
                }
            }
        } else {
            for (int slot = 0; slot < count; ++slot) {
                const int edge = edges_on_cell[CES(cell, slot, max_edges)];
                const float sign = -acoustic_sign[CES(cell, slot, max_edges)];
                horizontal = mpas_add(horizontal, mpas_mul(mpas_mul(
                    sign, velocity[E2(k, edge, nedges)]),
                    edge_values[QE3(tracer, k, edge, nlev, nedges)]));
            }
        }
        const float tendency = mpas_add(
            mpas_mul(horizontal, inv_area), source[index]);
        const float vertical = mpas_mul(rdzw_k, mpas_sub(
            vertical_flux[QI3(tracer, k + 1, cell, nlev, ncells)],
            vertical_flux[QI3(tracer, k, cell, nlev, ncells)]));
        const float numerator = mpas_add(
            mpas_mul(old[index], rho_old_k),
            mpas_mul(dt, mpas_sub(tendency, vertical)));
        output[index] = mpas_mul(numerator, rho_new_inv);
    }
}

/* Element forms of the monotonic (FCT) scalar-transport kernels.  The
   originals run one thread per cell or edge with every tracer and level
   serial in the thread (about 340k threads per 15 km rank, one wave); these
   run one thread per (tracer, level, owner), owner fastest.  No original
   carries a value across tracers or levels in its loops (each element reads
   inputs and writes only its own index), so each element runs the original
   body unchanged and carries the same bits. */
#define HEX_TKO(total_owners) \
    const int owner = element % (total_owners); \
    const int rest = element / (total_owners); \
    const int k = rest % nlev; \
    const int tracer = rest / nlev;

extern "C" __global__ void transport_target_density_elem_v841(
    const int nlev, const int ncells, const int nedges, const int max_edges,
    const int advance_density, const float dt,
    const int *n_edges_on_cell, const int *edges_on_cell,
    const float *acoustic_sign, const float *dv_edge,
    const float *inv_area_cell, const float *velocity,
    const float *vertical_velocity, const float *rdzw,
    const float *rho_old, const float *rho_new, float *target_density)
{
    const int element = blockDim.x * blockIdx.x + threadIdx.x;
    if (element >= nlev * ncells) return;
    const int cell = element % ncells;
    const int k = element / ncells;
    const int index = C2(k, cell, ncells);
    if (!advance_density) {
        target_density[index] = rho_new[index];
    } else {
        float horizontal = 0.0f;
        for (int slot = 0; slot < n_edges_on_cell[cell]; ++slot) {
            const int edge = edges_on_cell[CES(cell, slot, max_edges)];
            const float sign = -acoustic_sign[CES(cell, slot, max_edges)];
            float contribution = mpas_mul(
                sign, velocity[E2(k, edge, nedges)]);
            contribution = mpas_mul(contribution, dv_edge[edge]);
            contribution = mpas_mul(contribution, inv_area_cell[cell]);
            horizontal = mpas_add(horizontal, contribution);
        }
        target_density[index] = mpas_add(rho_old[index], mpas_mul(dt,
            mpas_sub(horizontal, mpas_mul(rdzw[k], mpas_sub(
                vertical_velocity[C2(k + 1, cell, ncells)],
                vertical_velocity[index])))));
    }
}

extern "C" __global__ void transport_edge_values_mono_hoist_v841(
    const int ntracers, const int nlev, const int ncells,
    const int nedges, const int width, const float coefficient,
    const float *stage, const float *velocity,
    const float *adv, const float *adv3,
    const int *n_adv, const int *adv_cells, float *edge_values, const int lpt)
{
    /* One thread per (tracer, edge); the edge's stencil is read once into
       registers and the thread walks the levels.  Both branches of the
       original keep their own association: the ten-cell branch weights the
       sum and multiplies by the velocity last; the other branch multiplies
       each weight by the velocity first and accumulates from 0.0f in slot
       order, exactly as the original's in-memory accumulation did. */
    const int hex_chunks = (nlev + lpt - 1) / lpt;
    const int element = blockDim.x * blockIdx.x + threadIdx.x;
    if (element >= ntracers * nedges * hex_chunks) return;
    const int edge = element % nedges;
    const int tracer = (element / nedges) % ntracers;
    const int hex_k0 = (element / nedges / ntracers) * lpt;
    const int hex_k1 = min(nlev, hex_k0 + lpt);
    const int count = n_adv[edge];
    const bool hoisted = count <= HEX_HOIST_ADV;
    int cl[HEX_HOIST_ADV];
    float b[HEX_HOIST_ADV];
    float t[HEX_HOIST_ADV];
#pragma unroll
    for (int slot = 0; slot < HEX_HOIST_ADV; ++slot) {
        const bool live = hoisted && slot < count;
        cl[slot] = live ? adv_cells[ADV(edge, slot, width)] : 0;
        b[slot] = live ? adv[ADV(edge, slot, width)] : 0.0f;
        t[slot] = live ? adv3[ADV(edge, slot, width)] : 0.0f;
    }
    for (int k = hex_k0; k < hex_k1; ++k) {
        const float vel = velocity[E2(k, edge, nedges)];
        const float sign = mpas_copysign(1.0f, vel);
        float result;
        if (count == 10 && hoisted) {
            float weight = mpas_add(b[0],
                mpas_mul(mpas_mul(coefficient, sign), t[0]));
            float value = mpas_mul(weight,
                stage[Q3(tracer, k, cl[0], nlev, ncells)]);
#pragma unroll
            for (int slot = 1; slot < 10; ++slot) {
                weight = mpas_add(b[slot],
                    mpas_mul(mpas_mul(coefficient, sign), t[slot]));
                value = mpas_add(value, mpas_mul(weight,
                    stage[Q3(tracer, k, cl[slot], nlev, ncells)]));
            }
            result = mpas_mul(vel, value);
        } else if (count == 10) {
            const int first_cell = adv_cells[ADV(edge, 0, width)];
            float weight = mpas_add(adv[ADV(edge, 0, width)],
                mpas_mul(mpas_mul(coefficient, sign),
                    adv3[ADV(edge, 0, width)]));
            float value = mpas_mul(weight,
                stage[Q3(tracer, k, first_cell, nlev, ncells)]);
            for (int slot = 1; slot < 10; ++slot) {
                const int cell = adv_cells[ADV(edge, slot, width)];
                weight = mpas_add(adv[ADV(edge, slot, width)],
                    mpas_mul(mpas_mul(coefficient, sign),
                        adv3[ADV(edge, slot, width)]));
                value = mpas_add(value, mpas_mul(weight,
                    stage[Q3(tracer, k, cell, nlev, ncells)]));
            }
            result = mpas_mul(vel, value);
        } else if (hoisted) {
            float value = 0.0f;
#pragma unroll
            for (int slot = 0; slot < HEX_HOIST_ADV; ++slot) {
                if (slot < count) {
                    float scalar_weight = mpas_add(b[slot],
                        mpas_mul(mpas_mul(coefficient, sign), t[slot]));
                    scalar_weight = mpas_mul(vel, scalar_weight);
                    value = mpas_add(value, mpas_mul(scalar_weight,
                        stage[Q3(tracer, k, cl[slot], nlev, ncells)]));
                }
            }
            result = value;
        } else {
            float value = 0.0f;
            for (int slot = 0; slot < count; ++slot) {
                const int cell = adv_cells[ADV(edge, slot, width)];
                float scalar_weight = mpas_add(adv[ADV(edge, slot, width)],
                    mpas_mul(mpas_mul(coefficient, sign),
                        adv3[ADV(edge, slot, width)]));
                scalar_weight = mpas_mul(vel, scalar_weight);
                value = mpas_add(value, mpas_mul(scalar_weight,
                    stage[Q3(tracer, k, cell, nlev, ncells)]));
            }
            result = value;
        }
        edge_values[QE3(tracer, k, edge, nlev, nedges)] = result;
    }
}

extern "C" __global__ void fct_minmax_source_elem_v841(
    const int ntracers, const int nlev, const int ncells,
    const int max_edges, const float dt,
    const int *n_edges_on_cell, const int *cells_on_cell,
    const float *old, const float *source, const float *rho_old,
    float *source_old, float *minimum, float *maximum)
{
    const int element = blockDim.x * blockIdx.x + threadIdx.x;
    if (element >= ntracers * nlev * ncells) return;
    HEX_TKO(ncells)
    const int cell = owner;
    const int index = Q3(tracer, k, cell, nlev, ncells);
    const float current = mpas_add(old[index], mpas_div(mpas_mul(dt, source[index]), rho_old[C2(k, cell, ncells)]));
    source_old[index] = current;
    float low = current;
    float high = current;
    if (k > 0) {
        const float value = mpas_add(old[Q3(
            tracer, k - 1, cell, nlev, ncells)], mpas_div(mpas_mul(dt, source[Q3(
                tracer, k - 1, cell, nlev, ncells)]), rho_old[C2(k - 1, cell, ncells)]));
        low = mpas_min(low, value);
        high = mpas_max(high, value);
    }
    if (k + 1 < nlev) {
        const float value = mpas_add(old[Q3(
            tracer, k + 1, cell, nlev, ncells)], mpas_div(mpas_mul(dt, source[Q3(
                tracer, k + 1, cell, nlev, ncells)]), rho_old[C2(k + 1, cell, ncells)]));
        low = mpas_min(low, value);
        high = mpas_max(high, value);
    }
    for (int slot = 0; slot < n_edges_on_cell[cell]; ++slot) {
        const int neighbor = cells_on_cell[CES(cell, slot, max_edges)];
        const float value = mpas_add(old[Q3(
            tracer, k, neighbor, nlev, ncells)], mpas_div(mpas_mul(dt, source[Q3(tracer, k, neighbor, nlev, ncells)]), rho_old[C2(k, neighbor, ncells)]));
        low = mpas_min(low, value);
        high = mpas_max(high, value);
    }
    minimum[index] = low;
    maximum[index] = high;
}

extern "C" __global__ void fct_edge_residual_elem_v841(
    const int ntracers, const int nlev, const int ncells, const int nedges,
    const float dt, const float *source_old, const float *velocity,
    const float *dv_edge, const int *cells_on_edge,
    const float *high_flux, float *upwind_flux, float *horizontal_residual)
{
    const int element = blockDim.x * blockIdx.x + threadIdx.x;
    if (element >= ntracers * nlev * nedges) return;
    HEX_TKO(nedges)
    const int edge = owner;
    const int c0 = cells_on_edge[2 * edge];
    const int c1 = cells_on_edge[2 * edge + 1];
    const int index = QE3(tracer, k, edge, nlev, nedges);
    const float vel = velocity[E2(k, edge, nedges)];
    const float upwind = mpas_mul(mpas_mul(dv_edge[edge], dt),
        mpas_add(mpas_mul(plus(vel), source_old[Q3(
            tracer, k, c0, nlev, ncells)]),
            mpas_mul(minus(vel), source_old[Q3(
            tracer, k, c1, nlev, ncells)])));
    upwind_flux[index] = upwind;
    horizontal_residual[index] = mpas_sub(
        mpas_mul(dt, high_flux[index]), upwind);
}

extern "C" __global__ void fct_horizontal_low_order_elem_v841(
    const int ntracers, const int nlev, const int ncells,
    const int nedges, const int max_edges,
    const int *n_edges_on_cell, const int *edges_on_cell,
    const float *acoustic_sign, const float *inv_area_cell,
    const float *upwind_flux, const float *horizontal_residual,
    float *mass, float *scale_in, float *scale_out)
{
    const int element = blockDim.x * blockIdx.x + threadIdx.x;
    if (element >= ntracers * nlev * ncells) return;
    HEX_TKO(ncells)
    const int cell = owner;
    const float inverse_area = inv_area_cell[cell];
    const int index = Q3(tracer, k, cell, nlev, ncells);
    float cell_mass = mass[index];
    float incoming = scale_in[index];
    float outgoing = scale_out[index];
    for (int slot = 0; slot < n_edges_on_cell[cell]; ++slot) {
        const int edge = edges_on_cell[CES(cell, slot, max_edges)];
        const float sign = -acoustic_sign[CES(cell, slot, max_edges)];
        const int qe = QE3(tracer, k, edge, nlev, nedges);
        cell_mass = mpas_add(cell_mass, mpas_mul(
            mpas_mul(sign, upwind_flux[qe]), inverse_area));
        const float signed_residual = mpas_mul(
            -sign, horizontal_residual[qe]);
        outgoing = mpas_sub(outgoing,
            mpas_mul(plus(signed_residual), inverse_area));
        incoming = mpas_sub(incoming,
            mpas_mul(minus(signed_residual), inverse_area));
    }
    mass[index] = cell_mass;
    scale_in[index] = incoming;
    scale_out[index] = outgoing;
}

extern "C" __global__ void fct_scale_elem_v841(
    const int ntracers, const int nlev, const int ncells,
    const float *minimum, const float *maximum, const float *target_density,
    const float *mass, float *scale_in, float *scale_out)
{
    const int element = blockDim.x * blockIdx.x + threadIdx.x;
    if (element >= ntracers * nlev * ncells) return;
    HEX_TKO(ncells)
    const int cell = owner;
    const int index = Q3(tracer, k, cell, nlev, ncells);
    const float density = target_density[C2(k, cell, ncells)];
    const float eps = 1.0e-20f;
    const float incoming = mpas_div(mpas_sub(
        mpas_mul(maximum[index], density), mass[index]),
        mpas_add(scale_in[index], eps));
    const float outgoing = mpas_div(mpas_sub(
        mpas_mul(minimum[index], density), mass[index]),
        mpas_sub(scale_out[index], eps));
    scale_in[index] = mpas_min(1.0f, mpas_max(0.0f, incoming));
    scale_out[index] = mpas_min(1.0f, mpas_max(0.0f, outgoing));
}

/* The scale factors depend only on this element's completed low-order
   accumulation. Keep that accumulation in registers through scaling. The
   first 14 arguments retain the low-order ABI for the LTS flux hooks. */
extern "C" __global__ void fct_horizontal_low_order_scale_elem_v841(
    const int ntracers, const int nlev, const int ncells,
    const int nedges, const int max_edges,
    const int *n_edges_on_cell, const int *edges_on_cell,
    const float *acoustic_sign, const float *inv_area_cell,
    const float *upwind_flux, const float *horizontal_residual,
    float *mass, float *scale_in, float *scale_out,
    const float *minimum, const float *maximum, const float *target_density)
{
    const int element = blockDim.x * blockIdx.x + threadIdx.x;
    if (element >= ntracers * nlev * ncells) return;
    HEX_TKO(ncells)
    const int cell = owner;
    const float inverse_area = inv_area_cell[cell];
    const int index = Q3(tracer, k, cell, nlev, ncells);
    float cell_mass = mass[index];
    float incoming = scale_in[index];
    float outgoing = scale_out[index];
    for (int slot = 0; slot < n_edges_on_cell[cell]; ++slot) {
        const int edge = edges_on_cell[CES(cell, slot, max_edges)];
        const float sign = -acoustic_sign[CES(cell, slot, max_edges)];
        const int qe = QE3(tracer, k, edge, nlev, nedges);
        cell_mass = mpas_add(cell_mass, mpas_mul(
            mpas_mul(sign, upwind_flux[qe]), inverse_area));
        const float signed_residual = mpas_mul(
            -sign, horizontal_residual[qe]);
        outgoing = mpas_sub(outgoing,
            mpas_mul(plus(signed_residual), inverse_area));
        incoming = mpas_sub(incoming,
            mpas_mul(minus(signed_residual), inverse_area));
    }
    mass[index] = cell_mass;
    const float density = target_density[C2(k, cell, ncells)];
    const float eps = 1.0e-20f;
    const float scaled_incoming = mpas_div(mpas_sub(
        mpas_mul(maximum[index], density), cell_mass),
        mpas_add(incoming, eps));
    const float scaled_outgoing = mpas_div(mpas_sub(
        mpas_mul(minimum[index], density), cell_mass),
        mpas_sub(outgoing, eps));
    scale_in[index] = mpas_min(1.0f, mpas_max(0.0f, scaled_incoming));
    scale_out[index] = mpas_min(1.0f, mpas_max(0.0f, scaled_outgoing));
}

extern "C" __global__ void fct_limit_horizontal_elem_v841(
    const int ntracers, const int nlev, const int ncells, const int nedges,
    const int *cells_on_edge, const float *scale_in, const float *scale_out,
    float *residual)
{
    const int element = blockDim.x * blockIdx.x + threadIdx.x;
    if (element >= ntracers * nlev * nedges) return;
    HEX_TKO(nedges)
    const int edge = owner;
    const int c0 = cells_on_edge[2 * edge];
    const int c1 = cells_on_edge[2 * edge + 1];
    const int index = QE3(tracer, k, edge, nlev, nedges);
    const float flux = residual[index];
    residual[index] = mpas_add(mpas_mul(plus(flux), mpas_min(
            scale_out[Q3(tracer, k, c0, nlev, ncells)],
            scale_in[Q3(tracer, k, c1, nlev, ncells)])),
        mpas_mul(minus(flux), mpas_min(
            scale_in[Q3(tracer, k, c0, nlev, ncells)],
            scale_out[Q3(tracer, k, c1, nlev, ncells)])));
}

extern "C" __global__ void fct_limit_vertical_elem_v841(
    const int ntracers, const int nlev, const int ncells,
    const float *scale_in, const float *scale_out, float *residual)
{
    /* interface 1..nlev-1 of every (tracer, cell); interfaces 0 and nlev
       are untouched, as in the original loop. */
    const int element = blockDim.x * blockIdx.x + threadIdx.x;
    if (element >= ntracers * (nlev - 1) * ncells) return;
    const int cell = element % ncells;
    const int rest = element / ncells;
    const int interface = 1 + rest % (nlev - 1);
    const int tracer = rest / (nlev - 1);
    const int qi = QI3(tracer, interface, cell, nlev, ncells);
    const float flux = residual[qi];
    residual[qi] = mpas_add(mpas_mul(plus(flux), mpas_min(
            scale_out[Q3(
                tracer, interface - 1, cell, nlev, ncells)],
            scale_in[Q3(tracer, interface, cell, nlev, ncells)])),
        mpas_mul(minus(flux), mpas_min(
            scale_out[Q3(tracer, interface, cell, nlev, ncells)],
            scale_in[Q3(
                tracer, interface - 1, cell, nlev, ncells)])));
}

extern "C" __global__ void fct_finish_elem_v841(
    const int ntracers, const int nlev, const int ncells,
    const int nedges, const int max_edges,
    const int *n_edges_on_cell, const int *edges_on_cell,
    const float *acoustic_sign, const float *inv_area_cell, const float *rdzw,
    const float *horizontal_residual, const float *vertical_residual,
    const float *target_density, const float *mass, float *output)
{
    const int element = blockDim.x * blockIdx.x + threadIdx.x;
    if (element >= ntracers * nlev * ncells) return;
    HEX_TKO(ncells)
    const int cell = owner;
    const float inverse_area = inv_area_cell[cell];
    const int index = Q3(tracer, k, cell, nlev, ncells);
    float value = mass[index];
    for (int slot = 0; slot < n_edges_on_cell[cell]; ++slot) {
        const int edge = edges_on_cell[CES(cell, slot, max_edges)];
        const float sign = -acoustic_sign[CES(cell, slot, max_edges)];
        value = mpas_add(value, mpas_mul(mpas_mul(sign,
            horizontal_residual[QE3(
                tracer, k, edge, nlev, nedges)]), inverse_area));
    }
    value = mpas_sub(value, mpas_mul(rdzw[k], mpas_sub(
        vertical_residual[QI3(
            tracer, k + 1, cell, nlev, ncells)],
        vertical_residual[QI3(
            tracer, k, cell, nlev, ncells)])));
    output[index] = mpas_max(0.0f,
        mpas_div(value, target_density[C2(k, cell, ncells)]));
}

#define G 9.81f
#define RD 287.0f
#define RV 461.6f
#define CP 1004.5f
#define CV 717.5f
#define P0 100000.0f
#define T0 300.0f
#define GAMMA 1.4f
#define RCP 0.2857142857142857f
#define RCV 0.4f
#define RVOVRD 1.6083624362945557f
#define RERADIUS 1.5698587127158556e-07f
#define XLV 2500000.0f
#define SVP1 0.6112f
#define SVP2 17.67f
#define SVP3 29.65f
#define SVPT0 273.15f
#define RHOWATER 1000.0f
#define EP2 0.6217504332755632f
// gpuwm/core/kernels/common.cuh
#pragma once
#define I3(k, j, i, ny, nx)  ((size_t)(k) * (ny) * (nx) + (size_t)(j) * (nx) + (i))
#define I3S(k, j, i, ny, nxs)  ((size_t)(k) * (ny) * (nxs) + (size_t)(j) * (nxs) + (i))
#define IDX3(k, j, i)  I3(k, j, i, ny, nx)
#define PERIODIC(i, n) ((((i) % (n)) + (n)) % (n))
typedef float real;

// WRF v4.6.1 legacy RRTMG McICA subcolumn generators -- CUDA FP32 twin
// of the certified NumPy port in gpuwm/core/rrtmg_mcica.py, restricted
// to the icld=2 (maximum-random) forecast path and gated bitwise
// against the same unmodified-WRF fixtures through that port
// (tests/test_rrtmg_mcica.py).
//
// Fortran authority (comment anchors): module mcica_subcol_gen_lw in
// phys/module_ra_rrtmg_lw.F --
//   kissvec RNG                           lines 2697-2729
//   pmid-fraction seeding + warm-up       lines 2418-2438
//   cldmin=1e-20 cloud-fraction floor     lines 2383, 2408-2416
//   maximum-random overlap walk (icld=2)  lines 2469-2504
//   subcolumn cloud decision + fill       lines 2632-2665
// module_ra_rrtmg_sw.F carries the identical generator; only ngpt, the
// ngb band table and the output roster differ, all supplied by the
// host through the descriptor arrays of rmcw_fill_outputs.
//
// DISTINCT from gpuwm/core/kernels/rrtmgp_mcica.cu: that file is the
// RTE+RRTMGP-side generator whose seed arithmetic runs in double from
// pressures already in Pa.  THIS file reproduces the WRF FP32 kind_rb
// build's double-rounded seed path: play(mb) -> *100 rounded to
// float32 -> truncate -> exact fractional part -> *1e9 rounded to
// float32 -> truncate to int, transcribing the NumPy port's op
// sequence (rrtmg_mcica.py::_make_seeds / _kissvec) statement for
// statement.
//
// EVERY float arithmetic operation goes through RMCW_AD/SU/MU
// (__fadd_rn etc.): NVRTC defaults to --fmad=true and contraction is
// the dominant bitwise hazard; gfortran -O0 on x86-64 emits no FMA.
// Compile with --ftz=false: the walk product cdf*(1-cldf) is applied
// repeatedly down a column and reaches the FP32 subnormal range when
// many consecutive layers sit near cldf=1.  The host preflight
// (rrtmg_mcica.py::mcica_gpu_preflight) PROVES subnormal survival and
// the seed/kissvec chain on the live toolchain rather than assuming
// them.  No transcendentals exist on this path (the decorrelation
// exponentials belong to icld=4/5, which fail closed host-side).
//
// Integer RNG state is exact 32-bit wraparound arithmetic: unsigned
// carriers here, signed wraparound in the Fortran -- identical bit
// patterns (the NumPy port's uint32 masks document the
// correspondence), and Fortran ISHFT is a logical shift = unsigned C
// shifts.  Float->int conversions (__float2int_rz) saturate on CUDA
// where x86 wraps to INT_MIN; both conversions on the seed path are
// range-bounded for in-contract inputs (pmid < ~1.1e5 Pa physically,
// and frac*1e9 < 2^31 always because frac < 1 exactly: pmid and its
// truncation are within a factor of two, so the subtraction is exact
// by Sterbenz), hence the semantics never diverge.

#define RMCW_AD(a, b) __fadd_rn((a), (b))
#define RMCW_SU(a, b) __fsub_rn((a), (b))
#define RMCW_MU(a, b) __fmul_rn((a), (b))

#define RMCW_CLDMIN 1.0e-20f
#define RMCW_KISS_SCALE 2.328306e-10f
#define RMCW_PMID_SCALE 1.0e2f
#define RMCW_SEED_SCALE 1000000000.0f

// Output source kinds consumed by rmcw_walk_outputs (mirrored by
// rrtmg_mcica.py's _MCICA_SRC_* constants).
#define RMCW_SRC_CONST1 0  // cloudy value 1.0 (cldfmc)
#define RMCW_SRC_PERCOL 1  // cloudy value src[col, lay]
#define RMCW_SRC_BAND 2    // cloudy value src[bandoff[isub], col, lay]

// One kissvec state advance (module_ra_rrtmg_lw.F lines 2721-2725).
// The warm-up loop (lines 2433-2435) computes and discards the float
// draw; skipping the draw touches no state, so warm-up uses this alone.
__device__ __forceinline__ void rmcw_kiss_advance(
    unsigned int &s1, unsigned int &s2, unsigned int &s3,
    unsigned int &s4)
{
    s1 = 69069u * s1 + 1327217885u;
    s2 = s2 ^ (s2 << 13);
    s2 = s2 ^ (s2 >> 17);
    s2 = s2 ^ (s2 << 5);
    s3 = 18000u * (s3 & 0xFFFFu) + (s3 >> 16);
    s4 = 30903u * (s4 & 0xFFFFu) + (s4 >> 16);
}

// Advance + draw: REAL(kiss) is the signed int32 value converted
// round-nearest to float32, then one rounded multiply and one rounded
// add (line 2726; rrtmg_mcica.py::_kissvec).
__device__ __forceinline__ float rmcw_kiss_draw(
    unsigned int &s1, unsigned int &s2, unsigned int &s3,
    unsigned int &s4)
{
    rmcw_kiss_advance(s1, s2, s3, s4);
    unsigned int kiss = s1 + s2 + (s3 << 16) + s4;
    return RMCW_AD(RMCW_MU(__int2float_rn((int)kiss), RMCW_KISS_SCALE),
                   0.5f);
}

// One seed word from one bottom-layer pressure (lines 2428-2431):
// pmid = play*100 rounded once; INT() truncates; the fractional part
// is exact (Sterbenz); *1e9 rounded once; INT() truncates.
__device__ __forceinline__ unsigned int rmcw_seed_from_play(
    float play_mb)
{
    float pm = RMCW_MU(play_mb, RMCW_PMID_SCALE);
    int ipart = __float2int_rz(pm);
    float frac = RMCW_SU(pm, __int2float_rn(ipart));
    float scaled = RMCW_MU(frac, RMCW_SEED_SCALE);
    return (unsigned int)__float2int_rz(scaled);
}

// Preflight probe: x = [1e-30, 1e-10, play0..play3].  out[0] proves
// subnormal survival of __fmul_rn under the live compile options;
// out[1]/out[2] run the full seed chain plus two draws for bitwise
// comparison against the NumPy port's _make_seeds/_kissvec.
extern "C" __global__ void rmcw_probe(const float *x, float *out)
{
    if (blockIdx.x != 0 || threadIdx.x != 0) return;
    out[0] = RMCW_MU(x[0], x[1]);
    unsigned int s1 = rmcw_seed_from_play(x[2]);
    unsigned int s2 = rmcw_seed_from_play(x[3]);
    unsigned int s3 = rmcw_seed_from_play(x[4]);
    unsigned int s4 = rmcw_seed_from_play(x[5]);
    out[1] = rmcw_kiss_draw(s1, s2, s3, s4);
    out[2] = rmcw_kiss_draw(s1, s2, s3, s4);
}

// Kernel 1 -- one thread per column of the chunk: derive the column's
// four seed words from its bottom four layer-midpoint pressures,
// apply the changeSeed warm-up advances, then fill the chunk's raw
// CDF slab in the exact Fortran draw order for icld=2: subcolumn
// outer, layer inner (lines 2477-2482), one draw per (isubcol, ilev).
// All RNG state lives in registers; the per-column stream depends
// only on that column's play values and change_seed, which is what
// makes host-side chunking bitwise invisible.
//
// cdf layout (ngpt, nlay, nc): a warp handles adjacent columns, so
// the slab is written (and later read) coalesced.  The frozen
// (ngpt, ncol, nlay) output layout is materialized only by
// rmcw_walk_outputs.
extern "C" __global__ void rmcw_fill_cdf(
    int col0, int nc, int nlay, int ngpt, int change_seed,
    const float *__restrict__ play,  // (ncol_total, nlay) mb
    float *__restrict__ cdf)         // (ngpt, nlay, nc)
{
    int cc = blockDim.x * blockIdx.x + threadIdx.x;
    if (cc >= nc) return;
    const float *pcol = play + (size_t)(col0 + cc) * nlay;
    unsigned int s1 = rmcw_seed_from_play(pcol[0]);
    unsigned int s2 = rmcw_seed_from_play(pcol[1]);
    unsigned int s3 = rmcw_seed_from_play(pcol[2]);
    unsigned int s4 = rmcw_seed_from_play(pcol[3]);
    for (int i = 0; i < change_seed; ++i)
        rmcw_kiss_advance(s1, s2, s3, s4);
    size_t idx = (size_t)cc;
    for (int g = 0; g < ngpt; ++g) {
        for (int l = 0; l < nlay; ++l) {
            cdf[idx] = rmcw_kiss_draw(s1, s2, s3, s4);
            idx += (size_t)nc;
        }
    }
}

// Kernel 2 -- one thread per (subcolumn, column) pair: the icld=2
// maximum-random walk down the column (lines 2494-2504: keep the
// level-below value when it exceeded that layer's clear fraction,
// else rescale the fresh draw by it) and the >= 1-cldf cloud decision
// (line 2634), emitted as a one-byte iscloudy mask in the chunk-local
// (ngpt, nc, nlay) layout.  The cldmin floor (lines 2409-2416) is
// re-derived from raw cldfrac at each use -- a pure predicate, no
// rounding.  Splitting the mask from the output fill is pure data
// movement (the walk arithmetic is unchanged): the sequential-in-l
// walk thread writes 1 B/cell instead of 4*nout, and the fill below
// then streams the big slabs coalesced.
extern "C" __global__ void rmcw_walk_mask(
    int col0, int nc, int nlay, int ngpt,
    const float *__restrict__ cdf,      // (ngpt, nlay, nc)
    const float *__restrict__ cldfrac,  // (ncol_total, nlay)
    unsigned char *__restrict__ mask)   // (ngpt, nc, nlay)
{
    long long t = (long long)blockDim.x * blockIdx.x + threadIdx.x;
    if (t >= (long long)ngpt * nc) return;
    int isub = (int)(t / nc);
    int cc = (int)(t % nc);
    const float *cfcol = cldfrac + (size_t)(col0 + cc) * nlay;
    const float *cdfcol = cdf + (size_t)isub * nlay * nc + cc;
    unsigned char *mcol = mask + ((size_t)isub * nc + cc) * nlay;
    float prev = 0.0f;
    for (int l = 0; l < nlay; ++l) {
        float walked = cdfcol[(size_t)l * nc];
        if (l > 0) {
            float cfb = cfcol[l - 1];
            cfb = (cfb < RMCW_CLDMIN) ? 0.0f : cfb;
            float clear = RMCW_SU(1.0f, cfb);
            walked = (prev > clear) ? prev : RMCW_MU(walked, clear);
        }
        float cfl = cfcol[l];
        cfl = (cfl < RMCW_CLDMIN) ? 0.0f : cfl;
        mcol[l] = (walked >= RMCW_SU(1.0f, cfl)) ? 1 : 0;
        prev = walked;
    }
}

// Kernel 3 -- one thread per (subcolumn, column, layer) element: the
// output fill (lines 2642-2665), written straight into the frozen
// (ngpt, ncol_total, nlay) layout at the chunk's column offset.
// Adjacent threads share a row's adjacent layers, so every mask read,
// source gather and output store is coalesced.  No float arithmetic:
// values are copied from the sources or the clear-sky constants
// exactly as the Fortran assignments do.
//
// nout <= 8 descriptor-driven outputs so the LW roster (cldf, ciwp,
// clwp, cswp, tauc; clear values 0) and the SW roster (plus ssac with
// clear value 1, asmc, fsfc) share this one audited kernel; bandoff
// carries the 0-based ngb band index per g-point for RMCW_SRC_BAND
// sources.
extern "C" __global__ void rmcw_fill_outputs(
    int ncol_total, int col0, int nc, int nlay, int ngpt,
    const unsigned char *__restrict__ mask,          // (ngpt, nc, nlay)
    int nout,
    const unsigned long long *__restrict__ outptrs,  // [nout] float*
    const unsigned long long *__restrict__ srcptrs,  // [nout] float*
    const int *__restrict__ srckind,                 // [nout]
    const float *__restrict__ clearval,              // [nout]
    const int *__restrict__ bandoff)                 // [ngpt] 0-based
{
    long long t = (long long)blockDim.x * blockIdx.x + threadIdx.x;
    if (t >= (long long)ngpt * nc * nlay) return;
    int l = (int)(t % nlay);
    long long rest = t / nlay;
    int cc = (int)(rest % nc);
    int isub = (int)(rest / nc);
    int col = col0 + cc;
    bool cloudy = mask[t] != 0;
    size_t oidx = ((size_t)isub * ncol_total + col) * nlay + l;
    for (int j = 0; j < nout; ++j) {
        float v;
        if (cloudy) {
            int kind = srckind[j];
            const float *src = (const float *)srcptrs[j];
            if (kind == RMCW_SRC_CONST1) {
                v = 1.0f;
            } else if (kind == RMCW_SRC_PERCOL) {
                v = src[(size_t)col * nlay + l];
            } else {
                v = src[((size_t)bandoff[isub] * ncol_total + col)
                        * nlay + l];
            }
        } else {
            v = clearval[j];
        }
        ((float *)outptrs[j])[oidx] = v;
    }
}

// ---------------------------------------------------------------------
// Fused column-layout path (the forecast adapter's layout).  The three
// kernels above materialise a 4-byte raw CDF slab and a 1-byte mask per
// (subcolumn, column, layer) cell; these two kernels compute the same
// cells without either slab.
//
// The draw order is unchanged: one stream per column, subcolumn outer,
// layer inner, one advance + one draw per (isub, ilev).  So the stream
// state at the first draw of subcolumn isub is the column's seeded state
// after change_seed + isub * nlay advances.  rmcw_subcol_states walks
// each column's stream once with advances only (a draw's float result
// never feeds back into the state, the same fact the warm-up relies on)
// and records that state per subcolumn; rmcw_walk_fill_column then
// restarts every (column, subcolumn) pair from its recorded state and
// produces exactly the draws rmcw_fill_cdf would have stored, walks them
// exactly as rmcw_walk_mask does and stores the outputs exactly as
// rmcw_fill_outputs_column does.  Every float operation is the same
// RMCW_* intrinsic in the same order on the same operands.
// ---------------------------------------------------------------------

// Kernel 4 -- one thread per column of the chunk: seeds, warm-up, then
// the stream state before each subcolumn's first draw.
extern "C" __global__ void rmcw_subcol_states(
    int col0, int nc, int nlay, int ngpt, int change_seed,
    const float *__restrict__ play,     // (ncol_total, nlay) mb
    uint4 *__restrict__ states)         // (nc, ngpt)
{
    int cc = blockDim.x * blockIdx.x + threadIdx.x;
    if (cc >= nc) return;
    const float *pcol = play + (size_t)(col0 + cc) * nlay;
    unsigned int s1 = rmcw_seed_from_play(pcol[0]);
    unsigned int s2 = rmcw_seed_from_play(pcol[1]);
    unsigned int s3 = rmcw_seed_from_play(pcol[2]);
    unsigned int s4 = rmcw_seed_from_play(pcol[3]);
    for (int i = 0; i < change_seed; ++i)
        rmcw_kiss_advance(s1, s2, s3, s4);
    uint4 *row = states + (size_t)cc * ngpt;
    for (int g = 0; g < ngpt; ++g) {
        row[g] = make_uint4(s1, s2, s3, s4);
        for (int l = 0; l < nlay; ++l)
            rmcw_kiss_advance(s1, s2, s3, s4);
    }
}

// Kernel 5 -- one thread per (column, subcolumn), subcolumn fastest so a
// warp's stores at one layer are consecutive words of the column layout
// (ncol_total, nlay, ngpt).  Draw (rmcw_kiss_draw), walk and cloud
// decision are rmcw_walk_mask's statements; the store is
// rmcw_fill_outputs_column's.
extern "C" __global__ void rmcw_walk_fill_column(
    int ncol_total, int col0, int nc, int nlay, int ngpt,
    const uint4 *__restrict__ states,                // (nc, ngpt)
    const float *__restrict__ cldfrac,               // (ncol_total, nlay)
    int nout,
    const unsigned long long *__restrict__ outptrs,  // [nout] float*
    const unsigned long long *__restrict__ srcptrs,  // [nout] float*
    const int *__restrict__ srckind,                 // [nout]
    const float *__restrict__ clearval,              // [nout]
    const int *__restrict__ bandoff)                 // [ngpt] 0-based
{
    long long t = (long long)blockDim.x * blockIdx.x + threadIdx.x;
    if (t >= (long long)ngpt * nc) return;
    int isub = (int)(t % ngpt);
    int cc = (int)(t / ngpt);
    int col = col0 + cc;
    uint4 st = states[t];
    unsigned int s1 = st.x, s2 = st.y, s3 = st.z, s4 = st.w;
    const float *cfcol = cldfrac + (size_t)col * nlay;
    int band = bandoff[isub];
    float prev = 0.0f;
    for (int l = 0; l < nlay; ++l) {
        float walked = rmcw_kiss_draw(s1, s2, s3, s4);
        if (l > 0) {
            float cfb = cfcol[l - 1];
            cfb = (cfb < RMCW_CLDMIN) ? 0.0f : cfb;
            float clear = RMCW_SU(1.0f, cfb);
            walked = (prev > clear) ? prev : RMCW_MU(walked, clear);
        }
        float cfl = cfcol[l];
        cfl = (cfl < RMCW_CLDMIN) ? 0.0f : cfl;
        bool cloudy = walked >= RMCW_SU(1.0f, cfl);
        prev = walked;
        size_t oidx = ((size_t)col * nlay + l) * ngpt + isub;
        for (int j = 0; j < nout; ++j) {
            float v;
            if (cloudy) {
                int kind = srckind[j];
                const float *src = (const float *)srcptrs[j];
                if (kind == RMCW_SRC_CONST1) {
                    v = 1.0f;
                } else if (kind == RMCW_SRC_PERCOL) {
                    v = src[(size_t)col * nlay + l];
                } else {
                    v = src[((size_t)band * ncol_total + col) * nlay + l];
                }
            } else {
                v = clearval[j];
            }
            ((float *)outptrs[j])[oidx] = v;
        }
    }
}

// Column layout changes only the copy addresses.
extern "C" __global__ void rmcw_fill_outputs_column(
    int ncol_total, int col0, int nc, int nlay, int ngpt,
    const unsigned char *__restrict__ mask,          // (ngpt, nc, nlay)
    int nout,
    const unsigned long long *__restrict__ outptrs,  // [nout] float*
    const unsigned long long *__restrict__ srcptrs,  // [nout] float*
    const int *__restrict__ srckind,                 // [nout]
    const float *__restrict__ clearval,              // [nout]
    const int *__restrict__ bandoff)                 // [ngpt] 0-based
{
    long long t = (long long)blockDim.x * blockIdx.x + threadIdx.x;
    if (t >= (long long)ngpt * nc * nlay) return;
    int isub = (int)(t % ngpt);
    long long rest = t / ngpt;
    int l = (int)(rest % nlay);
    int cc = (int)(rest / nlay);
    int col = col0 + cc;
    bool cloudy = mask[((size_t)isub * nc + cc) * nlay + l] != 0;
    size_t oidx = ((size_t)col * nlay + l) * ngpt + isub;
    for (int j = 0; j < nout; ++j) {
        float v;
        if (cloudy) {
            int kind = srckind[j];
            const float *src = (const float *)srcptrs[j];
            if (kind == RMCW_SRC_CONST1) {
                v = 1.0f;
            } else if (kind == RMCW_SRC_PERCOL) {
                v = src[(size_t)col * nlay + l];
            } else {
                v = src[((size_t)bandoff[isub] * ncol_total + col)
                        * nlay + l];
            }
        } else {
            v = clearval[j];
        }
        ((float *)outptrs[j])[oidx] = v;
    }
}

#ifndef MPAS_FTZ_FALLBACK_ENABLED
#define MPAS_FTZ_FALLBACK_ENABLED 1
#endif

__device__ __forceinline__ unsigned int mpas_f32_magnitude_bits(
    const float value)
{
    return __float_as_uint(value) & 0x7fffffffu;
}

__device__ __forceinline__ bool mpas_is_subnormal_f32(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int magnitude = mpas_f32_magnitude_bits(value);
    return magnitude != 0u && (magnitude & 0x7f800000u) == 0u;
#else
    return false;
#endif
}

// A plain float/double cast is one of the measured DAZ mechanisms, so decode
// a subnormal float from its integer mantissa instead.
__device__ __forceinline__ double mpas_f32_to_f64_ieee(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int bits = __float_as_uint(value);
    const unsigned int magnitude = bits & 0x7fffffffu;
    if (magnitude != 0u && (magnitude & 0x7f800000u) == 0u) {
        const double decoded = ldexp(
            (double)(magnitude & 0x007fffffu), -149);
        return (bits & 0x80000000u) != 0u ? -decoded : decoded;
    }
#endif
    return (double)value;
}

// __double2float_rn flushes an FP32-subnormal result on the certified route,
// so pack that narrow result from the rounded integer mantissa.
__device__ __forceinline__ float mpas_f64_to_f32_ieee(const double value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const double magnitude = fabs(value);
    if (magnitude > 0.0 && magnitude < 1.1754943508222875e-38) {
        const double scaled = rint(
            magnitude * 7.1362384635297994e+44);  // 2^149
        const unsigned int mantissa = (unsigned int)scaled;
        const unsigned int sign =
            (__double_as_longlong(value) < 0LL) ? 0x80000000u : 0u;
        return __uint_as_float(sign | mantissa);
    }
#endif
    return __double2float_rn(value);
}

__device__ __forceinline__ float mpas_add(
    const float left, const float right)
{
    const float ordinary = left + right;
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int result_magnitude = mpas_f32_magnitude_bits(ordinary);
    const unsigned int result_exponent = result_magnitude >> 23;
    // A result at exponent field >=25 cannot have been rounded differently
    // by an FP32 subnormal operand, which is then below half an ulp.
    if (result_exponent > 24u) return ordinary;
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) + mpas_f32_to_f64_ieee(right));
    }
#endif
#if MPAS_FTZ_FALLBACK_ENABLED
    // Two normal binary32 values can cancel into the subnormal range only
    // while both exponent fields are <= 23; above that, one ulp is already
    // at least the smallest normal value.
    if (left_exponent <= 23u && right_exponent <= 23u
            && result_exponent == 0u
            && left_magnitude != right_magnitude
            && left_magnitude != 0u && right_magnitude != 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) + mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_sub(
    const float left, const float right)
{
    const float ordinary = left - right;
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int result_magnitude = mpas_f32_magnitude_bits(ordinary);
    const unsigned int result_exponent = result_magnitude >> 23;
    if (result_exponent > 24u) return ordinary;
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) - mpas_f32_to_f64_ieee(right));
    }
#endif
#if MPAS_FTZ_FALLBACK_ENABLED
    if (left_exponent <= 23u && right_exponent <= 23u
            && result_exponent == 0u
            && left_magnitude != right_magnitude
            && left_magnitude != 0u && right_magnitude != 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) - mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_mul(
    const float left, const float right)
{
    const float ordinary = left * right;
#if MPAS_FTZ_FALLBACK_ENABLED
    // A normal finite/overflow result proves neither operand was lost to DAZ
    // and no FTZ result occurred.  Inspect operands only on the rare zero or
    // subnormal-result envelope.
    if ((mpas_f32_magnitude_bits(ordinary) & 0x7f800000u) == 0u) {
        const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
        const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
        if (left_magnitude != 0u && right_magnitude != 0u) {
            return mpas_f64_to_f32_ieee(
                mpas_f32_to_f64_ieee(left) * mpas_f32_to_f64_ieee(right));
        }
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_div(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) / mpas_f32_to_f64_ieee(right));
    }
#endif
    const float ordinary = left / right;
#if MPAS_FTZ_FALLBACK_ENABLED
    if (left_magnitude != 0u && right_magnitude != 0u
            && left_exponent + 126u <= right_exponent
            && (mpas_f32_magnitude_bits(ordinary) & 0x7f800000u) == 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) / mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_sqrt(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(value)) {
        return mpas_f64_to_f32_ieee(sqrt(mpas_f32_to_f64_ieee(value)));
    }
#endif
    return sqrtf(value);
}

__device__ __forceinline__ float mpas_abs(const float value)
{
    return __uint_as_float(__float_as_uint(value) & 0x7fffffffu);
}

__device__ __forceinline__ float mpas_copysign(
    const float magnitude, const float sign)
{
    return __uint_as_float(
        (__float_as_uint(magnitude) & 0x7fffffffu)
        | (__float_as_uint(sign) & 0x80000000u));
}

__device__ __forceinline__ float mpas_min(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(left) || mpas_is_subnormal_f32(right)) {
        return mpas_f32_to_f64_ieee(right) < mpas_f32_to_f64_ieee(left)
            ? right : left;
    }
#endif
    return fminf(left, right);
}

__device__ __forceinline__ float mpas_max(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(left) || mpas_is_subnormal_f32(right)) {
        return mpas_f32_to_f64_ieee(right) > mpas_f32_to_f64_ieee(left)
            ? right : left;
    }
#endif
    return fmaxf(left, right);
}

/* Level-independent kernels walk a flat (level, owner) element index, owner
   fastest, in a grid-stride loop; each element runs the former per-owner
   loop body for its level unchanged, so the launch geometry is not in the
   arithmetic.  The forecast launches one thread per element. */
#define HORIZONTAL_ELEMENT_LOOP(total) \
    for (int element = blockDim.x * blockIdx.x + threadIdx.x; \
         element < (total); element += gridDim.x * blockDim.x)
__device__ __forceinline__ int lidx_v841(int level, int entity, int count) {
    return level * count + entity;
}
__device__ __forceinline__ float cell_sign_v841(
    int cell, int edge, const int *cells_on_edge)
{
    return cells_on_edge[2 * edge] == cell ? 1.0f : -1.0f;
}
__device__ __forceinline__ float vertex_sign_v841(
    int vertex, int edge, const int *vertices_on_edge)
{
    return vertices_on_edge[2 * edge] == vertex ? -1.0f : 1.0f;
}
__device__ __forceinline__ int kite_slot_v841(
    int vertex, int cell, const int *cells_on_vertex, int vertex_degree)
{
    for (int slot = 0; slot < vertex_degree; ++slot) {
        if (cells_on_vertex[vertex * vertex_degree + slot] == cell) return slot;
    }
    return -1;
}

extern "C" __global__ void vertex_diagnostics_v841_f32(
    const float *normal_velocity, const float *ke_edge,
    const int *edges_on_vertex, const int *vertices_on_edge,
    const float *dc_edge, const float *inv_area_triangle,
    const float *f_vertex, const int nlev, const int nedges,
    const int nvertices, const int vertex_degree,
    float *vorticity, float *ke_vertex, float *pv_vertex)
{
    HORIZONTAL_ELEMENT_LOOP(nlev * nvertices) {
        const int vertex = element % nvertices;
        const int k = element / nvertices;
        float vort = 0.0f;
        float ke = 0.0f;
        for (int slot = 0; slot < vertex_degree; ++slot) {
            const int edge = edges_on_vertex[vertex * vertex_degree + slot];
            if (edge < 0) continue;
            vort = mpas_add(vort, mpas_mul(mpas_mul(
                vertex_sign_v841(vertex, edge, vertices_on_edge), dc_edge[edge]),
                normal_velocity[lidx_v841(k, edge, nedges)]));
            ke = mpas_add(ke, ke_edge[lidx_v841(k, edge, nedges)]);
        }
        vort = mpas_mul(vort, inv_area_triangle[vertex]);
        const float r = mpas_mul(0.25f, inv_area_triangle[vertex]);
        ke = mpas_mul(ke, r);
        const int index = lidx_v841(k, vertex, nvertices);
        vorticity[index] = vort;
        ke_vertex[index] = ke;
        pv_vertex[index] = mpas_add(f_vertex[vertex], vort);
    }
}

#ifndef HEX_HOIST_EOE
#define HEX_HOIST_EOE 10
#endif
/* Thread-per-edge form of tangential_velocity_f32 (cuda_horizontal.py): the
   edge's neighbour indices and TRiSK weights are read once into registers
   and the thread walks the levels; each level runs the element body
   unchanged (same slot order, same helper calls), so each value carries the
   same bits. */
extern "C" __global__ void tangential_velocity_hoist_v841_f32(
    const float* normal_velocity,
    const int* edges_on_edge,
    const int* n_edges_on_edge,
    const float* weights_on_edge,
    const int nlev,
    const int nedges,
    const int max_edges2,
    float* tangential_velocity, const int lpt)
{
    const int hex_rows = nlev;
    const int hex_chunks = (hex_rows + lpt - 1) / lpt;
    const int hex_element = blockDim.x * blockIdx.x + threadIdx.x;
    if (hex_element >= nedges * hex_chunks) return;
    const int edge = hex_element % nedges;
    const int hex_k0 = (hex_element / nedges) * lpt;
    const int hex_k1 = min(hex_rows, hex_k0 + lpt);
    const int count = n_edges_on_edge[edge];
    if (count > HEX_HOIST_EOE) {
        for (int k = hex_k0; k < hex_k1; ++k) {
            float value = 0.0f;
            for (int slot = 0; slot < count; ++slot) {
                const int offset = edge * max_edges2 + slot;
                const int neighbor = edges_on_edge[offset];
                value = mpas_add(value, mpas_mul(weights_on_edge[offset],
                    normal_velocity[lidx_v841(k, neighbor, nedges)]));
            }
            tangential_velocity[lidx_v841(k, edge, nedges)] = value;
        }
        return;
    }
    int nb[HEX_HOIST_EOE];
    float wt[HEX_HOIST_EOE];
#pragma unroll
    for (int slot = 0; slot < HEX_HOIST_EOE; ++slot) {
        nb[slot] = slot < count ? edges_on_edge[edge * max_edges2 + slot] : edge;
        wt[slot] = slot < count ? weights_on_edge[edge * max_edges2 + slot] : 0.0f;
    }
    for (int k = hex_k0; k < hex_k1; ++k) {
        float value = 0.0f;
#pragma unroll
        for (int slot = 0; slot < HEX_HOIST_EOE; ++slot) {
            if (slot < count) {
                value = mpas_add(value, mpas_mul(wt[slot],
                    normal_velocity[lidx_v841(k, nb[slot], nedges)]));
            }
        }
        tangential_velocity[lidx_v841(k, edge, nedges)] = value;
    }
}

extern "C" __global__ void cell_diagnostics_v841_f32(
    const float *normal_velocity, const float *ke_edge,
    const float *ke_vertex, const int *edges_on_cell,
    const int *n_edges_on_cell, const int *cells_on_edge,
    const int *vertices_on_cell, const int *cells_on_vertex,
    const float *dv_edge, const float *inv_area_cell,
    const float *kite_areas, const int nlev, const int ncells,
    const int nedges, const int nvertices, const int max_edges,
    const int vertex_degree, float *divergence, float *kinetic_energy)
{
    HORIZONTAL_ELEMENT_LOOP(nlev * ncells) {
        const int cell = element % ncells;
        const int k = element / ncells;
        const int count = n_edges_on_cell[cell];
        const float inv_area = inv_area_cell[cell];
        const float ke_fact = 0.625f;
        float div = 0.0f;
        float ke = 0.0f;
        for (int slot = 0; slot < count; ++slot) {
            const int edge = edges_on_cell[cell * max_edges + slot];
            div = mpas_add(div, mpas_mul(mpas_mul(
                cell_sign_v841(cell, edge, cells_on_edge), dv_edge[edge]),
                normal_velocity[lidx_v841(k, edge, nedges)]));
            ke = mpas_add(ke, mpas_mul(
                0.25f, ke_edge[lidx_v841(k, edge, nedges)]));
        }
        div = mpas_mul(div, inv_area);
        ke = mpas_mul(ke, inv_area);
        ke = mpas_mul(ke, ke_fact);
        for (int slot = 0; slot < count; ++slot) {
            const int vertex = vertices_on_cell[cell * max_edges + slot];
            const int kite = kite_slot_v841(
                vertex, cell, cells_on_vertex, vertex_degree);
            if (kite >= 0) {
                float correction = mpas_mul(mpas_sub(1.0f, ke_fact),
                    kite_areas[vertex * vertex_degree + kite]);
                correction = mpas_mul(correction,
                    ke_vertex[lidx_v841(k, vertex, nvertices)]);
                correction = mpas_mul(correction, inv_area);
                ke = mpas_add(ke, correction);
            }
        }
        const int index = lidx_v841(k, cell, ncells);
        divergence[index] = div;
        kinetic_energy[index] = ke;
    }
}

extern "C" __global__ void laplacian_divergence_v841_f32(
    const float* delsq_u,
    const int* edges_on_cell,
    const int* n_edges_on_cell,
    const int* cells_on_edge,
    const float* dv_edge,
    const float* area_cell,
    const int nlev,
    const int ncells,
    const int nedges,
    const int max_edges,
    float* delsq_divergence
) {
    HORIZONTAL_ELEMENT_LOOP(nlev * ncells) {
        const int cell = element % ncells;
        const int k = element / ncells;
        const int count = n_edges_on_cell[cell];
        float value = 0.0f;
        for (int slot = 0; slot < count; ++slot) {
            const int edge = edges_on_cell[cell * max_edges + slot];
            value = mpas_add(value, mpas_mul(mpas_mul(mpas_mul(mpas_div(1.0f, area_cell[cell]), dv_edge[edge]),
                cell_sign_v841(cell, edge, cells_on_edge)), delsq_u[lidx_v841(k, edge, nedges)]));
        }
        delsq_divergence[lidx_v841(k, cell, ncells)] = value;
    }
}


extern "C" __global__ void laplacian_vorticity_v841_f32(
    const float* delsq_u,
    const int* edges_on_vertex,
    const int* vertices_on_edge,
    const float* dc_edge,
    const float* area_triangle,
    const int nlev,
    const int nedges,
    const int nvertices,
    const int vertex_degree,
    float* delsq_vorticity
) {
    const int vertex = blockDim.x * blockIdx.x + threadIdx.x;
    if (vertex >= nvertices) return;
    for (int k = 0; k < nlev; ++k) {
        float value = 0.0f;
        for (int slot = 0; slot < vertex_degree; ++slot) {
            const int edge = edges_on_vertex[vertex * vertex_degree + slot];
            if (edge < 0) continue;
            value = mpas_add(value, mpas_mul(mpas_mul(mpas_mul(mpas_div(1.0f, area_triangle[vertex]), dc_edge[edge]),
                vertex_sign_v841(vertex, edge, vertices_on_edge)), delsq_u[lidx_v841(k, edge, nedges)]));
        }
        delsq_vorticity[lidx_v841(k, vertex, nvertices)] = value;
    }
}


extern "C" __global__ void theta_filter_lap2_v841_f32(
    const float* theta_m,
    const float* rho_edge,
    const float* kdiff,
    const float* del2,
    const int* edges_on_cell,
    const int* n_edges_on_cell,
    const int* cells_on_edge,
    const float* dc_edge,
    const float* dv_edge,
    const float* area_cell,
    const int nlev,
    const int ncells,
    const int nedges,
    const int max_edges,
    float* delsq_theta,
    float* tendency
) {
    HORIZONTAL_ELEMENT_LOOP(nlev * ncells) {
        const int cell = element % ncells;
        const int k = element / ncells;
        const int count = n_edges_on_cell[cell];
        float lap = 0.0f;
        float tend = 0.0f;
        for (int slot = 0; slot < count; ++slot) {
            const int edge = edges_on_cell[cell * max_edges + slot];
            const int cell0 = cells_on_edge[2 * edge];
            const int cell1 = cells_on_edge[2 * edge + 1];
            const float factor = mpas_mul(mpas_mul(mpas_mul(mpas_div(1.0f, area_cell[cell]),
                cell_sign_v841(cell, edge, cells_on_edge)), dv_edge[edge]),
                mpas_div(1.0f, dc_edge[edge]));
            const float flux = mpas_mul(mpas_mul(factor, mpas_sub(
                theta_m[lidx_v841(k, cell1, ncells)],
                theta_m[lidx_v841(k, cell0, ncells)])),
                rho_edge[lidx_v841(k, edge, nedges)]);
            lap = mpas_add(lap, flux);
            tend = mpas_add(tend, mpas_mul(mpas_mul(mpas_mul(
                flux, 0.5f), mpas_add(
                    kdiff[lidx_v841(k, cell0, ncells)],
                    kdiff[lidx_v841(k, cell1, ncells)])), del2[edge]));
        }
        const int tid = lidx_v841(k, cell, ncells);
        delsq_theta[tid] = lap;
        tendency[tid] = tend;
    }
}


extern "C" __global__ void theta_filter_lap4_v841_f32(
    const float* delsq_theta,
    const float* del4,
    const int* edges_on_cell,
    const int* n_edges_on_cell,
    const int* cells_on_edge,
    const float* dc_edge,
    const float* dv_edge,
    const float* area_cell,
    const float h4,
    const int nlev,
    const int ncells,
    const int max_edges,
    float* tendency
) {
    HORIZONTAL_ELEMENT_LOOP(nlev * ncells) {
        const int cell = element % ncells;
        const int k = element / ncells;
        const int count = n_edges_on_cell[cell];
        const int tid = lidx_v841(k, cell, ncells);
        float tend = tendency[tid];
        for (int slot = 0; slot < count; ++slot) {
            const int edge = edges_on_cell[cell * max_edges + slot];
            const int cell0 = cells_on_edge[2 * edge];
            const int cell1 = cells_on_edge[2 * edge + 1];
            const float factor = mpas_mul(mpas_mul(mpas_mul(mpas_mul(del4[edge],
                mpas_mul(h4, mpas_div(1.0f, area_cell[cell]))), dv_edge[edge]),
                cell_sign_v841(cell, edge, cells_on_edge)), mpas_div(1.0f, dc_edge[edge]));
            tend = mpas_sub(tend, mpas_mul(factor, mpas_sub(
                delsq_theta[lidx_v841(k, cell1, ncells)],
                delsq_theta[lidx_v841(k, cell0, ncells)])));
        }
        tendency[tid] = tend;
    }
}


extern "C" __global__ void w_filter_lap2_v841_f32(
    const float* vertical_velocity,
    const float* rho_edge,
    const float* kdiff,
    const float* del2,
    const int* edges_on_cell,
    const int* n_edges_on_cell,
    const int* cells_on_edge,
    const float* dc_edge,
    const float* dv_edge,
    const float* area_cell,
    const int nlev,
    const int ncells,
    const int nedges,
    const int max_edges,
    float* delsq_w,
    float* tendency
) {
    HORIZONTAL_ELEMENT_LOOP(nlev * ncells) {
        const int cell = element % ncells;
        const int k = element / ncells;
        const int count = n_edges_on_cell[cell];
        const int tid = lidx_v841(k, cell, ncells);
        if (k == 0) {
            delsq_w[tid] = 0.0f;
            tendency[tid] = 0.0f;
            continue;
        }
        float lap = 0.0f;
        float tend = 0.0f;
        for (int slot = 0; slot < count; ++slot) {
            const int edge = edges_on_cell[cell * max_edges + slot];
            const int cell0 = cells_on_edge[2 * edge];
            const int cell1 = cells_on_edge[2 * edge + 1];
            const float factor = mpas_mul(mpas_mul(mpas_mul(mpas_mul(0.5f,
                mpas_div(1.0f, area_cell[cell])),
                cell_sign_v841(cell, edge, cells_on_edge)), dv_edge[edge]),
                mpas_div(1.0f, dc_edge[edge]));
            const float flux = mpas_mul(mpas_mul(factor, mpas_add(
                rho_edge[lidx_v841(k, edge, nedges)],
                rho_edge[lidx_v841(k - 1, edge, nedges)])), mpas_sub(
                    vertical_velocity[lidx_v841(k, cell1, ncells)],
                    vertical_velocity[lidx_v841(k, cell0, ncells)]));
            lap = mpas_add(lap, flux);
            const float sum_k = mpas_add(mpas_add(mpas_add(
                kdiff[lidx_v841(k, cell0, ncells)],
                kdiff[lidx_v841(k, cell1, ncells)]),
                kdiff[lidx_v841(k - 1, cell0, ncells)]),
                kdiff[lidx_v841(k - 1, cell1, ncells)]);
            tend = mpas_add(tend, mpas_mul(mpas_mul(mpas_mul(
                flux, del2[edge]), 0.25f), sum_k));
        }
        delsq_w[tid] = lap;
        tendency[tid] = tend;
    }
}


extern "C" __global__ void w_filter_lap4_v841_f32(
    const float* delsq_w,
    const float* del4,
    const int* edges_on_cell,
    const int* n_edges_on_cell,
    const int* cells_on_edge,
    const float* dc_edge,
    const float* dv_edge,
    const float* area_cell,
    const float h4,
    const int nlev,
    const int ncells,
    const int max_edges,
    float* tendency
) {
    /* Rows 1..nlev-1 only, as the per-cell loop ran them. */
    HORIZONTAL_ELEMENT_LOOP((nlev - 1) * ncells) {
        const int cell = element % ncells;
        const int k = 1 + element / ncells;
        const int count = n_edges_on_cell[cell];
        const int tid = lidx_v841(k, cell, ncells);
        float tend = tendency[tid];
        for (int slot = 0; slot < count; ++slot) {
            const int edge = edges_on_cell[cell * max_edges + slot];
            const int cell0 = cells_on_edge[2 * edge];
            const int cell1 = cells_on_edge[2 * edge + 1];
            const float factor = mpas_mul(mpas_mul(mpas_mul(mpas_mul(del4[edge],
                mpas_mul(h4, mpas_div(1.0f, area_cell[cell]))), dv_edge[edge]),
                cell_sign_v841(cell, edge, cells_on_edge)), mpas_div(1.0f, dc_edge[edge]));
            tend = mpas_sub(tend, mpas_mul(factor, mpas_sub(
                delsq_w[lidx_v841(k, cell1, ncells)],
                delsq_w[lidx_v841(k, cell0, ncells)])));
        }
        tendency[tid] = tend;
    }
}


extern "C" __global__ void momentum_filter_lap4_v841_f32(
    const float* rho_edge,
    const float* delsq_divergence,
    const float* delsq_vorticity,
    const float* del4,
    const int* cells_on_edge,
    const int* vertices_on_edge,
    const float* dc_edge,
    const float* dv_edge,
    const float h4,
    const float div_factor,
    const int nlev,
    const int ncells,
    const int nedges,
    const int nvertices,
    float* tendency
) {
    const int edge = blockDim.x * blockIdx.x + threadIdx.x;
    if (edge >= nedges) return;
    const int cell0 = cells_on_edge[2 * edge];
    const int cell1 = cells_on_edge[2 * edge + 1];
    const int vertex0 = vertices_on_edge[2 * edge];
    const int vertex1 = vertices_on_edge[2 * edge + 1];
    const float inv_dc = 1.0f / dc_edge[edge];
    const float inv_dv = fminf(1.0f / dv_edge[edge], 4.0f * inv_dc);
    const float scale = mpas_mul(del4[edge], h4);
    // Native prepares these rounded geometry coefficients outside the level loop.
    const float r_dc = mpas_mul(mpas_mul(scale, div_factor), inv_dc);
    const float r_dv = mpas_mul(scale, inv_dv);
    for (int k = 0; k < nlev; ++k) {
        const int tid = lidx_v841(k, edge, nedges);
        const float diffusion = mpas_mul(rho_edge[tid], mpas_sub(
            mpas_mul(mpas_sub(
                delsq_divergence[lidx_v841(k, cell1, ncells)],
                delsq_divergence[lidx_v841(k, cell0, ncells)]), r_dc),
            mpas_mul(mpas_sub(
                delsq_vorticity[lidx_v841(k, vertex1, nvertices)],
                delsq_vorticity[lidx_v841(k, vertex0, nvertices)]), r_dv)));
        tendency[tid] = mpas_sub(tendency[tid], diffusion);
    }
}


extern "C" __global__ void momentum_filter_seed_v841_f32(
    const float* rho_edge, const float* divergence, const float* vorticity,
    const float* kdiff, const float* del2, const int* cells_on_edge,
    const int* vertices_on_edge, const float* dc_edge, const float* dv_edge,
    const int nlev, const int ncells, const int nedges, const int nvertices,
    float* delsq_u, float* tendency)
{
    const int edge = blockDim.x * blockIdx.x + threadIdx.x;
    if (edge >= nedges) return;
    const int c0 = cells_on_edge[2*edge], c1 = cells_on_edge[2*edge+1];
    const int v0 = vertices_on_edge[2*edge], v1 = vertices_on_edge[2*edge+1];
    const float inv_dc = mpas_div(1.0f, dc_edge[edge]);
    const float inv_dv = mpas_min(mpas_div(1.0f, dv_edge[edge]), mpas_mul(4.0f, inv_dc));
    for (int k=0; k<nlev; ++k) {
        const int tid=lidx_v841(k,edge,nedges);
        const float lap=mpas_sub(mpas_mul(mpas_sub(divergence[lidx_v841(k,c1,ncells)],divergence[lidx_v841(k,c0,ncells)]),inv_dc),mpas_mul(mpas_sub(vorticity[lidx_v841(k,v1,nvertices)],vorticity[lidx_v841(k,v0,nvertices)]),inv_dv));
        const float kedge=mpas_mul(0.5f,mpas_add(kdiff[lidx_v841(k,c0,ncells)],kdiff[lidx_v841(k,c1,ncells)]));
        delsq_u[tid]=lap;
        // Native adds del2 directly to the saved pressure-gradient pool,
        // then subtracts del4 from that already-rounded sum (F:721,803).
        tendency[tid]=mpas_add(tendency[tid],mpas_mul(mpas_mul(mpas_mul(rho_edge[tid],kedge),lap),del2[edge]));
    }
}

extern "C" __global__ void smagorinsky_v841_f32(
    const float *normal_velocity, const float *tangential_velocity,
    const int *edges_on_cell, const int *n_edges_on_cell,
    const float *coef_c2, const float *coef_s2, const float *coef_cs,
    const float strain_scale, const float ceiling,
    const int nlev, const int ncells, const int nedges, const int max_edges,
    float *kdiff)
{
    // mpas_atm_dissipation_models.F:119-204 (smagorinsky_2d): full
    // velocity-gradient tensor from the precomputed v8.4.1 deformation
    // weights, D11 = 2 du/dx, D22 = 2 dv/dy, D12 = du/dy + dv/dx,
    // kdiff = (c_s*len)**2 * sqrt(0.25*(D11-D22)**2 + D12**2) capped at
    // (0.01*len**2)*invDt.
    HORIZONTAL_ELEMENT_LOOP(nlev * ncells) {
        const int cell = element % ncells;
        const int k = element / ncells;
        const int count = n_edges_on_cell[cell];
        float dudx = 0.0f;
        float dudy = 0.0f;
        float dvdx = 0.0f;
        float dvdy = 0.0f;
        for (int slot = 0; slot < count; ++slot) {
            const int offset = cell * max_edges + slot;
            const int edge = edges_on_cell[offset];
            const float u = normal_velocity[lidx_v841(k, edge, nedges)];
            const float v = tangential_velocity[lidx_v841(k, edge, nedges)];
            const float c2 = coef_c2[offset];
            const float s2 = coef_s2[offset];
            const float cs = coef_cs[offset];
            dudx = mpas_sub(mpas_add(dudx, mpas_mul(c2, u)), mpas_mul(cs, v));
            dudy = mpas_sub(mpas_add(dudy, mpas_mul(cs, u)), mpas_mul(s2, v));
            dvdx = mpas_add(mpas_add(dvdx, mpas_mul(cs, u)), mpas_mul(c2, v));
            dvdy = mpas_add(mpas_add(dvdy, mpas_mul(s2, u)), mpas_mul(cs, v));
        }
        const float d_11 = mpas_mul(2.0f, dudx);
        const float d_22 = mpas_mul(2.0f, dvdy);
        const float d_12 = mpas_add(dudy, dvdx);
        const float diff = mpas_sub(d_11, d_22);
        const float strain = mpas_sqrt(mpas_add(
            mpas_mul(0.25f, mpas_mul(diff, diff)),
            mpas_mul(d_12, d_12)));
        kdiff[lidx_v841(k, cell, ncells)] = mpas_min(
            mpas_mul(strain_scale, strain), ceiling);
    }
}

extern "C" __global__ void pv_cell_v841_f32(
    const float *pv_vertex, const int *vertices_on_cell,
    const int *n_edges_on_cell, const int *cells_on_vertex,
    const float *kite_areas, const float *inv_area_cell,
    const int nlev, const int ncells, const int nvertices,
    const int max_edges, const int vertex_degree, float *pv_cell)
{
    HORIZONTAL_ELEMENT_LOOP(nlev * ncells) {
        const int cell = element % ncells;
        const int k = element / ncells;
        const int count = n_edges_on_cell[cell];
        float value = 0.0f;
        for (int slot = 0; slot < count; ++slot) {
            const int vertex = vertices_on_cell[cell * max_edges + slot];
            const int kite = kite_slot_v841(
                vertex, cell, cells_on_vertex, vertex_degree);
            if (kite >= 0) {
                float contribution = mpas_mul(
                    kite_areas[vertex * vertex_degree + kite],
                    pv_vertex[lidx_v841(k, vertex, nvertices)]);
                contribution = mpas_mul(contribution, inv_area_cell[cell]);
                value = mpas_add(value, contribution);
            }
        }
        pv_cell[lidx_v841(k, cell, ncells)] = value;
    }
}

extern "C" __global__ void pv_apvm_v841_f32(
    const float *normal_velocity, const float *tangential_velocity,
    const float *pv_vertex, const float *pv_cell,
    const int *vertices_on_edge, const int *cells_on_edge,
    const float *inv_dc_edge, const float *inv_dv_edge, const float scale,
    const int nlev, const int ncells, const int nedges, const int nvertices,
    float *pv_edge, float *grad_pv_normal, float *grad_pv_tangential)
{
    HORIZONTAL_ELEMENT_LOOP(nlev * nedges) {
        const int edge = element % nedges;
        const int k = element / nedges;
        const int vertex0 = vertices_on_edge[2 * edge];
        const int vertex1 = vertices_on_edge[2 * edge + 1];
        const int cell0 = cells_on_edge[2 * edge];
        const int cell1 = cells_on_edge[2 * edge + 1];
        const int index = lidx_v841(k, edge, nedges);
        const float grad_t = mpas_mul(mpas_sub(
            pv_vertex[lidx_v841(k, vertex1, nvertices)],
            pv_vertex[lidx_v841(k, vertex0, nvertices)]), inv_dv_edge[edge]);
        const float grad_n = mpas_mul(mpas_sub(
            pv_cell[lidx_v841(k, cell1, ncells)],
            pv_cell[lidx_v841(k, cell0, ncells)]), inv_dc_edge[edge]);
        grad_pv_tangential[index] = grad_t;
        grad_pv_normal[index] = grad_n;
        pv_edge[index] = mpas_sub(pv_edge[index], mpas_mul(scale, mpas_add(
            mpas_mul(tangential_velocity[index], grad_t),
            mpas_mul(normal_velocity[index], grad_n))));
    }
}

extern "C" __global__ void mass_flux_divergence_v841_f32(
    const float *rho_u, const int *edges_on_cell,
    const int *n_edges_on_cell, const int *cells_on_edge,
    const float *dv_edge, const float *inv_area_cell,
    const int nlev, const int ncells, const int nedges,
    const int max_edges, float *mass_divergence)
{
    HORIZONTAL_ELEMENT_LOOP(nlev * ncells) {
        const int cell = element % ncells;
        const int k = element / ncells;
        const int count = n_edges_on_cell[cell];
        float value = 0.0f;
        for (int slot = 0; slot < count; ++slot) {
            const int edge = edges_on_cell[cell * max_edges + slot];
            value = mpas_add(value, mpas_mul(mpas_mul(
                cell_sign_v841(cell, edge, cells_on_edge), dv_edge[edge]),
                rho_u[lidx_v841(k, edge, nedges)]));
        }
        mass_divergence[lidx_v841(k, cell, ncells)] = mpas_mul(
            value, inv_area_cell[cell]);
    }
}

extern "C" __global__ void pressure_gradient_v841_f32(
    const float *pressure_p, const float *dpdz, const float *cqu,
    const float *zz, const float *zxu, const int *cells_on_edge,
    const float *inv_dc_edge, const int nlev, const int ncells,
    const int nedges, float *tendency)
{
    const int edge = blockDim.x * blockIdx.x + threadIdx.x;
    if (edge >= nedges) return;
    const int cell0 = cells_on_edge[2 * edge];
    const int cell1 = cells_on_edge[2 * edge + 1];
    for (int k = 0; k < nlev; ++k) {
        const int index = lidx_v841(k, edge, nedges);
        float normal = mpas_mul(mpas_sub(
            pressure_p[lidx_v841(k, cell1, ncells)],
            pressure_p[lidx_v841(k, cell0, ncells)]), inv_dc_edge[edge]);
        normal = mpas_div(normal, mpas_mul(0.5f, mpas_add(
            zz[lidx_v841(k, cell1, ncells)],
            zz[lidx_v841(k, cell0, ncells)])));
        const float terrain = mpas_mul(mpas_mul(0.5f, zxu[index]), mpas_add(
            dpdz[lidx_v841(k, cell0, ncells)],
            dpdz[lidx_v841(k, cell1, ncells)]));
        tendency[index] = mpas_mul(mpas_sub(0.0f, cqu[index]),
            mpas_sub(normal, terrain));
    }
}

#ifndef HEX_HOIST_CELL
#define HEX_HOIST_CELL 10
#endif
#define HEX_CELL_CHUNK(rows) \
    const int hex_rows = (rows); \
    const int hex_chunks = (hex_rows + lpt - 1) / lpt; \
    const int hex_element = blockDim.x * blockIdx.x + threadIdx.x; \
    if (hex_element >= ncells * hex_chunks) return; \
    const int cell = hex_element % ncells; \
    const int hex_k0 = (hex_element / ncells) * lpt; \
    const int hex_k1 = min(hex_rows, hex_k0 + lpt);

extern "C" __global__ void cell_diagnostics_chunk_v841_f32(
    const float *normal_velocity, const float *ke_edge,
    const float *ke_vertex, const int *edges_on_cell,
    const int *n_edges_on_cell, const int *cells_on_edge,
    const int *vertices_on_cell, const int *cells_on_vertex,
    const float *dv_edge, const float *inv_area_cell,
    const float *kite_areas, const int nlev, const int ncells,
    const int nedges, const int nvertices, const int max_edges,
    const int vertex_degree, float *divergence, float *kinetic_energy,
    const int lpt)
{
    HEX_CELL_CHUNK(nlev)
    const int count = n_edges_on_cell[cell];
    const float inv_area = inv_area_cell[cell];
    const float ke_fact = 0.625f;
    if (count > HEX_HOIST_CELL) {
        for (int k = hex_k0; k < hex_k1; ++k) {
            float div = 0.0f;
            float ke = 0.0f;
            for (int slot = 0; slot < count; ++slot) {
                const int edge = edges_on_cell[cell * max_edges + slot];
                div = mpas_add(div, mpas_mul(mpas_mul(
                    cell_sign_v841(cell, edge, cells_on_edge), dv_edge[edge]),
                    normal_velocity[lidx_v841(k, edge, nedges)]));
                ke = mpas_add(ke, mpas_mul(
                    0.25f, ke_edge[lidx_v841(k, edge, nedges)]));
            }
            div = mpas_mul(div, inv_area);
            ke = mpas_mul(ke, inv_area);
            ke = mpas_mul(ke, ke_fact);
            for (int slot = 0; slot < count; ++slot) {
                const int vertex = vertices_on_cell[cell * max_edges + slot];
                const int kite = kite_slot_v841(
                    vertex, cell, cells_on_vertex, vertex_degree);
                if (kite >= 0) {
                    float correction = mpas_mul(mpas_sub(1.0f, ke_fact),
                        kite_areas[vertex * vertex_degree + kite]);
                    correction = mpas_mul(correction,
                        ke_vertex[lidx_v841(k, vertex, nvertices)]);
                    correction = mpas_mul(correction, inv_area);
                    ke = mpas_add(ke, correction);
                }
            }
            const int index = lidx_v841(k, cell, ncells);
            divergence[index] = div;
            kinetic_energy[index] = ke;
        }
        return;
    }
    int ed[HEX_HOIST_CELL];
    float sdv[HEX_HOIST_CELL];
    int vx[HEX_HOIST_CELL];
    float kc[HEX_HOIST_CELL];
    bool kv[HEX_HOIST_CELL];
#pragma unroll
    for (int slot = 0; slot < HEX_HOIST_CELL; ++slot) {
        const bool live = slot < count;
        const int edge = live ? edges_on_cell[cell * max_edges + slot] : 0;
        ed[slot] = edge;
        sdv[slot] = live ? mpas_mul(cell_sign_v841(cell, edge, cells_on_edge), dv_edge[edge]) : 0.0f;
        const int vertex = live ? vertices_on_cell[cell * max_edges + slot] : 0;
        vx[slot] = vertex;
        const int kite = live ? kite_slot_v841(vertex, cell, cells_on_vertex, vertex_degree) : -1;
        kv[slot] = kite >= 0;
        kc[slot] = kite >= 0 ? mpas_mul(mpas_sub(1.0f, ke_fact),
            kite_areas[vertex * vertex_degree + kite]) : 0.0f;
    }
    for (int k = hex_k0; k < hex_k1; ++k) {
        float div = 0.0f;
        float ke = 0.0f;
#pragma unroll
        for (int slot = 0; slot < HEX_HOIST_CELL; ++slot) {
            if (slot < count) {
                div = mpas_add(div, mpas_mul(sdv[slot],
                    normal_velocity[lidx_v841(k, ed[slot], nedges)]));
                ke = mpas_add(ke, mpas_mul(
                    0.25f, ke_edge[lidx_v841(k, ed[slot], nedges)]));
            }
        }
        div = mpas_mul(div, inv_area);
        ke = mpas_mul(ke, inv_area);
        ke = mpas_mul(ke, ke_fact);
#pragma unroll
        for (int slot = 0; slot < HEX_HOIST_CELL; ++slot) {
            if (slot < count && kv[slot]) {
                float correction = mpas_mul(kc[slot],
                    ke_vertex[lidx_v841(k, vx[slot], nvertices)]);
                correction = mpas_mul(correction, inv_area);
                ke = mpas_add(ke, correction);
            }
        }
        const int index = lidx_v841(k, cell, ncells);
        divergence[index] = div;
        kinetic_energy[index] = ke;
    }
}

