#define GFK_TG_PI   0x1.921fb54442d18p+1
#define GFK_TG_QNAN __uint_as_float(0x7fc00000u)

// Gamma(r) for r in [1,2).  All arithmetic pinned to binary64 add/mul; the
// two subtractions below are exact (Sterbenz), so j and u are exact.
__device__ double gfk_tgamma_poly(double r)
{
    double t = DMUL(DSUB(r, 1.0), 16.0);                 /* [0,16), exact */
    int j = (int)t;
    if (j > 15) j = 15;                                  /* r = nextbelow(2) */
    double u = DSUB(r, DMUL((double)(33 + 2 * j), 0.03125));   /* exact */
    const double *c = GFK_TG_C[j];
    double p = c[9];
    p = DADD(DMUL(p, u), c[8]);
    p = DADD(DMUL(p, u), c[7]);
    p = DADD(DMUL(p, u), c[6]);
    p = DADD(DMUL(p, u), c[5]);
    p = DADD(DMUL(p, u), c[4]);
    p = DADD(DMUL(p, u), c[3]);
    p = DADD(DMUL(p, u), c[2]);
    p = DADD(DMUL(p, u), c[1]);
    p = DADD(DMUL(p, u), c[0]);
    return p;
}

// Gamma(v) in binary64 for 0 < v < 43 (the caller's x < 36 guard bounds the
// reflected argument 1-x below 43, so the recurrence runs at most 41 times).
__device__ double gfk_tgamma_pos(double v)
{
    if (v >= 1.0) {
        int n = (int)v;                                  /* 1 .. 42 */
        double r = DSUB(v, (double)(n - 1));             /* [1,2), exact */
        double p = gfk_tgamma_poly(r);
        for (int i = 1; i < n; i++)
            p = DMUL(p, DSUB(v, (double)i));
        return p;
    }
    return DDIV(gfk_tgamma_poly(DADD(v, 1.0)), v);       /* Gamma(v)=Gamma(v+1)/v */
}

// sin(pi*x) for |x| < 2^23.  k and the subtraction are exact.
__device__ double gfk_tgamma_sinpi(double x)
{
    long long k = (long long)(x < 0.0 ? DSUB(x, 0.5) : DADD(x, 0.5));
    double r  = DSUB(x, (double)k);                      /* [-1/2,1/2], exact */
    double r2 = DMUL(r, r);
    double s  = GFK_TG_SP[12];
    for (int i = 11; i >= 0; i--) s = DADD(DMUL(s, r2), GFK_TG_SP[i]);
    s = DMUL(s, r);
    return (k & 1) ? -s : s;
}

// The correctly-rounded float32 gamma.
//
// The 36.0f overflow guard is arithmetic, not inherited: MEASURED, the last
// float32 with a finite Gamma is 35.0401001, and binary64 holds Gamma out to
// x = 171.6, so ANY threshold in [35.041, 171] gives the same float32 answer
// on every argument.  36 is taken as the smallest integer above the overflow
// point, which is also what bounds the recurrence trip count above at 42.
// glibc picks the same number for the same arithmetic reason; the choice is
// free within a 136-wide interval and carries no expression.
__device__ float gfk_tgamma(float x)
{
    unsigned int ix = __float_as_uint(x);
    unsigned int ax = ix & 0x7fffffffu;

    if (ax >= 0x7f800000u) {                    /* inf / nan */
        if (ix == 0xff800000u) return GFK_TG_QNAN;      /* -inf  -> qNaN */
        return FADD(x, x);                              /* +inf  -> +inf
                                                           NaN   -> same, quieted */
    }
    if (ix < 0x80000000u) {                     /* x >= +0 */
        if (ix == 0u) return FDIV(1.0f, x);             /* +0 -> +inf */
        if (x >= 36.0f)
            return FMUL(FMUL(x, 0x1p127f), 0x1p127f);   /* -> +inf */
        return gfk_d2f_rn(gfk_tgamma_pos((double)x));
    }
    /* x < 0: reflection  Gamma(x) = pi / (sin(pi x) * Gamma(1-x)) */
    if (ix == 0x80000000u) return FDIV(1.0f, x);        /* -0 -> -inf */
    if (ax >= 0x4b000000u) return GFK_TG_QNAN;          /* |x| >= 2^23: every
                                                           float is an integer,
                                                           so every one is a pole */
    {
        double s = gfk_tgamma_sinpi((double)x);
        if (s == 0.0) return GFK_TG_QNAN;               /* negative integer: pole */
        if (x <= -42.0f)                                /* |Gamma| < 2^-150 below
                                                           here; measured, the
                                                           last non-zero float32
                                                           result is at -41.000042 */
            return (s < 0.0) ? -0.0f : 0.0f;
        {
            double g1 = gfk_tgamma_pos(DSUB(1.0, (double)x));   /* 1-x in (1,43) */
            return gfk_d2f_rn(DDIV(GFK_TG_PI, DMUL(s, g1)));
        }
    }
}

// WOOF's own float32 exp, contracted form: gfk_exp_fma.
//
// Requires glibc_flt32.cuh ahead of it in the assembled source (the loader's
// _EXTRA_HEADERS lists both, in that order).  It holds no table of its own:
// the scale 2**(k/32) comes from that header's gfk_exp2_core called with a
// zero polynomial (which returns its table scale exactly), and it reuses the
// polynomial constants GFK_EXP2F_P0..P2, GFK_EXP2F_SHIFT and gfk_d2f_rn.
//
// WHY A SECOND FORM.  gfk_exp evaluates every a*b+c of the algorithm as a
// separate multiply and add.  The reference a WRF column oracle calls on an
// x86-64 host with FMA (every oracle host here: W1's Xeon Platinum 8559C,
// a development machine) is the C library's run-time-selected FMA build of expf, whose
// multiply-adds are fused.  The two forms differ at exactly two float32
// inputs over the whole line -- x = 0x4202422F (32.5646324) and
// x = 0xC27C65D9 (-63.0994606), 1 ULP each -- measured by
// tools/myjpbl_wrf461_oracle/libm_sweep.py over all 2**32 inputs on W1.
// gfk_exp_fma fuses the same five sites (the shift add, the reduced
// argument, both polynomial halves and their combination) with explicit
// __fma_rn, so it is unaffected by --fmad and matches the reference at every
// input (same sweep).  The MYJ PBL calls it; kernels/mynn_pbl.cu carries the
// same contracted form privately as mynn_glibc_expf.

__device__ float gfk_exp_fma(float x)
{
    unsigned int ix = __float_as_uint(x);
    unsigned int abstop = (ix >> 20) & 0x7ffu;
    if (abstop >= ((__float_as_uint(88.0f)) >> 20)) {
        if (ix == 0xff800000u) return 0.0f;
        if (abstop >= (0x7f800000u >> 20)) return __fadd_rn(x, x);
        if (x > __int_as_float(0x42b17218)) return __int_as_float(0x7f800000);
        if (x < -__int_as_float(0x42cff1b4)) return 0.0f;
    }
    const double inv_ln2_n = 0x1.71547652b82fep+0 * 32.0;
    double xd = (double)x;
    double kd = __fma_rn(inv_ln2_n, xd, GFK_EXP2F_SHIFT);
    kd = __dsub_rn(kd, GFK_EXP2F_SHIFT);
    double r = __fma_rn(inv_ln2_n, xd, -kd);
    // kd is an integer-valued double, so kd + SHIFT inside the core
    // rebuilds the fused shift sum above bit for bit (the same table index
    // and exponent bits); with a zero
    // polynomial the core returns 1.0 * scale, the scale exactly.
    double s = gfk_exp2_core(kd, GFK_EXP2F_SHIFT, 0.0, 0.0, 0.0, 0ULL);
    double z = __fma_rn(GFK_EXP2F_P0 / 32.0 / 32.0 / 32.0, r,
                        GFK_EXP2F_P1 / 32.0 / 32.0);
    double r2 = __dmul_rn(r, r);
    double y = __fma_rn(GFK_EXP2F_P2 / 32.0, r, 1.0);
    y = __dmul_rn(__fma_rn(z, r2, y), s);
    return gfk_d2f_rn(y);
}


// MPAS-A v8.4.2, pinned f34984b. RKIND is REAL(4).
// Elementary functions come from the engine's shared glibc device headers.
#define A(a,b) __fadd_rn((a),(b))
#define S(a,b) __fsub_rn((a),(b))
#define M(a,b) __fmul_rn((a),(b))
#define D(a,b) __fdiv_rn((a),(b))

// mpas_isobaric_diagnostics.F:1005-1091, including the collective kupper
// search and exact-top equality behavior. One cooperative block handles
// arbitrary ncol with strided work, preserving native kount semantics.
extern "C" __global__ void fixed_pressure(
    int nc,int ni,int no,const float* p,const float* f,const float* po,
    float* out,int* upper) {
    int t=threadIdx.x;
    __shared__ int start,count,all;
    for(int c=t;c<nc;c+=blockDim.x) upper[c]=0;
    __syncthreads();
    for(int k=0;k<no;k++) {
        if(t==0) {start=ni-1;count=0;all=0;}
        __syncthreads();
        for(int c=t;c<nc;c+=blockDim.x) atomicMin(&start,upper[c]);
        __syncthreads();
        for(int kk=start;kk<ni-1;kk++) {
            for(int c=t;c<nc;c+=blockDim.x) {
                float q=po[c*no+k];
                if(q>p[c*ni+kk] && q<=p[c*ni+kk+1]) {
                    upper[c]=kk;atomicAdd(&count,1);
                }
            }
            __syncthreads();
            if(count==nc) {if(t==0) all=1;break;}
        }
        __syncthreads();
        for(int c=t;c<nc;c+=blockDim.x) {
            float q=po[c*no+k]; int u=upper[c];
            if(!all && q<p[c*ni]) out[c*no+k]=D(M(f[c*ni],q),p[c*ni]);
            else if(!all && q>p[c*ni+ni-1]) out[c*no+k]=f[c*ni+ni-1];
            else {
                float dpu=S(q,p[c*ni+u]),dpl=S(p[c*ni+u+1],q);
                out[c*no+k]=D(A(M(f[c*ni+u],dpl),M(f[c*ni+u+1],dpu)),A(dpl,dpu));
            }
        }
        __syncthreads();
    }
}

// The same routine across the whole grid (fixed_pressure is one block, kept as
// the referee). Per output level k, with start[k] = min over columns of the
// carried kupper: count[k*ni+kk] counts bracket hits at kk; a one-thread scan
// finds the first kk whose running count equals ncol exactly (native kount);
// apply re-finds each column's last hit through that kk, interpolates and
// folds its kupper into start[k+1]. Same words as the one-block kernel.
extern "C" __global__ void fixed_pressure_count(
    int nc,int ni,int no,int k,const float* p,const float* po,const int* upper,
    const int* start,int* count) {
    int c=blockIdx.x*blockDim.x+threadIdx.x;if(c>=nc)return;
    float q=po[c*no+k];
    for(int kk=start[k];kk<ni-1;kk++)
        if(q>p[c*ni+kk] && q<=p[c*ni+kk+1]) atomicAdd(&count[k*ni+kk],1);
}
extern "C" __global__ void fixed_pressure_scan(
    int nc,int ni,int k,const int* start,const int* count,int* stop) {
    if(blockIdx.x||threadIdx.x)return;
    int total=0,last=ni-2,all=0;
    for(int kk=start[k];kk<ni-1;kk++) {
        total+=count[k*ni+kk];
        if(total==nc) {last=kk;all=1;break;}
    }
    stop[2*k]=last;stop[2*k+1]=all;
}
extern "C" __global__ void fixed_pressure_apply(
    int nc,int ni,int no,int k,const float* p,const float* f,const float* po,
    float* out,int* upper,int* start,const int* stop) {
    int c=blockIdx.x*blockDim.x+threadIdx.x;if(c>=nc)return;
    float q=po[c*no+k];int u=upper[c];
    int last=stop[2*k],all=stop[2*k+1];
    for(int kk=start[k];kk<=last;kk++)
        if(q>p[c*ni+kk] && q<=p[c*ni+kk+1]) u=kk;
    upper[c]=u;
    if(!all && q<p[c*ni]) out[c*no+k]=D(M(f[c*ni],q),p[c*ni]);
    else if(!all && q>p[c*ni+ni-1]) out[c*no+k]=f[c*ni+ni-1];
    else {
        float dpu=S(q,p[c*ni+u]),dpl=S(p[c*ni+u+1],q);
        out[c*no+k]=D(A(M(f[c*ni+u],dpl),M(f[c*ni+u+1],dpu)),A(dpl,dpu));
    }
    atomicMin(&start[k+1],u);
}

// mpas_isobaric_diagnostics.F:1245-1351.
extern "C" __global__ void layer_mean(
    int nc,int nl,float p1,float p2,const float* f,const float* p,float* out) {
    int c=blockIdx.x*blockDim.x+threadIdx.x;if(c>=nc)return;
    if(p[0]>p[nl-1]) {out[c]=0.f;return;}
    float pt=p1<p2?p1:p2,pb=p1<p2?p2:p1;
    int kt=-1,kb=-1;
    float wtp=0,wtm=0,wbp=0,wbm=0;
    const float* pc=p+c*nl; const float* fc=f+c*nl;
    for(int k=0;k<nl-1;k++) {
        if(pc[k]<=pt && pc[k+1]>pt) {
            kt=k;wtp=D(S(pt,pc[k]),S(pc[k+1],pc[k]));
            wtm=D(S(pc[k+1],pt),S(pc[k+1],pc[k]));
        }
        if(pc[k]<=pb && pc[k+1]>pb) {
            kb=k;wbm=D(S(pb,pc[k]),S(pc[k+1],pc[k]));
            wbp=D(S(pc[k+1],pb),S(pc[k+1],pc[k]));
        }
    }
    if(kt==-1 || kb==-1) {out[c]=0;return;}
    float x=A(M(wtm,fc[kt]),M(wtp,fc[kt+1]));
    if(kt==kb) {
        x=A(A(x,M(wbm,fc[kb])),M(wbp,fc[kb+1]));
        out[c]=M(.5f,x);return;
    }
    float total=S(pc[kt+1],pt);
    x=M(M(total,.5f),A(fc[kt+1],x));
    for(int k=kt+1;k<kb;k++) {
        float w=S(pc[k+1],pc[k]); total=A(total,w);
        x=A(x,M(M(w,.5f),A(fc[k],fc[k+1])));
    }
    float w=S(pb,pc[kb]); total=A(total,w);
    float temp=A(M(wbm,fc[kb]),M(wbp,fc[kb+1]));
    x=A(x,M(M(w,.5f),A(fc[kb],temp)));
    out[c]=D(x,total);
}

// mpas_isobaric_diagnostics.F:1094-1227. Inputs are column-major C arrays
// (column,level); p is hPa. A failed column marks the entire output invalid.
extern "C" __global__ void slp_columns(
    int nc,int nl,const float* p,const float* temp,const float* h,
    const float* q,float* out,int* failed) {
    int c=blockIdx.x*blockDim.x+threadIdx.x;if(c>=nc)return;
    const float* pc=p+c*nl;const float* tc=temp+c*nl;
    const float* hc=h+c*(nl+1);const float* qc=q+c*nl;
    int level=-1;
    for(int k=0;k<nl;k++)if(pc[k]<S(pc[0],100.f)){level=k;break;}
    if(level==-1){atomicExch(failed,1);return;}
    int lo=max(level-1,0),hi=min(lo+1,nl-2);
    if(lo==hi){atomicExch(failed,1);return;}
    float plo=pc[lo],phi=pc[hi];
    float tlo=M(tc[lo],A(1.f,M(.608f,qc[lo])));
    float thi=M(tc[hi],A(1.f,M(.608f,qc[hi])));
    float zlo=M(.5f,A(hc[lo],hc[lo+1]));
    float zhi=M(.5f,A(hc[hi],hc[hi+1]));
    float pp=S(pc[0],100.f);
    float lp=gfk_log(D(pp,phi)),ll=gfk_log(D(plo,phi));
    float tp=S(thi,M(M(S(thi,tlo),lp),ll));
    float zp=S(zhi,M(M(S(zhi,zlo),lp),ll));
    float ts=M(tp,gfk_pow(D(pc[0],pp),D(M(.0065f,287.f),9.80616f)));
    float tm=A(tp,M(.0065f,zp));
    const float limit=290.66f;
    if(ts<=limit && tm>=limit) tm=limit;
    else {float delta=S(ts,limit);tm=S(limit,M(.005f,M(delta,delta)));}
    float zhalf=M(.5f,A(hc[0],hc[1]));
    out[c]=M(pc[0],gfk_exp_fma(D(M(19.61232f,zhalf),M(287.f,A(tm,ts)))));
}

extern "C" __global__ void slp_finish(int nc,float* out,const int* failed,float scale) {
    int c=blockIdx.x*blockDim.x+threadIdx.x;
    if(c<nc)out[c]=*failed?0.f:M(out[c],scale);
}

