                                  +(R(0.5f)*(R(vc[k])+R(vc[k-1]))-vstorm)*R(dudz[k])).v;
        srh[0]=(-(R(uc[0])-ustorm)*R(dvdz[0])+(R(vc[0])-vstorm)*R(dudz[0])).v;
