__device__ R mean_pressure(const float* values,const float* p,R bot,R top,int n) {
    R result=0.0f;int count=0;
    for(int k=0;k<n;k++) if(R(p[k])<=bot&&R(p[k])>=top) {result+=values[k];count++;}
