            sea[IDX_xland*n+i]=2.0f;
            F(xland)=1.0f;
            sea[IDX_mavail*n+i]=1.0f;
            sea[IDX_znt*n+i]=0.0001f;
            sea[IDX_tsk*n+i]=fmaxf(sst[i],271.4f);
        }
    }
