    F(albedo)=si_div(si_sub(F(albedo),si_mul(0.08f,si_sub(1.0f,F(xice)))),F(xice));
    F(emiss)=si_div(si_sub(F(emiss),si_mul(0.98f,si_sub(1.0f,F(xice)))),F(xice));
    F(tsk_sea)=fmaxf(F(tsk_sea),271.4f);
