extern "C" __global__ void rrfs_init_directions(
    const int cells, const int extent, const float *lat, const float *lon,
    float *east, float *north) {
    int c=blockDim.x*blockIdx.x+threadIdx.x;
    if(c>=cells) return;
    float slon=glibc_sinf(lon[c]),clon=glibc_cosf(lon[c]);
    float slat=glibc_sinf(lat[c]),clat=glibc_cosf(lat[c]);
    float ax=-slon,ay=clon,az=0.f;
    float mi=__fdiv_rn(1.f,__fsqrt_rn(__fadd_rn(
        __fadd_rn(__fmul_rn(ax,ax),__fmul_rn(ay,ay)),__fmul_rn(az,az))));
    east[c]=__fmul_rn(ax,mi);
    east[extent+c]=__fmul_rn(ay,mi);
    east[2*extent+c]=__fmul_rn(az,mi);
    ax=__fmul_rn(-clon,slat);ay=__fmul_rn(-slon,slat);az=clat;
    mi=__fdiv_rn(1.f,__fsqrt_rn(__fadd_rn(
        __fadd_rn(__fmul_rn(ax,ax),__fmul_rn(ay,ay)),__fmul_rn(az,az))));
    north[c]=__fmul_rn(ax,mi);
    north[extent+c]=__fmul_rn(ay,mi);
    north[2*extent+c]=__fmul_rn(az,mi);
}
extern "C" __global__ void rrfs_init_ocean_temperature(
    const int cells,const float *sst,float *deep) {
    int c=blockDim.x*blockIdx.x+threadIdx.x;
    if(c<cells) deep[c]=__fsub_rn(sst[c],5.f);
}

extern "C" {
// mpas_atmphys_interface.F:357-425. Input words are the existing max(+0,q)
// preparation outputs; select-case order and MYNN's zeroing are preserved.
__global__ void prep_numbers_v842_u32(
    int nlev, int ncells, int solved, int aerosol, int mynn, int ice, int trio,
    const unsigned int *nc, const unsigned int *ni,
    const unsigned int *nifa, const unsigned int *nwfa,
    unsigned int *out_nc, unsigned int *out_ni,
    unsigned int *out_nifa, unsigned int *out_nwfa)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= solved) return;
    for (int k=0; k<nlev; ++k) {
        const int i=k*ncells+cell;
        if (aerosol) { out_nifa[i]=nifa[i]; out_nwfa[i]=nwfa[i]; }
        if (mynn) {
            out_nc[i]=0u; out_ni[i]=0u; out_nifa[i]=0u; out_nwfa[i]=0u;
            if (ice) out_ni[i]=ni[i];
            if (trio) { out_nc[i]=nc[i]; out_nifa[i]=nifa[i]; out_nwfa[i]=nwfa[i]; }
        }
    }
}
}

