extern "C" __global__ void split_helicity(int nc,int nl,const float* w,
    const float* area,float* positive,float* negative) {
    int c=blockDim.x*blockIdx.x+threadIdx.x;
    if(c>nc) return;
    for(int k=0;k<nl;k++) {
        R h=positive[c*nl+k];
        if(c<nc) {
