#define GFK_TG_PI   0x1.921fb54442d18p+1
#define GFK_TG_QNAN __uint_as_float(0x7fc00000u)

// Gamma(r) for r in [1,2).  All arithmetic pinned to binary64 add/mul; the
// two subtractions below are exact (Sterbenz), so j and u are exact.
__device__ double gfk_tgamma_poly(double r)
{
    double t = DMUL(DSUB(r, 1.0), 16.0);                 /* [0,16), exact */
    int j = (int)t;
    if (j > 15) j = 15;                                  /* r = nextbelow(2) */
    double u = DSUB(r, DMUL((double)(33 + 2 * j), 0.03125));   /* exact */
    const double *c = GFK_TG_C[j];
    double p = c[9];
    p = DADD(DMUL(p, u), c[8]);
    p = DADD(DMUL(p, u), c[7]);
    p = DADD(DMUL(p, u), c[6]);
    p = DADD(DMUL(p, u), c[5]);
    p = DADD(DMUL(p, u), c[4]);
    p = DADD(DMUL(p, u), c[3]);
    p = DADD(DMUL(p, u), c[2]);
    p = DADD(DMUL(p, u), c[1]);
    p = DADD(DMUL(p, u), c[0]);
    return p;
}

// Gamma(v) in binary64 for 0 < v < 43 (the caller's x < 36 guard bounds the
// reflected argument 1-x below 43, so the recurrence runs at most 41 times).
__device__ double gfk_tgamma_pos(double v)
{
    if (v >= 1.0) {
        int n = (int)v;                                  /* 1 .. 42 */
        double r = DSUB(v, (double)(n - 1));             /* [1,2), exact */
        double p = gfk_tgamma_poly(r);
        for (int i = 1; i < n; i++)
            p = DMUL(p, DSUB(v, (double)i));
        return p;
    }
    return DDIV(gfk_tgamma_poly(DADD(v, 1.0)), v);       /* Gamma(v)=Gamma(v+1)/v */
}

// sin(pi*x) for |x| < 2^23.  k and the subtraction are exact.
__device__ double gfk_tgamma_sinpi(double x)
{
    long long k = (long long)(x < 0.0 ? DSUB(x, 0.5) : DADD(x, 0.5));
    double r  = DSUB(x, (double)k);                      /* [-1/2,1/2], exact */
    double r2 = DMUL(r, r);
    double s  = GFK_TG_SP[12];
    for (int i = 11; i >= 0; i--) s = DADD(DMUL(s, r2), GFK_TG_SP[i]);
    s = DMUL(s, r);
    return (k & 1) ? -s : s;
}

// The correctly-rounded float32 gamma.
//
// The 36.0f overflow guard is arithmetic, not inherited: MEASURED, the last
// float32 with a finite Gamma is 35.0401001, and binary64 holds Gamma out to
// x = 171.6, so ANY threshold in [35.041, 171] gives the same float32 answer
// on every argument.  36 is taken as the smallest integer above the overflow
// point, which is also what bounds the recurrence trip count above at 42.
// glibc picks the same number for the same arithmetic reason; the choice is
// free within a 136-wide interval and carries no expression.
__device__ float gfk_tgamma(float x)
{
    unsigned int ix = __float_as_uint(x);
    unsigned int ax = ix & 0x7fffffffu;

    if (ax >= 0x7f800000u) {                    /* inf / nan */
        if (ix == 0xff800000u) return GFK_TG_QNAN;      /* -inf  -> qNaN */
        return FADD(x, x);                              /* +inf  -> +inf
                                                           NaN   -> same, quieted */
    }
    if (ix < 0x80000000u) {                     /* x >= +0 */
        if (ix == 0u) return FDIV(1.0f, x);             /* +0 -> +inf */
        if (x >= 36.0f)
            return FMUL(FMUL(x, 0x1p127f), 0x1p127f);   /* -> +inf */
        return gfk_d2f_rn(gfk_tgamma_pos((double)x));
    }
    /* x < 0: reflection  Gamma(x) = pi / (sin(pi x) * Gamma(1-x)) */
    if (ix == 0x80000000u) return FDIV(1.0f, x);        /* -0 -> -inf */
    if (ax >= 0x4b000000u) return GFK_TG_QNAN;          /* |x| >= 2^23: every
                                                           float is an integer,
                                                           so every one is a pole */
    {
        double s = gfk_tgamma_sinpi((double)x);
        if (s == 0.0) return GFK_TG_QNAN;               /* negative integer: pole */
        if (x <= -42.0f)                                /* |Gamma| < 2^-150 below
                                                           here; measured, the
                                                           last non-zero float32
                                                           result is at -41.000042 */
            return (s < 0.0) ? -0.0f : 0.0f;
        {
            double g1 = gfk_tgamma_pos(DSUB(1.0, (double)x));   /* 1-x in (1,43) */
            return gfk_d2f_rn(DDIV(GFK_TG_PI, DMUL(s, g1)));
        }
    }
}

// Sub-grid terrain drag from WRF v4.7.1: the topo_wind static coefficients
// and the two orographic drag schemes gwd_opt = 1 and gwd_opt = 3.
//
//   topo_wind_static  dyn_em/start_em.F:1539-1626.  LAP_HGT from the terrain
//                     and CTOPO / CTOPO2 for topo_wind = 1 (Jimenez and
//                     Dudhia 2012: drag scaled by ln of the sub-grid terrain
//                     deviation, tapered to zero on hill tops) and
//                     topo_wind = 2 (drag scaled by (VAR*0.4/200+1.175)^2,
//                     capped at 1.575^2).  YSU reads them (kernels/ysu.cu).
//   gwdo_column       gwd_opt = 1: phys/module_bl_gwdo.F (gwdo) calling
//                     phys/physics_mmm/bl_gwdo.F90 (bl_gwdo_run), the KIM
//                     orographic gravity-wave drag with flow blocking
//                     (Choi and Hong 2015).
//   gwdo_gsl_column   gwd_opt = 3: phys/module_bl_gwdo_gsl.F, the GSL drag
//                     suite: large-scale gravity-wave drag and flow
//                     blocking (tapered off between 13 and 3 km), small-scale
//                     gravity-wave drag (Steeneveld et al. 2008) and
//                     turbulent orographic form drag (Beljaars et al. 2004),
//                     both tapered off between 12 and 1 km.
//
// Every statement follows WRF's own, in WRF's order of evaluation; the module
// is compiled with -fmad=false so no product is fused into a sum, as gfortran
// fuses none.  Fortran's real powers (x**2., x**(-1.2), ...) are glibc's
// powf (gfk_pow; gfortran calls powf for a real exponent even when it is
// 2.0), integer powers are products, expf and logf are glibc's (gfk_exp,
// gfk_log), sinf is glibc's (glibc_sinf).  atan2f is td_atan2f below, WOOF's
// own float32 atan2f, whose words are the reference platform's (Ubuntu 24.04,
// glibc 2.39, box W1): see its comment.  The oracles that hold these kernels
// to WRF are tools/terrain_drag_wrf471_oracle
// (tests/test_terrain_drag_wrf471_parity.py) and, for gwd_opt = 1 on the
// reference platform, tools/gwdo_kim_wrf461_oracle
// (tests/test_gwdo_kim_wrf461_parity.py).
//
// Layout: 3-D fields are (nz, ny, nx) mass levels (p_interface nz+1), 2-D
// fields (ny, nx); the four directional statistics OA1-4 and OL1-4 are
// (4, ny, nx).  One thread owns one column.

#define TD_KMAX 128

__device__ __forceinline__ float td_max(float a, float b)
{ return fmaxf(a, b); }
__device__ __forceinline__ float td_min(float a, float b)
{ return fminf(a, b); }

// atan2f for the wind-sector choice, bl_gwdo.F90:338 and
// module_bl_gwdo_gsl.F's `wdir = atan2(ubar,vbar) + pi`: the angle only picks
// one of eight sectors (which OA/OL statistic and grid length the drag uses),
// so its last bit matters only on a sector boundary, and there it decides
// the whole column.
//
// WHY NOT atan2() IN DOUBLE.  Until lane/verify-gwdo-kim this read
// __double2float_rn(atan2((double)y, (double)x)), the correctly rounded
// angle, which is what glibc 2.43 returns (the WRF v4.7.1 oracle's
// platform).  The reference platform of this verification (Ubuntu 24.04,
// glibc 2.39; the MYNN, YSU and Kessler oracles' platform) returns the
// classic atanf-based atan2f instead, 1 ULP off the correctly rounded angle
// on 16% of random wind pairs (measured on box W1), and on a sector
// boundary that 1 ULP picks the other sector: in the WRF v4.6.1 column
// oracle (tests/data/oracles/gwdo_kim) one sector-boundary column per grid
// took idir 1 under WRF and 8 under the double atan2 (50 levels), 5 and 4
// (90 levels), and every drag word of those columns differed (up to
// 0.41 m/s2).
//
// td_atanf and td_atan2f are WOOF's own float32 code: td_atanf is the same
// algorithm and the same words as the MYNN unit's mynn_glibc_atanf
// (kernels/mynn_pbl.cu), and td_atan2f reduces to it through one IEEE
// division y/x and a quadrant fix-up with float32 pi constants.  They are
// held to the reference platform's atanf over EVERY float32 and to its
// atan2f on boundary, special and random pairs by
// tools/gwdo_kim_wrf461_oracle/sector_sweep.py.  Every operation is one
// plain float32 operation; the module compiles with -fmad=false.
__constant__ unsigned int TD_ATANF_TAB[19] = {
    0x3EED6338u, 0x3F490FDAu, 0x3F7B985Eu, 0x3FC90FDAu,   // atan hi parts
    0x31AC3769u, 0x33222168u, 0x33140FB4u, 0x33A22168u,   // atan lo parts
    0x3EAAAAABu, 0xBE4CCCCDu, 0x3E124925u, 0xBDE38E38u,   // odd series
    0x3DBA2E6Eu, 0xBD9D8795u, 0x3D886B35u, 0xBD6EF16Bu,
    0x3D4BDA59u, 0xBD15A221u, 0x3C8569D7u,
};

__device__ float td_atanf(float x)
{
    unsigned int hx = __float_as_uint(x);
    unsigned int ix = hx & 0x7FFFFFFFu;
    int signed_hx = (int)hx;
    int id;
#define TD_ATAN_HI(i) __uint_as_float(TD_ATANF_TAB[(i)])
#define TD_ATAN_LO(i) __uint_as_float(TD_ATANF_TAB[4 + (i)])
#define TD_ATAN_T(i)  __uint_as_float(TD_ATANF_TAB[8 + (i)])
    if (ix >= 0x4C000000u) {                     // |x| >= 2**25
        if (ix > 0x7F800000u) return x + x;      // NaN
        if (signed_hx > 0) return TD_ATAN_HI(3) + TD_ATAN_LO(3);
        return -TD_ATAN_HI(3) - TD_ATAN_LO(3);
    }
    if (ix < 0x3EE00000u) {                      // |x| < 0.4375
        if (ix < 0x31000000u) return x;          // |x| < 2**-29
        id = -1;
    } else {
        x = __uint_as_float(ix);                 // |x|
        if (ix < 0x3F980000u) {                  // |x| < 1.1875
            if (ix < 0x3F300000u) {              // 7/16 <= |x| < 11/16
                id = 0;
                x = (2.0f * x - 1.0f) / (2.0f + x);
            } else {                             // 11/16 <= |x| < 19/16
                id = 1;
                x = (x - 1.0f) / (x + 1.0f);
            }
        } else if (ix < 0x401C0000u) {           // |x| < 2.4375
            id = 2;
            x = (x - 1.5f) / (1.0f + 1.5f * x);
        } else {                                 // 2.4375 <= |x| < 2**25
            id = 3;
            x = -1.0f / x;
        }
    }
    float z = x * x;
    float w = z * z;
    float s1 = w * TD_ATAN_T(10);
    s1 = w * (TD_ATAN_T(8) + s1);
    s1 = w * (TD_ATAN_T(6) + s1);
    s1 = w * (TD_ATAN_T(4) + s1);
    s1 = w * (TD_ATAN_T(2) + s1);
    s1 = z * (TD_ATAN_T(0) + s1);
    float s2 = w * TD_ATAN_T(9);
    s2 = w * (TD_ATAN_T(7) + s2);
    s2 = w * (TD_ATAN_T(5) + s2);
    s2 = w * (TD_ATAN_T(3) + s2);
    s2 = w * (TD_ATAN_T(1) + s2);
    float s = s1 + s2;
    if (id < 0) return x - x * s;
    float r = TD_ATAN_HI(id) - ((x * s - TD_ATAN_LO(id)) - x);
    return (signed_hx < 0) ? -r : r;
#undef TD_ATAN_HI
#undef TD_ATAN_LO
#undef TD_ATAN_T
}

__device__ float td_atan2f(float y, float x)
{
    const float tiny = 1.0e-30f;
    const float pi_o_4 = __uint_as_float(0x3F490FDBu);
    const float pi_o_2 = __uint_as_float(0x3FC90FDBu);
    const float pi = __uint_as_float(0x40490FDBu);
    const float pi_lo = __uint_as_float(0xB3BBBD2Eu);   // pi - float(pi)
    int hx = __float_as_int(x), hy = __float_as_int(y);
    int ix = hx & 0x7FFFFFFF, iy = hy & 0x7FFFFFFF;
    if (ix > 0x7F800000 || iy > 0x7F800000) return x + y;   // NaN
    if (hx == 0x3F800000) return td_atanf(y);               // x = 1
    int m = ((hy >> 31) & 1) | ((hx >> 30) & 2);            // 2*sign(x)+sign(y)
    if (iy == 0) {                                          // y = +-0
        if (m <= 1) return y;
        return (m == 2) ? pi + tiny : -pi - tiny;
    }
    if (ix == 0) return (hy < 0) ? -pi_o_2 - tiny : pi_o_2 + tiny;
    if (ix == 0x7F800000) {                                 // x = +-Inf
        if (iy == 0x7F800000) {
            switch (m) {
            case 0: return pi_o_4 + tiny;
            case 1: return -pi_o_4 - tiny;
            case 2: return 3.0f * pi_o_4 + tiny;
            default: return -3.0f * pi_o_4 - tiny;
            }
        }
        switch (m) {
        case 0: return 0.0f;
        case 1: return -0.0f;
        case 2: return pi + tiny;
        default: return -pi - tiny;
        }
    }
    if (iy == 0x7F800000) return (hy < 0) ? -pi_o_2 - tiny : pi_o_2 + tiny;
    int k = (iy - ix) >> 23;
    float z;
    if (k > 60) z = pi_o_2 + 0.5f * pi_lo;                  // |y/x| > 2**60
    else if (hx < 0 && k < -60) z = 0.0f;                   // |y|/x < -2**60
    else z = td_atanf(fabsf(y / x));
    switch (m) {
    case 0: return z;
    case 1: return -z;
    case 2: return pi - (z - pi_lo);
    default: return (z - pi_lo) - pi;
    }
}

// Fortran NINT: round half away from zero.
__device__ __forceinline__ int td_nint(float x) { return (int)roundf(x); }



#ifndef MPAS_FTZ_FALLBACK_ENABLED
#define MPAS_FTZ_FALLBACK_ENABLED 1
#endif

__device__ __forceinline__ unsigned int mpas_f32_magnitude_bits(
    const float value)
{
    return __float_as_uint(value) & 0x7fffffffu;
}

__device__ __forceinline__ bool mpas_is_subnormal_f32(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int magnitude = mpas_f32_magnitude_bits(value);
    return magnitude != 0u && (magnitude & 0x7f800000u) == 0u;
#else
    return false;
#endif
}

// A plain float/double cast is one of the measured DAZ mechanisms, so decode
// a subnormal float from its integer mantissa instead.
__device__ __forceinline__ double mpas_f32_to_f64_ieee(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int bits = __float_as_uint(value);
    const unsigned int magnitude = bits & 0x7fffffffu;
    if (magnitude != 0u && (magnitude & 0x7f800000u) == 0u) {
        const double decoded = ldexp(
            (double)(magnitude & 0x007fffffu), -149);
        return (bits & 0x80000000u) != 0u ? -decoded : decoded;
    }
#endif
    return (double)value;
}

// __double2float_rn flushes an FP32-subnormal result on the certified route,
// so pack that narrow result from the rounded integer mantissa.
__device__ __forceinline__ float mpas_f64_to_f32_ieee(const double value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const double magnitude = fabs(value);
    if (magnitude > 0.0 && magnitude < 1.1754943508222875e-38) {
        const double scaled = rint(
            magnitude * 7.1362384635297994e+44);  // 2^149
        const unsigned int mantissa = (unsigned int)scaled;
        const unsigned int sign =
            (__double_as_longlong(value) < 0LL) ? 0x80000000u : 0u;
        return __uint_as_float(sign | mantissa);
    }
#endif
    return __double2float_rn(value);
}

__device__ __forceinline__ float mpas_add(
    const float left, const float right)
{
    const float ordinary = __fadd_rn(left, right);
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int result_magnitude = mpas_f32_magnitude_bits(ordinary);
    const unsigned int result_exponent = result_magnitude >> 23;
    // A result at exponent field >=25 cannot have been rounded differently
    // by an FP32 subnormal operand, which is then below half an ulp.
    if (result_exponent > 24u) return ordinary;
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) + mpas_f32_to_f64_ieee(right));
    }
#endif
#if MPAS_FTZ_FALLBACK_ENABLED
    // Two normal binary32 values can cancel into the subnormal range only
    // while both exponent fields are <= 23; above that, one ulp is already
    // at least the smallest normal value.
    if (left_exponent <= 23u && right_exponent <= 23u
            && result_exponent == 0u
            && left_magnitude != right_magnitude
            && left_magnitude != 0u && right_magnitude != 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) + mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_sub(
    const float left, const float right)
{
    const float ordinary = __fsub_rn(left, right);
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int result_magnitude = mpas_f32_magnitude_bits(ordinary);
    const unsigned int result_exponent = result_magnitude >> 23;
    if (result_exponent > 24u) return ordinary;
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) - mpas_f32_to_f64_ieee(right));
    }
#endif
#if MPAS_FTZ_FALLBACK_ENABLED
    if (left_exponent <= 23u && right_exponent <= 23u
            && result_exponent == 0u
            && left_magnitude != right_magnitude
            && left_magnitude != 0u && right_magnitude != 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) - mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_mul(
    const float left, const float right)
{
    const float ordinary = __fmul_rn(left, right);
#if MPAS_FTZ_FALLBACK_ENABLED
    // A normal finite/overflow result proves neither operand was lost to DAZ
    // and no FTZ result occurred.  Inspect operands only on the rare zero or
    // subnormal-result envelope.
    if ((mpas_f32_magnitude_bits(ordinary) & 0x7f800000u) == 0u) {
        const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
        const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
        if (left_magnitude != 0u && right_magnitude != 0u) {
            return mpas_f64_to_f32_ieee(
                mpas_f32_to_f64_ieee(left) * mpas_f32_to_f64_ieee(right));
        }
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_div(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    const unsigned int left_magnitude = mpas_f32_magnitude_bits(left);
    const unsigned int right_magnitude = mpas_f32_magnitude_bits(right);
    const unsigned int left_exponent = left_magnitude >> 23;
    const unsigned int right_exponent = right_magnitude >> 23;
    if ((left_exponent == 0u && left_magnitude != 0u)
            || (right_exponent == 0u && right_magnitude != 0u)) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) / mpas_f32_to_f64_ieee(right));
    }
#endif
    const float ordinary = __fdiv_rn(left, right);
#if MPAS_FTZ_FALLBACK_ENABLED
    if (left_magnitude != 0u && right_magnitude != 0u
            && left_exponent + 126u <= right_exponent
            && (mpas_f32_magnitude_bits(ordinary) & 0x7f800000u) == 0u) {
        return mpas_f64_to_f32_ieee(
            mpas_f32_to_f64_ieee(left) / mpas_f32_to_f64_ieee(right));
    }
#endif
    return ordinary;
}

__device__ __forceinline__ float mpas_sqrt(const float value)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(value)) {
        return mpas_f64_to_f32_ieee(sqrt(mpas_f32_to_f64_ieee(value)));
    }
#endif
    return __fsqrt_rn(value);
}

__device__ __forceinline__ float mpas_abs(const float value)
{
    return __uint_as_float(__float_as_uint(value) & 0x7fffffffu);
}

__device__ __forceinline__ float mpas_copysign(
    const float magnitude, const float sign)
{
    return __uint_as_float(
        (__float_as_uint(magnitude) & 0x7fffffffu)
        | (__float_as_uint(sign) & 0x80000000u));
}

__device__ __forceinline__ float mpas_min(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(left) || mpas_is_subnormal_f32(right)) {
        return mpas_f32_to_f64_ieee(right) < mpas_f32_to_f64_ieee(left)
            ? right : left;
    }
#endif
    return fminf(left, right);
}

__device__ __forceinline__ float mpas_max(
    const float left, const float right)
{
#if MPAS_FTZ_FALLBACK_ENABLED
    if (mpas_is_subnormal_f32(left) || mpas_is_subnormal_f32(right)) {
        return mpas_f32_to_f64_ieee(right) > mpas_f32_to_f64_ieee(left)
            ? right : left;
    }
#endif
    return fmaxf(left, right);
}


#define GWDO_NLEV 55

// MPAS physics_mmm/bl_gwdo.F90:55-643; mpas_atmphys_driver_gwdo.F:761-781.
extern "C" __global__ void bl_ysu_gwdo_v842_f32(
    const int nlev, const int ncells, const float dt,
    const float len_disp, const float gravity, const float cp,
    const float rd, const float fv, const float pi,
    const float *u, const float *v, const float *temperature,
    const float *qv, const float *p_mass_dry_hyd,
    const float *p_interface_dry_hyd, const float *exner,
    const float *zmid, const float *rublten_in,
    const float *rvblten_in, const float *mesh_density,
    const float *var2d, const float *oc1, const float *oa1,
    const float *oa2, const float *oa3, const float *oa4,
    const float *ol1, const float *ol2, const float *ol3,
    const float *ol4, float *rublten_out, float *rvblten_out,
    float *dtaux3d, float *dtauy3d, float *dusfcg,
    float *dvsfcg, float *rubldiff, float *rvbldiff,
    int *invalid)
{
    const int cell = blockDim.x * blockIdx.x + threadIdx.x;
    if (cell >= ncells) return;
    if (nlev != GWDO_NLEV) {
        atomicExch(invalid, 1);
        return;
    }

    // Native bl_gwdo.F90:218-643 performs these operations without a
    // humidity/geometry/finite-value gate. Preserve its arithmetic even for
    // values that produce nonfinite outputs; do not invent a forecast abort.
    const float md = mesh_density[cell];
    const float oa_input[4] = {oa1[cell], oa2[cell], oa3[cell], oa4[cell]};
    const float ol_input[4] = {ol1[cell], ol2[cell], ol3[cell], ol4[cell]};

    float vtj[GWDO_NLEV];
    float vtk[GWDO_NLEV];
    float rho[GWDO_NLEV];
    float delta_p[GWDO_NLEV];
    float u1[GWDO_NLEV];
    float v1[GWDO_NLEV];
    float usqj[GWDO_NLEV];
    float bnv2[GWDO_NLEV];
    float velco[GWDO_NLEV - 1];
    float taup[GWDO_NLEV + 1];
    float taufb[GWDO_NLEV + 1];
    float taud[GWDO_NLEV];
    for (int k = 0; k < nlev; ++k) {
        usqj[k] = 0.0f;
        bnv2[k] = 0.0f;
        taud[k] = 0.0f;
    }
    for (int k = 0; k <= nlev; ++k) {
        taup[k] = 0.0f;
        taufb[k] = 0.0f;
    }

    const float dx = mpas_div(len_disp, gfk_pow(md, 0.25f));
    const float diagonal = mpas_sqrt(
        mpas_add(mpas_mul(dx, dx), mpas_mul(dx, dx)));
    const float dxy4[4] = {dx, dx, diagonal, diagonal};
    const float dxy4p[4] = {dx, dx, diagonal, diagonal};
    for (int k = 0; k < nlev; ++k) {
        const int i = k * ncells + cell;
        const int ip = (k + 1) * ncells + cell;
        const float virtual_factor = mpas_add(1.0f, mpas_mul(fv, qv[i]));
        vtj[k] = mpas_mul(temperature[i], virtual_factor);
        vtk[k] = mpas_div(vtj[k], exner[i]);
        rho[k] = mpas_div(
            mpas_mul(mpas_div(1.0f, rd), p_mass_dry_hyd[i]), vtj[k]);
        delta_p[k] = mpas_sub(
            p_interface_dry_hyd[i], p_interface_dry_hyd[ip]);
        u1[k] = mpas_sub(mpas_mul(u[i], 1.0f), mpas_mul(v[i], 0.0f));
        v1[k] = mpas_add(mpas_mul(u[i], 0.0f), mpas_mul(v[i], 1.0f));
    }

    const float zlowtop = mpas_mul(2.0f, var2d[cell]);
    int klowtop = 0;
    for (int k = 1; k < nlev; ++k) {
        const float height = mpas_sub(
            zmid[k * ncells + cell], zmid[cell]);
        if (zlowtop > 0.0f && klowtop == 0 && height >= zlowtop)
            klowtop = k + 2;
    }
    int kbl = klowtop;
    if (kbl > nlev) kbl = nlev;
    if (kbl < 2) kbl = 2;
    const float delks = mpas_div(
        1.0f, mpas_sub(p_interface_dry_hyd[cell],
            p_interface_dry_hyd[(kbl - 1) * ncells + cell]));
    const float delks1 = mpas_div(
        1.0f, mpas_sub(p_mass_dry_hyd[cell],
            p_mass_dry_hyd[(kbl - 1) * ncells + cell]));
    float ubar = 0.0f;
    float vbar = 0.0f;
    float rhobar = 0.0f;
    for (int k = 0; k < nlev; ++k) {
        if (k + 1 < kbl) {
            const float weight = mpas_mul(delta_p[k], delks);
            ubar = mpas_add(ubar, mpas_mul(weight, u1[k]));
            vbar = mpas_add(vbar, mpas_mul(weight, v1[k]));
            rhobar = mpas_add(rhobar, mpas_mul(weight, rho[k]));
        }
    }

    const int nwdir[8] = {6, 7, 5, 8, 2, 3, 1, 4};
    const float fdir = mpas_div(8.0f, mpas_mul(2.0f, pi));
    const float wdir = mpas_add(td_atan2f(ubar, vbar), pi);
    const int nearest = td_nint(mpas_mul(fdir, wdir));
    const int nwd = nwdir[nearest % 8];
    const int direction = (nwd - 1) % 4;
    const int sign = 1 - 2 * ((nwd - 1) / 4);
    const float oa = mpas_mul((float)sign, oa_input[direction]);
    const float ol = ol_input[direction];
    const float ol_perp[4] = {
        ol_input[1], ol_input[0], ol_input[3], ol_input[2]};
    const float olp = ol_perp[direction];
    float od = mpas_div(olp, mpas_max(ol, 1.0e-5f));
    od = mpas_max(mpas_min(od, 10.0f), 0.1f);
    const float dxy = dxy4[direction];
    const float dxyp = dxy4p[direction];

    for (int k = 0; k < nlev - 1; ++k) {
        const int i = k * ncells + cell;
        const int ia = i + ncells;
        const float ti = mpas_div(
            2.0f, mpas_add(temperature[i], temperature[ia]));
        const float rdz = mpas_div(1.0f, mpas_sub(zmid[ia], zmid[i]));
        const float du = mpas_sub(u1[k], u1[k + 1]);
        const float dv = mpas_sub(v1[k], v1[k + 1]);
        const float dw2 = mpas_add(mpas_mul(du, du), mpas_mul(dv, dv));
        const float shr2 = mpas_mul(
            mpas_mul(mpas_max(dw2, 1.0f), rdz), rdz);
        const float stability = mpas_add(
            mpas_div(gravity, cp), mpas_mul(rdz, mpas_sub(vtj[k + 1], vtj[k])));
        const float bvf2 = mpas_mul(mpas_mul(gravity, stability), ti);
        usqj[k] = mpas_max(mpas_div(bvf2, shr2), -100.0f);
        bnv2[k] = mpas_div(
            mpas_mul(mpas_mul(mpas_mul(2.0f, gravity), rdz),
                mpas_sub(vtk[k + 1], vtk[k])),
            mpas_add(vtk[k + 1], vtk[k]));
    }

    float ulow = mpas_sqrt(mpas_add(mpas_mul(ubar, ubar), mpas_mul(vbar, vbar)));
    ulow = mpas_max(ulow, 1.0f);
    const float rulow = mpas_div(1.0f, ulow);
    for (int k = 0; k < nlev - 1; ++k) {
        float aligned = mpas_add(
            mpas_mul(mpas_add(u1[k], u1[k + 1]), ubar),
            mpas_mul(mpas_add(v1[k], v1[k + 1]), vbar));
        velco[k] = mpas_mul(mpas_mul(0.5f, aligned), rulow);
        if (velco[k] < 1.0f && velco[k] > 0.0f) velco[k] = 1.0f;
    }
    bool ldrag = velco[0] <= 0.0f;
    for (int kf = 2; kf <= nlev; ++kf) {
        if (kf < kbl && velco[kf - 1] <= 0.0f) ldrag = true;
    }

    const float first_weight = mpas_mul(
        mpas_sub(p_mass_dry_hyd[cell], p_mass_dry_hyd[ncells + cell]),
        delks1);
    bnv2[0] = mpas_mul(first_weight, bnv2[0]);
    usqj[0] = mpas_mul(first_weight, usqj[0]);
    for (int kf = 2; kf <= nlev; ++kf) {
        if (kf < kbl) {
            const int k = kf - 1;
            const float pressure_weight = mpas_mul(
                mpas_sub(p_mass_dry_hyd[k * ncells + cell],
                    p_mass_dry_hyd[(k + 1) * ncells + cell]), delks1);
            bnv2[0] = mpas_add(bnv2[0], mpas_mul(bnv2[k], pressure_weight));
            usqj[0] = mpas_add(usqj[0], mpas_mul(usqj[k], pressure_weight));
        }
    }
    ldrag = ldrag || bnv2[0] <= 0.0f || ulow == 1.0f || var2d[cell] <= 0.0f;
    for (int kf = 2; kf <= nlev; ++kf) {
        if (kf < kbl) usqj[kf - 1] = usqj[0];
    }

    float bnv = 0.0f;
    float fr = 0.0f;
    float xn = 0.0f;
    float yn = 0.0f;
    if (!ldrag) {
        bnv = mpas_sqrt(bnv2[0]);
        fr = mpas_mul(mpas_mul(mpas_mul(bnv, rulow), var2d[cell]), od);
        fr = mpas_min(fr, 10.0f);
        xn = mpas_mul(ubar, rulow);
        yn = mpas_mul(vbar, rulow);
    }

    float coefm = 0.0f;
    float taub = 0.0f;
    if (!ldrag) {
        float efact = gfk_pow(mpas_add(oa, 2.0f), mpas_mul(0.8f, fr));
        efact = mpas_min(mpas_max(efact, 0.0f), 10.0f);
        coefm = gfk_pow(mpas_add(1.0f, ol), mpas_add(oa, 1.0f));
        const float xlinv = mpas_div(coefm, dx);
        const float tem = mpas_mul(mpas_mul(fr, fr), oc1[cell]);
        const float gfobnv = mpas_div(
            tem, mpas_mul(mpas_add(tem, 0.5f), bnv));
        taub = mpas_mul(xlinv, rhobar);
        taub = mpas_mul(taub, ulow);
        taub = mpas_mul(taub, ulow);
        taub = mpas_mul(taub, ulow);
        taub = mpas_mul(mpas_mul(taub, gfobnv), efact);
    }
    for (int kf = 1; kf <= nlev; ++kf) {
        if (kf <= kbl) taup[kf - 1] = taub;
    }

    bool icrilv = false;
    for (int kf = 2; kf < nlev; ++kf) {
        const int k = kf - 1;
        const int kp1 = k + 1;
        float brvf = 0.0f;
        if (kf >= kbl) {
            icrilv = icrilv || usqj[k] < 0.25f || velco[k] <= 0.0f;
            brvf = mpas_sqrt(mpas_max(bnv2[k], 1.0e-5f));
        }
        if (kf >= kbl && !ldrag && !icrilv && taup[k] > 0.0f) {
            const float temv = mpas_div(1.0f, velco[k]);
            float tem1 = mpas_div(coefm, dxy);
            tem1 = mpas_mul(tem1, mpas_add(rho[kp1], rho[k]));
            tem1 = mpas_mul(tem1, brvf);
            tem1 = mpas_mul(tem1, velco[k]);
            tem1 = mpas_mul(tem1, 0.5f);
            float hd = mpas_sqrt(mpas_div(taup[k], tem1));
            const float fro = mpas_mul(mpas_mul(brvf, hd), temv);
            const float tem2 = mpas_sqrt(usqj[k]);
            const float tem = mpas_add(1.0f, mpas_mul(tem2, fro));
            const float rim = mpas_div(
                mpas_mul(usqj[k], mpas_sub(1.0f, fro)), mpas_mul(tem, tem));
            if (rim <= 0.25f) {
                const float temc = mpas_add(2.0f, mpas_div(1.0f, tem2));
                hd = mpas_div(
                    mpas_mul(velco[k],
                        mpas_sub(mpas_mul(2.0f, mpas_sqrt(temc)), temc)),
                    brvf);
                taup[kp1] = mpas_mul(mpas_mul(tem1, hd), hd);
            } else {
                taup[kp1] = taup[k];
            }
        }
    }

    if (!ldrag) {
        int kblk = 0;
        float fbdpe = 0.0f;
        float zblk = 0.0f;
        for (int kf = nlev; kf >= 2; --kf) {
            if (kblk == 0 && kf <= kbl) {
                const int k = kf - 1;
                float contribution = mpas_mul(
                    bnv2[k], mpas_sub(zmid[(kbl - 1) * ncells + cell],
                        zmid[k * ncells + cell]));
                contribution = mpas_mul(contribution, delta_p[k]);
                contribution = mpas_div(contribution, gravity);
                contribution = mpas_div(contribution, rho[k]);
                fbdpe = mpas_add(fbdpe, contribution);
                const float fbdke = mpas_mul(0.5f,
                    mpas_add(mpas_mul(u1[k], u1[k]), mpas_mul(v1[k], v1[k])));
                if (fbdpe >= fbdke) {
                    kblk = kf < kbl ? kf : kbl;
                    zblk = mpas_sub(zmid[(kblk - 1) * ncells + cell], zmid[cell]);
                }
            }
        }
        if (kblk != 0) {
            const float fbdcd = mpas_max(
                mpas_sub(2.0f, mpas_div(1.0f, od)), 0.0f);
            float value = mpas_mul(0.5f, rhobar);
            value = mpas_mul(value, coefm);
            value = mpas_div(value, mpas_mul(dx, dx));
            value = mpas_mul(value, fbdcd);
            value = mpas_mul(value, dxyp);
            value = mpas_mul(value, olp);
            value = mpas_mul(value, zblk);
            value = mpas_mul(value, mpas_mul(ulow, ulow));
            taufb[0] = value;
            const float tautem = mpas_div(taufb[0], (float)(kblk - 1));
            for (int kf = 2; kf <= kblk; ++kf)
                taufb[kf - 1] = mpas_sub(taufb[kf - 2], tautem);
            for (int k = 0; k <= nlev; ++k)
                taup[k] = mpas_add(taup[k], taufb[k]);
        }
    }

    for (int k = 0; k < nlev; ++k) {
        taud[k] = mpas_div(
            mpas_mul(mpas_sub(taup[k + 1], taup[k]), gravity), delta_p[k]);
    }
    float dtfac = 1.0f;
    for (int kf = 1; kf < nlev; ++kf) {
        const int k = kf - 1;
        if (kf <= kbl && taud[k] != 0.0f) {
            const float limiter = mpas_abs(
                mpas_div(velco[k], mpas_mul(dt, taud[k])));
            dtfac = mpas_min(dtfac, limiter);
        }
    }

    float surface_u = 0.0f;
    float surface_v = 0.0f;
    for (int k = 0; k < nlev; ++k) {
        const int i = k * ncells + cell;
        taud[k] = mpas_mul(taud[k], dtfac);
        const float du = mpas_mul(taud[k], xn);
        const float dv = mpas_mul(taud[k], yn);
        dtaux3d[i] = mpas_add(mpas_mul(du, 1.0f), mpas_mul(dv, 0.0f));
        dtauy3d[i] = mpas_add(mpas_mul(-du, 0.0f), mpas_mul(dv, 1.0f));
        surface_u = mpas_add(surface_u, mpas_mul(du, delta_p[k]));
        surface_v = mpas_add(surface_v, mpas_mul(dv, delta_p[k]));
        rublten_out[i] = mpas_add(mpas_add(rublten_in[i], mpas_mul(du, 1.0f)), mpas_mul(dv, 0.0f));
        rvblten_out[i] = mpas_add(mpas_sub(rvblten_in[i], mpas_mul(du, 0.0f)), mpas_mul(dv, 1.0f));
        rubldiff[i] = mpas_sub(rublten_out[i], rublten_in[i]);
        rvbldiff[i] = mpas_sub(rvblten_out[i], rvblten_in[i]);
    }
    const float stress_u = mpas_mul(mpas_div(-1.0f, gravity), surface_u);
    const float stress_v = mpas_mul(mpas_div(-1.0f, gravity), surface_v);
    dusfcg[cell] = mpas_add(mpas_mul(stress_u, 1.0f), mpas_mul(stress_v, 0.0f));
    dvsfcg[cell] = mpas_add(mpas_mul(-stress_u, 0.0f), mpas_mul(stress_v, 1.0f));
}

